const DECK_REACT_EXTRA = [
  { id: 'rx1',
    q: 'Когда useReducer объективно лучше useState? Приведи критерии, а не вкусовщину.',
    a: `<h4>Коротко</h4>
<p>Критерий не «много полей», а <strong>связанность переходов</strong>: следующее состояние зависит от предыдущего и от типа события, а одно действие меняет сразу несколько полей согласованно. Когда поля независимы и обновляются по одному — <code>useState</code>.</p>

<h4>Как это работает</h4>
<p><code>dispatch(action)</code> не вызывает редьюсер сразу: он кладёт action в очередь обновлений этого хука на фибере и планирует рендер. На рендере React проходит очередь от базового состояния и применяет редьюсер по одному экшену. Поэтому три <code>dispatch</code> подряд в одном обработчике дают три последовательных перехода, а не три перезаписи одним значением — в отличие от <code>setState(value)</code>, где выиграет последний вызов.</p>
<p>Есть оптимизация eager state: если очередь пуста, React вызывает редьюсер прямо в момент <code>dispatch</code> и сравнивает результат с текущим состоянием через <code>Object.is</code>. Совпало — рендер не планируется вообще. Отсюда практическое правило: редьюсер обязан вернуть <strong>тот же объект</strong>, если переход ничего не поменял.</p>
<p><code>dispatch</code> стабилен по ссылке всё время жизни компонента. Его безопасно класть в зависимости эффектов, отдавать через контекст и передавать в мемоизированных детей без <code>useCallback</code>.</p>

<h4>Почему так</h4>
<p>Редьюсер выносит логику переходов из компонента в чистую функцию: её тестируешь без рендера, логируешь целиком (action + prev + next) и вызываешь из нескольких мест без дублирования. Главный выигрыш — моделирование домена: размеченное объединение по <code>status</code> делает невозможные комбинации (<code>loading: true</code> одновременно с <code>error</code>) непредставимыми на уровне типов, а не «не встречающимися на практике».</p>
<p>Платим индирекцией: чтобы понять, что делает кнопка, идёшь в другой файл. Плюс больше кода на простых случаях и менее точная типизация отдельного поля.</p>

<h4>Подводные камни</h4>
<ul>
<li>Мутация в редьюсере: <code>state.items.push(x); return state</code> — ссылка та же, React не перерисует ничего.</li>
<li>Побочные эффекты внутри редьюсера (запрос, отправка аналитики): в StrictMode редьюсер вызывается дважды, эффект задвоится.</li>
<li>Тяжёлый начальный стейт считают в теле компонента вместо третьего аргумента <code>useReducer(reducer, arg, init)</code> — расчёт идёт на каждый рендер.</li>
<li>Редьюсер, объявленный внутри компонента, замыкает пропсы. Это работает, но делает «чистую функцию» непроверяемой в отрыве от рендера.</li>
<li>Один булев флаг в редьюсере — оверинжиниринг, а не архитектура.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем это отличается от Redux?</strong> Состояние локально, нет middleware, devtools, селекторов и подписки по частям: при выносе в контекст любое изменение будит всех потребителей. <strong>Как редьюсеру узнать пропсы?</strong> Класть их в экшен или объявлять редьюсер внутри компонента — <code>dispatch</code> при этом остаётся стабильным.</p>`,
    code: `// как не надо: независимые флаги, между которыми возможны невалидные пары
const [loading, setLoading] = useState(false);
const [data, setData] = useState<Item[]>([]);
const [error, setError] = useState<string | null>(null);
// забыли setLoading(false) в catch -> на экране одновременно спиннер и ошибка

// как надо: размеченное объединение + один переход на событие
type State =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'ok'; data: Item[] }
  | { status: 'err'; error: string };

type Action =
  | { type: 'fetch' }
  | { type: 'ok'; data: Item[] }
  | { type: 'err'; error: string };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'fetch': return { status: 'loading' };
    case 'ok':    return { status: 'ok', data: action.data };
    case 'err':   return { status: 'err', error: action.error };
    default:      return state;              // та же ссылка -> рендера не будет
  }
}

const [state, dispatch] = useReducer(reducer, { status: 'idle' } as State);`,
    tip: 'Добавь про eager state: при пустой очереди React вызывает редьюсер прямо в dispatch и, если Object.is совпал, рендер не планирует. Поэтому возвращать новый объект «на всякий случай» - это лишние рендеры.' },

  { id: 'rx2',
    q: 'Как построить связку useReducer + Context так, чтобы она не убивала производительность?',
    a: `<h4>Коротко</h4>
<p>Убийца производительности — один провайдер с объектом <code>{ state, dispatch }</code>: он новый на каждом рендере, поэтому просыпаются все потребители, включая те, кому нужен только <code>dispatch</code>. Базовое лечение — два контекста: <code>StateCtx</code> и <code>DispatchCtx</code>. Дальше — дробление по доменам и вынос горячего состояния во внешний стор.</p>

<h4>Как это работает</h4>
<p>Контекст не сравнивает содержимое. React хранит текущее value на объекте контекста; когда провайдер коммитится с новым value, React сравнивает старое и новое через <code>Object.is</code> и, если ссылка изменилась, обходит фиберы-потребители и помечает их к обновлению. Подписка живёт в списке зависимостей на фибере, а не в пропсах — поэтому <code>memo</code> на потребителе <strong>не спасает</strong>: он отсекает обновление по пропсам, а контекст будит компонент в обход этой проверки.</p>
<p><code>dispatch</code> из <code>useReducer</code> стабилен всё время жизни компонента. Значит <code>DispatchCtx</code> получает одну и ту же ссылку навсегда, и его потребители — кнопки, формы, тулбары — не перерисовываются при смене состояния вообще ни разу. Это самая дешёвая половина выигрыша: ноль мемоизации, минус большая часть коммитов.</p>
<p>Второй приём — <code>children</code> как проп. Если провайдер получает <code>children</code> сверху, при его собственном рендере эти элементы не пересоздаются: React видит те же ссылки на элементы и по bailout не спускается в поддерево. Перерисуются только реальные потребители контекста.</p>
<p>Третий уровень — <code>useSyncExternalStore</code>: контекст отдаёт неизменяемую ссылку на стор, а компонент подписывается на срез через селектор. Тогда обновление доходит только до тех, у кого срез реально изменился.</p>

<h4>Почему так</h4>
<p>Контекст проектировался как транспорт для редко меняющихся значений — тема, локаль, текущий пользователь, — а не как стор. Селекторов в нём нет намеренно: они требуют подписки с произвольным сравнением, а это уже другая модель, живущая мимо реконсиляции. Платим за расщепление читаемостью: два провайдера, два хука, и новичок в команде может взять не тот. Плюс ошибка «забыл провайдер» ловится только в рантайме — поэтому хуки-обёртки с явным <code>throw</code>.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>value={{ state, dispatch }}</code> прямо в JSX — новый объект на каждом рендере, вся оптимизация мимо.</li>
<li><code>useMemo</code> на value с забытым полем в зависимостях: потребители видят устаревшие данные, и это молчаливый баг, а не падение.</li>
<li>Провайдер сам рендерит дерево вместо <code>children</code>: любое обновление стейта перерисовывает всё поддерево независимо от контекстов.</li>
<li><code>memo</code> на потребителе как «оптимизация» — не работает, обновление приходит через контекст.</li>
<li>Один god-context на приложение: клик по чекбоксу в сайдбаре перерисовывает таблицу на 500 строк.</li>
<li>Дефолтное значение <code>createContext(null)</code> без проверки в хуке — падение с <code>Cannot read properties of null</code> вместо внятного сообщения.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Почему memo не помогает потребителю контекста?</strong> Потому что контекст обновляет фибер напрямую по списку зависимостей, минуя сравнение пропсов. <strong>Когда пора уходить в Zustand или Redux?</strong> Когда состояние меняется часто, читается точечно и нужны селекторы, middleware или devtools — контекст на такое не рассчитан.</p>`,
    code: `// как не надо: одно значение, новый объект каждый рендер
const Ctx = createContext(null);
<Ctx value={{ state, dispatch }}>{children}</Ctx>   // будит вообще всех

// как надо: два контекста + children пропом
const StateCtx = createContext<State | null>(null);
const DispatchCtx = createContext<React.Dispatch<Action> | null>(null);

export function Provider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(reducer, init);
  return (
    <StateCtx value={state}>
      <DispatchCtx value={dispatch}>{children}</DispatchCtx>
    </StateCtx>
  );
}
// React 19: <Context value={...}> вместо <Context.Provider value={...}>

// хуки-обёртки: понятная ошибка вместо падения на null
export function useAppState() {
  const v = useContext(StateCtx);
  if (v === null) throw new Error('useAppState вне Provider');
  return v;
}`,
    tip: 'Сильный ход - объяснить, почему memo не спасает потребителя контекста: обновление приходит по списку зависимостей на фибере, а не через пропсы. И упомяни, что в React 19 сам Context рендерится как провайдер, а Context.Provider объявлен устаревшим.' },

  { id: 'rx3',
    q: 'Зачем нужен useImperativeHandle и почему им злоупотребляют?',
    a: `<h4>Коротко</h4>
<p><code>useImperativeHandle</code> подменяет то, что родитель увидит в <code>ref</code>: вместо голого DOM-узла — объект с методами, которые компонент сам решил отдать наружу. Уместен для <strong>глаголов</strong> (<code>focus</code>, <code>play</code>, <code>reset</code>, <code>scrollToError</code>) и неуместен для существительных (<code>value</code>, <code>isOpen</code>) — их место в пропсах.</p>

<h4>Как это работает</h4>
<p>Сигнатура <code>useImperativeHandle(ref, createHandle, deps)</code>. React вызывает <code>createHandle</code> и кладёт результат в <code>ref.current</code> на <strong>layout</strong>-фазе коммита: DOM уже мутирован, но браузер ещё не рисовал — тот же проход, что и <code>useLayoutEffect</code>. Практическое следствие: родитель может дёрнуть метод в своём <code>useLayoutEffect</code> или в обработчике, но не во время рендера — там <code>ref.current</code> ещё старый или <code>null</code>.</p>
<p>Если <code>deps</code> изменились, React сначала записывает в ref <code>null</code>, затем присваивает новый хендл. Опустишь <code>deps</code> — хендл пересоздаётся на каждом коммите: обычно безобидно, но если родитель положил метод в зависимости эффекта, эффект будет перезапускаться бесконечно.</p>
<p>В React 19 <code>ref</code> — обычный проп, <code>forwardRef</code> не нужен: компонент просто принимает <code>ref</code> и передаёт его первым аргументом в хук.</p>

<h4>Почему так</h4>
<p>Декларативная модель плохо выражает «сделай прямо сейчас, один раз». Фокус, скролл, <code>play()</code>, открытие нативного <code>&lt;dialog&gt;</code>, сброс неконтролируемой формы — это события во времени, а не состояние. Моделировать их флагом <code>shouldFocus</code> и сбрасывать в эффекте — конечный автомат вокруг одного вызова функции, плюс лишний рендер.</p>
<p>Цена императивного хендла: React не знает про такие вызовы. Они не участвуют в реконсиляции, не воспроизводятся при повторном рендере, не переживают Suspense-переигрывание. Компонент, которым управляют снаружи вызовами, невозможно восстановить из пропсов — а это ломает и SSR, и тесты, и предсказуемость.</p>

<h4>Подводные камни</h4>
<ul>
<li>Через хендл прокидывают <code>setOpen()</code> / <code>setValue()</code>: состояние оказывается в двух местах, поток данных идёт снизу вверх, дебажить нечем.</li>
<li>Вызов метода в <code>useEffect</code> родителя при первом рендере — работает, но конкурирует с восстановлением скролла браузером; для фокуса надёжнее <code>autoFocus</code> или layout-эффект.</li>
<li>Пустой массив <code>deps</code> при том, что хендл замыкает свежие пропсы — методы навсегда видят значения первого рендера.</li>
<li>Хендл создают, но ref может быть <code>null</code>: у родителя всегда <code>ref.current?.focus()</code>, иначе падение при условном рендере.</li>
<li>Отдают наружу <code>{ ...inputRef.current }</code> — спред DOM-узла теряет методы из прототипа.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Когда достаточно обычного ref без хука?</strong> Когда родителю нужен именно DOM-узел и скрывать нечего — обёртка только добавит кода. <strong>Как вызвать метод сразу после монтирования?</strong> В <code>useLayoutEffect</code> родителя: к этому моменту хендл уже присвоен, а браузер ещё не отрисовал кадр.</p>`,
    code: `// как не надо: через хендл прокинули состояние
useImperativeHandle(ref, () => ({ setOpen, setValue }), []);
// родитель дёргает modalRef.current.setOpen(true) — React не видит источник истины

// как надо: только действия, только нужный минимум
type FieldHandle = { focus: () => void; scrollIntoView: () => void };

function Field({ ref, ...props }: Props & { ref?: React.Ref<FieldHandle> }) {
  const inputRef = useRef<HTMLInputElement>(null);
  useImperativeHandle(ref, () => ({
    focus: () => inputRef.current?.focus(),
    scrollIntoView: () => inputRef.current?.scrollIntoView({ block: 'center' }),
  }), []);
  return <input ref={inputRef} {...props} />;   // React 19: ref как обычный проп
}

// родитель: хендл готов уже в layout-фазе
useLayoutEffect(() => { fieldRef.current?.focus(); }, []);`,
    tip: 'Формулировка, которая заходит: императивный хендл уместен для глаголов (focus, play, reset) и неуместен для существительных (value, isOpen). Добавь, что хендл присваивается в layout-фазе коммита - значит доступен в useLayoutEffect родителя, но не во время рендера.' },

  { id: 'rx4',
    q: 'Что изменилось с forwardRef в React 19 и как теперь правильно пробрасывать ref?',
    a: `<h4>Коротко</h4>
<p>В React 19 <code>ref</code> — обычный проп функционального компонента. <code>forwardRef</code> больше не нужен, объявлен устаревшим и будет удалён в следующей мажорной версии; в репозитории React есть codemod. Второе изменение — ref-колбэк теперь может вернуть функцию очистки, и из-за этого стрелки с неявным возвратом стали ошибкой.</p>

<h4>Как это работает</h4>
<p>Раньше <code>ref</code> и <code>key</code> вырезались из пропсов на уровне <code>createElement</code>: до компонента они не доходили, обратиться к <code>props.ref</code> было нельзя, а <code>forwardRef</code> создавал специальный тип элемента, который принимал ref вторым аргументом рендер-функции. В 19 новый JSX-трансформ передаёт <code>ref</code> внутрь пропсов для функциональных компонентов — компонент просто деструктурирует его и вешает на нужный узел. <code>key</code> по-прежнему вырезается, он часть реконсиляции.</p>
<p>Ref-колбэк: React вызывает его с узлом при монтировании. Если колбэк <strong>вернул функцию</strong>, React запомнит её и вызовет при отвязке — вместо повторного вызова колбэка с <code>null</code>. Если не вернул — старое поведение с <code>null</code> сохраняется. Отсюда ловушка: <code>ref={el =&gt; (nodeRef.current = el)}</code> неявно возвращает сам узел, React принимает его за cleanup и падает.</p>
<p>Классовые компоненты не изменились: у них <code>ref</code> остаётся специальным атрибутом и даёт инстанс.</p>

<h4>Почему так</h4>
<p>Обёртка <code>forwardRef</code> стоила дорого в типах и в дереве. Дженерик-компонент через неё нормально не типизировался: <code>forwardRef</code> возвращает не дженерик-функцию, приходилось кастовать результат или объявлять перегрузку модуля. В DevTools появлялся лишний узел <code>ForwardRef</code>, ломались <code>displayName</code> и мемо-обёртки поверх. Убрав слой, React выровнял ref с остальными пропсами.</p>
<p>Cleanup у колбэка появился по той же причине, что и cleanup у эффектов: пара «вызвали с узлом / вызвали с null» асимметрична, и в ветке с <code>null</code> у тебя уже нет доступа к узлу, чтобы отписаться от него. Платим за это несовместимостью: тихо работавший код с неявным возвратом теперь бросает ошибку при обновлении.</p>

<h4>Подводные камни</h4>
<ul>
<li>Стрелка с неявным возвратом в <code>ref</code> — самая частая реальная поломка при апгрейде. Нужны фигурные скобки.</li>
<li>Инлайновый ref-колбэк пересоздаётся каждый рендер: React отвяжет старый (вызовет cleanup) и привяжет новый на каждом коммите. Если внутри создаётся <code>ResizeObserver</code>, оберни в <code>useCallback</code>.</li>
<li>Смешивать <code>forwardRef</code> и новый стиль в одной кодовой базе можно, но тип <code>ComponentPropsWithRef</code> начинает вести себя по-разному — мигрируй целыми модулями.</li>
<li>Библиотеки, собранные под React 18, продолжают экспортировать <code>forwardRef</code>-компоненты: они работают, но предупреждение о депрекейте появится в их коде, а не в твоём.</li>
<li><code>ref</code> в пропсах теперь виден спреду: <code>&lt;div {...props} /&gt;</code> может неожиданно навесить чужой ref.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Почему key не сделали таким же пропом?</strong> Он нужен реконсилятору до создания фибера, компонент про него знать не должен. <strong>Как типизировать проброс?</strong> <code>React.ComponentPropsWithRef&lt;'input'&gt;</code> для обёрток над DOM-элементами — ref подтянется с правильным типом узла.</p>`,
    code: `// React 19
function Input({ ref, ...rest }: React.ComponentPropsWithRef<'input'>) {
  return <input ref={ref} {...rest} />;
}

// ref-колбэк с cleanup
<div ref={(node) => {
  const ro = new ResizeObserver(onResize);
  if (node) ro.observe(node);
  return () => ro.disconnect();
}} />

// ЛОВУШКА: неявный возврат теперь считается cleanup
<div ref={el => (nodeRef.current = el)} />        // ошибка
<div ref={el => { nodeRef.current = el; }} />     // правильно`,
    tip: 'Отдельно отметь ловушку с неявным возвратом в стрелке - это самая частая реальная поломка при апгрейде на React 19. И добавь, почему key остался вырезанным, а ref нет: key нужен реконсилятору раньше, чем существует компонент.' },

  { id: 'rx5',
    q: 'Зачем нужен useId и почему нельзя обойтись Math.random или счётчиком?',
    a: `<h4>Коротко</h4>
<p><code>useId</code> даёт стабильный уникальный идентификатор, <strong>совпадающий на сервере и на клиенте</strong>. В этом весь смысл: <code>Math.random()</code> и глобальный счётчик дают в двух средах разные значения, и гидратация ругается на несовпадение атрибутов. Нужен для связок <code>label</code>/<code>input</code> и ARIA в переиспользуемых компонентах.</p>

<h4>Как это работает</h4>
<p>Идентификатор выводится из <strong>позиции компонента в дереве Fiber</strong>: React накапливает при обходе битовый путь от корня (индекс среди сиблингов, глубина) и кодирует его в строку. Раз дерево на сервере и на клиенте одинаковое, путь одинаковый, значит и id совпадает — без всякой синхронизации значений через сериализованный стейт.</p>
<p>Формат вида <code>«:r1:»</code> намеренно содержит двоеточия — символы, недопустимые в CSS-селекторе без экранирования. Это защита от соблазна писать <code>#\\:r1\\:</code> в стилях или в <code>querySelector</code>. В HTML-атрибуте <code>id</code> двоеточия при этом полностью легальны, и <code>getElementById</code> с ними работает.</p>
<p>Значение стабильно на всё время жизни компонента и не меняется между рендерами. Разные инстансы одного компонента получают разные id, потому что у них разные позиции в дереве. При нескольких React-рутах на одной странице пути совпадут — для этого у <code>createRoot</code> и <code>hydrateRoot</code> есть опция <code>identifierPrefix</code>.</p>

<h4>Почему так</h4>
<p>Альтернатива — прокидывать id пропом сверху — не масштабируется: компонент из дизайн-системы не должен требовать от вызывающего кода уникальности. Модуль-счётчик ломается на SSR, потому что на сервере он общий для всех параллельных запросов и стартовое значение на клиенте другое. Привязка к позиции в дереве — единственный источник, который есть в обеих средах бесплатно.</p>
<p>Цена: id непредсказуем и меняется при перестановке компонента в дереве. Значит он бесполезен как якорь в тестах (в Testing Library ищут по роли и имени, а не по id) и как ключ в URL-хеше.</p>

<h4>Подводные камни</h4>
<ul>
<li>Использовать <code>useId</code> как <code>key</code> в списке: ключ обязан идентифицировать <strong>данные</strong>, а не позицию — иначе при сортировке состояние переедет не туда.</li>
<li>Вызывать хук по разу на каждое поле формы: берут один id и добавляют суффиксы <code>id + '-input'</code>, <code>id + '-hint'</code>.</li>
<li>Забыть <code>identifierPrefix</code> при нескольких рутах или при виджете, встраиваемом в чужую страницу — коллизия id и сломанные <code>aria-describedby</code>.</li>
<li>Пытаться стилизовать по этому id — селектор не сработает без экранирования двоеточий.</li>
<li>Считать, что <code>useId</code> решает проблему уникальности сущностей: он про разметку, не про домен.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Что будет, если всё-таки использовать random?</strong> В dev React напечатает предупреждение о несовпадении гидратации, в проде — тихо перерисует поддерево на клиенте и потеряет серверную разметку. <strong>Нужен ли useId, если SSR нет?</strong> Формально нет, но компонент из библиотеки не знает, где его отрендерят, поэтому дешевле сразу использовать хук.</p>`,
    code: `function PasswordField() {
  const id = useId();
  return (
    <>
      <label htmlFor={id + '-input'}>Пароль</label>
      <input id={id + '-input'} aria-describedby={id + '-hint'} type="password" />
      <p id={id + '-hint'}>Минимум 8 символов</p>
    </>
  );
}
// Для нескольких инстансов приложения на странице задают identifierPrefix у createRoot`,
    tip: 'Объясни механику: id выводится из позиции компонента в дереве Fiber, поэтому детерминирован в обеих средах. И добавь про identifierPrefix в createRoot - без него несколько рутов на странице дадут одинаковые id.' },

  { id: 'rx6',
    q: 'Как ты применяешь useTransition на практике? Что он реально даёт и чего не даёт?',
    a: `<h4>Коротко</h4>
<p><code>useTransition</code> помечает обновление как неприоритетное: React начинает рендер сразу, но готов его бросить, чтобы обработать срочное событие, и потом начать заново. Плюс даёт <code>isPending</code>. Это не debounce и не ускорение кода — это защита ввода от блокировки.</p>

<h4>Как это работает</h4>
<p>Каждому обновлению React присваивает <strong>lane</strong> — приоритет. <code>setState</code> в обработчике клика или ввода попадает в синхронную/дискретную полосу, обновление внутри <code>startTransition</code> — в transition-полосу. Планировщик рендерит transition-работу нарезкой: примерно раз в 5 мс проверяет <code>shouldYield()</code> и отдаёт управление браузеру, чтобы тот успел обработать события и отрисовать кадр.</p>
<p>Если во время такого рендера прилетает срочное обновление, React <strong>выбрасывает незавершённую работу целиком</strong> и начинает рендер заново с новым состоянием. Отсюда требование чистоты: рендер могут вызвать и не закоммитить, побочные эффекты в теле компонента задвоятся.</p>
<p>Прерывание возможно только <strong>между компонентами</strong>. Один компонент рендерится атомарно: <code>filterHuge()</code> на 300 мс внутри одного рендера не прервётся ничем.</p>
<p>Ключевая деталь API: обновление должно быть вызвано <strong>синхронно внутри</strong> колбэка. <code>startTransition(() =&gt; setTimeout(() =&gt; setX(v)))</code> транзишеном не будет — к моменту вызова React уже вышел из области транзишена. В React 19 колбэк может быть async: React держит область до конца всех await внутри, и <code>isPending</code> остаётся true, пока промис не завершится. Это фундамент Actions.</p>

<h4>Почему так</h4>
<p>Синхронный рендер означает, что длинная работа блокирует главный поток и следующий кадр не отрисуется. Пользователь печатает, а буквы появляются через 300 мс. Разделив обновления на срочные и фоновые, React сохраняет отзывчивость ввода, жертвуя свежестью тяжёлой части экрана.</p>
<p>Платим двумя вещами: рендер может выполниться несколько раз (лишняя работа CPU и батарея) и появляется промежуточное состояние, где инпут показывает новое значение, а список — старое. Без индикации <code>isPending</code> это выглядит как залипший UI.</p>

<h4>Подводные камни</h4>
<ul>
<li>Ждать от транзишена ускорения. Если один рендер списка занимает 300 мс, транзишен не поможет — сначала виртуализация и мемоизация.</li>
<li>Оборачивать <code>setQuery</code> инпута — поле начнёт отставать от клавиатуры. В транзишен идёт только производная часть.</li>
<li>Вызов сеттера из колбэка/таймера/await в React 18 — теряется контекст транзишена.</li>
<li>Не показывать <code>isPending</code> — пользователь думает, что клик не сработал.</li>
<li>Оборачивать сетевой запрос ради «дебаунса»: число запросов не изменится.</li>
<li>Побочные эффекты в теле компонента — брошенный рендер выполнит их впустую.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем отличается от setTimeout?</strong> Таймер откладывает старт, транзишен стартует сразу и умеет прерваться — задержки нет, если поток свободен. <strong>Почему isPending иногда мигает?</strong> Потому что при быстрых обновлениях транзишены перезапускаются; для плавности индикатор держат с минимальной длительностью показа.</p>`,
    code: `const [isPending, startTransition] = useTransition();
const [query, setQuery] = useState('');
const [results, setResults] = useState<Item[]>([]);

function onChange(e: React.ChangeEvent<HTMLInputElement>) {
  setQuery(e.target.value);              // срочно: инпут отзывчив
  startTransition(() => {
    setResults(filterHuge(e.target.value)); // неприоритетно, прерываемо
  });
}

// ЛОВУШКА: сеттер вызван асинхронно -> транзишена нет
startTransition(() => {
  setTimeout(() => setResults(filterHuge(v)), 0);   // обычное срочное обновление
});

// React 19: async-actions, isPending держится до конца await
startTransition(async () => {
  const err = await saveName(name);
  if (err) setError(err);
});`,
    tip: 'Уточни, что startTransition НЕ делает обновление debounce - React стартует рендер сразу, просто готов его бросить и начать заново. И добавь, что прерывание возможно только между компонентами: тяжёлая функция внутри одного рендера не прервётся ничем.' },

  { id: 'rx7',
    q: 'useTransition или useDeferredValue — как выбрать?',
    a: `<h4>Коротко</h4>
<p>Механизм у них один — transition-полоса приоритетов. Разница в точке приложения: <code>useTransition</code> берёшь, когда <strong>есть доступ к сеттеру</strong> и можно обернуть само обновление; <code>useDeferredValue</code> — когда значение приходит извне (проп, результат хука, параметр URL) и оборачивать нечего.</p>

<h4>Как это работает</h4>
<p><code>useDeferredValue(value)</code> возвращает отстающую копию. При смене <code>value</code> React делает срочный рендер, в котором хук возвращает <strong>прежнее</strong> значение, а сразу после планирует фоновый рендер с новым. Фоновый прерываем: если <code>value</code> снова изменилось, промежуточное состояние будет пропущено и React отрендерит только последнее. Получается автоматическая «сжимающая» семантика без таймеров.</p>
<p>Сравнение <code>value !== deferred</code> даёт флаг «данные устаревают» — обычно приглушают прозрачность и оставляют старый список кликабельным.</p>
<p><strong>Обязательное условие</strong>: компонент, читающий отложенное значение, должен быть в <code>memo</code>. Иначе при срочном рендере родителя ребёнок перерисуется вместе с ним, отработает тяжёлый рендер синхронно, и весь смысл пропадёт: React отложил проп, но не отложил работу. С React Compiler мемоизация появляется автоматически, но проверять это всё равно нужно в профайлере.</p>
<p>Второй аргумент <code>initialValue</code> (React 19) задаёт, что вернуть на первом рендере — удобно, чтобы стартовать с пустого списка и не рендерить тяжёлое на монтировании.</p>

<h4>Почему так</h4>
<p>Два API нужны потому, что источник обновления бывает не твой. Библиотека роутера или форма отдают готовое значение; чтобы обернуть его в <code>startTransition</code>, пришлось бы лезть внутрь чужого кода. <code>useDeferredValue</code> ставит границу приоритета на <strong>потреблении</strong>, а не на записи.</p>
<p>Цена: у тебя нет <code>isPending</code>, приходится сравнивать вручную; и на экране живут два поколения данных одновременно — заголовок уже новый, таблица ещё старая. Если это данные, где рассинхрон опасен (цена и количество), лучше блокирующий спиннер.</p>

<h4>Подводные камни</h4>
<ul>
<li>Забыть <code>memo</code> на потребителе — самая частая ошибка, эффекта ноль.</li>
<li>Считать хук встроенным debounce для сети: количество запросов он не уменьшает, нужен debounce или <code>AbortController</code>.</li>
<li>Откладывать значение, которое участвует в контролируемом инпуте — поле начнёт «отставать» от клавиатуры.</li>
<li>Строить <code>useDeferredValue</code> поверх объекта, который пересоздаётся каждый рендер: значение всегда новое, отставание вечное.</li>
<li>Использовать оба API на одном потоке данных — приоритеты не складываются, лишний код.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Что выбрать для поиска по вводу?</strong> Если сеттер твой — <code>useTransition</code>, он даёт <code>isPending</code> бесплатно. <strong>Отменит ли React промежуточные значения?</strong> Да: фоновый рендер прерывается новым значением, и промежуточные состояния просто не коммитятся.</p>`,
    code: `function SearchPage({ query }: { query: string }) {   // query приходит пропом
  const deferred = useDeferredValue(query);
  const stale = query !== deferred;
  return (
    <div style={{ opacity: stale ? 0.6 : 1, transition: 'opacity .2s' }}>
      <Results query={deferred} />
    </div>
  );
}
const Results = memo(function Results({ query }: { query: string }) { /* ... */ });

// React 19: initialValue для первого рендера
const deferred = useDeferredValue(query, '');`,
    tip: 'Сильный ответ: назови memo обязательным условием работы useDeferredValue - большинство кандидатов этого не знают и объясняют его как встроенный debounce. Добавь, что оба хука пишут в одну transition-полосу, различается только точка приложения: запись против потребления.' },

  { id: 'rx8',
    q: 'Объясни механику Suspense: что именно его активирует, а что нет?',
    a: `<h4>Коротко</h4>
<p>Suspense — граница, которая ловит приостановку во время <strong>рендера</strong>. Компонент, которому не хватает данных, бросает промис; React откатывает рендер поддерева, коммитит <code>fallback</code> и повторяет попытку после резолва. Всё, что происходит в эффекте или в обработчике события, для Suspense не существует.</p>

<h4>Как это работает</h4>
<p>Механика буквально на исключениях: рендер-функция бросает не Error, а промис (в новом API это делает <code>use()</code>, раньше — библиотеки данных вручную). React ловит бросок в <code>renderWithHooks</code>, помечает ближайшую границу, откатывает частично построенную работу и рендерит вместо поддерева <code>fallback</code>. На промис вешается коллбэк, который планирует повторный рендер (retry) — уже с полосой транзишена, поэтому повтор прерываемый.</p>
<p>Что активирует границу: <code>lazy()</code>, <code>use(promise)</code>, ожидание данных Server Component, стриминг HTML при SSR, <code>&lt;link rel="stylesheet" precedence&gt;</code>. Что <strong>не активирует</strong>: <code>fetch</code> в <code>useEffect</code> с последующим <code>setState</code>, запросы в обработчиках, любая асинхронность вне рендера.</p>
<p>Про коммит и состояние. Если поддерево приостановилось <strong>до первого монтирования</strong>, оно ещё не смонтировано — состояние теряется, при повторе всё рендерится с нуля. Если приостановился уже показанный контент (обновление), React прячет узлы через <code>display: none</code>, вызывает <strong>cleanup layout-эффектов</strong> и показывает fallback — DOM-состояние вроде скролла и позиции курсора при этом сохраняется. Внутри транзишена React вместо фолбэка предпочтёт <strong>оставить старый контент</strong>, пока грузится новый.</p>
<p>При SSR граница задаёт точку разрыва стрима: сервер шлёт fallback в первом чанке, а готовый HTML — потом, вставляя его скриптом на место плейсхолдера. Реавилы батчатся примерно раз в 300 мс, чтобы не мигало.</p>

<h4>Почему так</h4>
<p>Идея — вынести «загрузка» из состояния компонента в структуру дерева. Тогда любой компонент на любой глубине объявляет только свою потребность в данных, а решение о том, что показать во время ожидания, принимается там, где известен макет. Это даёт единый спиннер вместо десяти и убирает <code>isLoading</code> из каждого компонента.</p>
<p>Цена: механика на исключениях требует, чтобы рендер был идемпотентным и дешёвым до точки броска — вся работа до неё выполняется впустую и повторится. Плюс промис нельзя создавать в рендере клиентского компонента: повтор создаст новый промис и получится цикл.</p>

<h4>Подводные камни</h4>
<ul>
<li>«Suspense не показывает fallback» — данные грузятся в <code>useEffect</code>, а не в рендере.</li>
<li>Граница обёрнута вокруг компонента, который сам приостанавливается: чтобы поймать, она должна быть <strong>выше</strong>, а не внутри.</li>
<li>Fallback другой высоты — прыжок макета и просадка CLS; скелет должен повторять размеры.</li>
<li>Границу монтируют внутри списка на каждый элемент — получаешь мигающую мозаику вместо одного плавного перехода.</li>
<li>Layout-эффекты с подписками рвутся при повторной приостановке — обязателен корректный cleanup.</li>
<li>Suspense не ловит ошибки: отклонённый промис летит в Error Boundary, границы нужны обе.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Почему при переходе не показался fallback?</strong> Переход шёл в транзишене — React намеренно держит старый экран. Нужен fallback — либо <code>key</code> на границе, либо не оборачивать переход в транзишен. <strong>Сохранится ли состояние формы под границей?</strong> При первой загрузке нет, при повторной приостановке — да.</p>`,
    code: `// НЕ приостанавливает
function Bad() {
  const [data, setData] = useState(null);
  useEffect(() => { fetchData().then(setData); }, []);
  return data ? <View data={data} /> : null;  // Suspense не увидит
}

// Приостанавливает
function Good({ promise }: { promise: Promise<Data> }) {
  const data = use(promise);                  // Suspense увидит
  return <View data={data} />;
}`,
    tip: 'Фраза-ключ: Suspense видит только то, что происходит во время рендера. Всё, что в эффекте или в хендлере, для него не существует. Второй сильный факт: внутри транзишена React вместо фолбэка оставляет старый контент - именно поэтому фолбэк часто «не показывается».' },

  { id: 'rx9',
    q: 'Что такое Suspense-водопад и как ты его лечишь?',
    a: `<h4>Коротко</h4>
<p>Водопад — запросы, выстроенные последовательно там, где могли идти параллельно. Бывает двух видов: <strong>по данным</strong> (второй запрос реально нуждается в результате первого) и <strong>структурный</strong> (родитель приостановился, дети даже не начали рендериться и потому не начали свои запросы). Первый лечится дедупликацией и префетчем, второй — тем, что запросы стартуют раньше рендера потребителя.</p>

<h4>Как это работает</h4>
<p>Ключ к пониманию — момент старта запроса. В модели Suspense запрос стартует, когда компонент <strong>рендерится</strong>. Пока родитель висит в pending, React не спускается ниже: его дети ещё не существуют как фиберы. Значит любая цепочка «родитель ждёт → ребёнок ждёт» превращается в сумму задержек, даже если данные независимы.</p>
<p>В серверном компоненте то же самое даёт подряд идущий <code>await</code>: <code>await getUser()</code> блокирует функцию до резолва, и <code>getOrders()</code> не будет даже вызван. Достаточно вызвать обе функции без <code>await</code>, чтобы запросы ушли одновременно, а <code>await</code> сделать позже — промис уже в полёте.</p>
<p>Второй приём: <strong>раздать промисы вниз</strong>. Родитель стартует запросы, но не ждёт их, а передаёт промисы в детей, каждый под своей границей <code>Suspense</code>. Тогда стриминг отдаёт готовые куски по мере резолва, а не по порядку в коде.</p>
<p>Третий слой — префетч на уровне роутера: <code>&lt;Link prefetch&gt;</code> в Next тянет RSC-payload сегмента заранее, TanStack Router и React Router дают loader, который стартует параллельно с загрузкой чанка компонента.</p>

<h4>Почему так</h4>
<p>Colocation данных с компонентом — большое удобство: компонент самодостаточен, его можно переставить куда угодно. Расплата в том, что граф зависимостей данных становится известен только по ходу рендера, отсюда последовательность. Роутер-лоадеры решают это обратным компромиссом: данные объявлены на уровне маршрута, стартуют разом, но компонент теряет автономность.</p>
<p>Отдельная цена параллелизации: <code>Promise.all</code> падает целиком при одной ошибке. Если частичный результат приемлем — <code>Promise.allSettled</code> или отдельные границы, чтобы упал только один блок.</p>

<h4>Подводные камни</h4>
<ul>
<li>Подряд идущие <code>await</code> в одном серверном компоненте — самый частый источник, находится глазами за минуту.</li>
<li>Одинаковые запросы из соседних компонентов без дедупликации: в RSC для этого <code>cache()</code>, в клиенте — ключи React Query.</li>
<li>Одна общая граница <code>Suspense</code> вокруг всего: стриминг есть, а пользы нет — контент придёт одним куском по самому медленному запросу.</li>
<li>Плавающий промис без обработчика ошибок: если ребёнок не смонтировался, получаешь unhandled rejection.</li>
<li>Создание промиса в рендере клиентского компонента — новый промис на каждый повтор, бесконечная приостановка.</li>
<li>Ленивый компонент, который сам ходит за данными: сначала грузится чанк, потом стартует fetch — двойная ступенька.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как увидеть водопад?</strong> Вкладка Network, режим водопада: запросы стартуют лесенкой ровно с задержкой на длительность предыдущего. В Next ещё помогает трассировка сервера. <strong>Всегда ли водопад плохо?</strong> Нет: если второй запрос зависит от первого, устранить его нельзя — можно только сократить, объединив в один эндпоинт или отдав данные вместе.</p>`,
    code: `// Водопад: второй await ждёт первого
async function Page() {
  const user = await getUser();
  const orders = await getOrders();   // не зависит от user, но ждёт
  ...
}

// Параллельно
async function Page() {
  const userP = getUser();            // стартуем оба сразу
  const ordersP = getOrders();
  const [user, orders] = await Promise.all([userP, ordersP]);
}

// Стриминг: раздаём промисы вниз, каждый со своей границей
function Page() {
  const userP = getUser();
  const ordersP = getOrders();
  return (
    <>
      <Suspense fallback={<UserSkeleton />}><User p={userP} /></Suspense>
      <Suspense fallback={<OrdersSkeleton />}><Orders p={ordersP} /></Suspense>
    </>
  );
}`,
    tip: 'Различай водопад по данным (неизбежен, лечится дедупликацией и объединением эндпоинтов) и водопад по структуре компонентов (искусственный, лечится стартом промисов выше и границами Suspense). И назови цену параллелизации: Promise.all падает целиком, частичный результат требует allSettled или отдельных границ.' },

  { id: 'rx10',
    q: 'Что такое хук use() и чем он отличается от остальных хуков?',
    a: `<h4>Коротко</h4>
<p><code>use()</code> читает значение из ресурса — промиса или контекста. Уникален тем, что <strong>на него не распространяются правила хуков</strong>: его можно вызывать условно, в ветке <code>if</code>, в цикле, после раннего <code>return</code>. Это единственный такой API в React.</p>

<h4>Как это работает</h4>
<p>Обычный хук занимает слот в связном списке хуков фибера, и порядок вызовов должен совпадать между рендерами — иначе состояние съедет. <code>use()</code> слот не занимает: он ничего не хранит на фибере. Для контекста он просто читает текущее значение с объекта контекста и регистрирует зависимость; для промиса — смотрит на его внутреннее состояние.</p>
<p>С промисом три ветки. <code>fulfilled</code> — вернуть значение синхронно. <code>pending</code> — бросить сам промис: React ловит его, показывает ближайший <code>Suspense</code>-fallback и планирует повтор после резолва. <code>rejected</code> — бросить причину, она летит в ближайший Error Boundary. React <strong>помечает промис</strong> служебными полями (<code>status</code>, <code>value</code>, <code>reason</code>), поэтому при повторном рендере с тем же промисом значение достаётся уже синхронно, без второй приостановки.</p>
<p>Отсюда критичное ограничение: <strong>нельзя создавать промис в рендере клиентского компонента</strong>. Повтор создаст новый объект, у него не будет статуса, компонент приостановится снова — бесконечный цикл. Промис должен приходить из Server Component пропом, из кеша фреймворка, из <code>cache()</code> в RSC или из библиотеки с дедупликацией.</p>

<h4>Почему так</h4>
<p>Правила хуков существуют ради индексации слотов. Раз <code>use()</code> состояния не хранит, ограничение теряет смысл, и React его снял — это позволяет читать разные ресурсы в разных ветках и не поднимать чтение наверх ради формального соблюдения порядка. Вызывать его всё равно можно только в компоненте или хуке: механизм приостановки работает только во время рендера.</p>
<p>Цена: async/await исчезает из клиентского кода, но взамен появляется требование внешнего владения промисом и обязательные две границы — <code>Suspense</code> и Error Boundary. Без Error Boundary отклонённый промис уронит всё дерево.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>use(fetch(url))</code> прямо в клиентском компоненте — бесконечная приостановка.</li>
<li>Промис создан в теле родителя без мемоизации: каждый рендер родителя даёт новый промис и новый цикл загрузки у ребёнка.</li>
<li>Нет Error Boundary — reject превращается в белый экран.</li>
<li>Ожидание, что <code>use()</code> заменит React Query: нет кеша, нет инвалидации, нет ретраев, нет фоновой ревалидации.</li>
<li>Вызов в обработчике события или в эффекте — там нет рендера, приостановиться некуда.</li>
<li>Промис, переданный из Server Component, обязан быть сериализуемым по значению внутри — иначе упадёт на границе.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем <code>use(Context)</code> лучше <code>useContext</code>?</strong> Только возможностью условного вызова; в остальном идентичны. <strong>Где взять стабильный промис на клиенте?</strong> Из <code>useMemo</code> с честными зависимостями, из внешнего кеша или из библиотеки данных — но правильнее поднять создание в серверный компонент.</p>`,
    code: `// Server Component создаёт промис, Client Component его читает
async function Page() {
  const commentsPromise = getComments();   // без await
  return (
    <Suspense fallback={<Spinner />}>
      <Comments promise={commentsPromise} />
    </Suspense>
  );
}

'use client';
function Comments({ promise }: { promise: Promise<Comment[]> }) {
  const comments = use(promise);   // приостановит до резолва
  return <ul>{comments.map(c => <li key={c.id}>{c.text}</li>)}</ul>;
}`,
    tip: 'Подчеркни, что use() можно вызывать условно - это единственный такой API в React, и объясни почему: он не занимает слот в списке хуков фибера. Второй сильный факт: React помечает промис полями status/value, поэтому повторный рендер с тем же промисом не приостанавливается.' },

  { id: 'rx11',
    q: 'Как устроены Server Actions под капотом? Что реально происходит при сабмите?',
    a: `<h4>Коротко</h4>
<p><code>'use server'</code> — это директива для бандлера, а не рантайм-магия. Тело функции остаётся на сервере, а на клиент попадает <strong>ссылка</strong>: строковый id. Вызов такой функции на клиенте — это POST на текущий URL с id в заголовке и сериализованными аргументами в теле. Главный вывод для собеседования: Server Action — публичный HTTP-эндпоинт, а не приватная функция.</p>

<h4>Как это работает</h4>
<p>На сборке бандлер видит директиву и делит модуль надвое. В серверный граф идёт настоящая реализация, регистрируемая в манифесте под id вида <code>«хеш-модуля#имя»</code>. В клиентский бандл вместо тела кладётся прокси, созданный <code>createServerReference</code>: у него есть <code>$$id</code>, а при вызове он сериализует аргументы через RSC-протокол и делает <code>fetch</code>.</p>
<p>Что уходит по сети при сабмите формы: POST на текущий роут, заголовок <code>Next-Action</code> с id, тело — <code>multipart/form-data</code> либо RSC-кодированные аргументы. Сервер по манифесту находит функцию, десериализует аргументы и выполняет.</p>
<p>Ответ — <strong>не JSON, а RSC-payload</strong>: сериализованное возвращаемое значение плюс, если внутри был <code>revalidatePath</code> или <code>revalidateTag</code>, обновлённое дерево серверных компонентов. React мержит это дерево в существующее реконсиляцией: состояние клиентских компонентов, скролл и фокус сохраняются, полной перезагрузки нет.</p>
<p>Вызов автоматически оборачивается в транзишен, поэтому во время выполнения работают <code>isPending</code> из <code>useActionState</code> и <code>useFormStatus</code>. Несколько экшенов одной формы React ставит <strong>в очередь</strong>, а не гонит параллельно — чтобы ревалидации не гонялись между собой.</p>

<h4>Почему так</h4>
<p>Модель убирает ручной слой API: не надо писать роут, DTO, клиентскую обёртку и типы к ней — типы выводятся из самой функции. Возврат RSC-payload вместо JSON даёт мутацию и обновление данных в одном раунд-трипе.</p>
<p>Платим тремя вещами. Эндпоинт публичен и его id лежит в бандле — авторизация обязана быть внутри функции. Аргументы и результат должны быть сериализуемыми: нет функций, классов, Symbol; есть примитивы, простые объекты, массивы, <code>Date</code>, <code>Map</code>, <code>Set</code>, <code>FormData</code>, <code>Promise</code>. И привязка к фреймворку: без RSC-сборки такой код не переносится.</p>

<h4>Подводные камни</h4>
<ul>
<li>Авторизация в родительском серверном компоненте, а не в экшене: страница защищена, экшен — нет, его дёргают напрямую curl-ом.</li>
<li>Права из скрытых полей формы (<code>userId</code>, <code>price</code>, <code>role</code>) — подменяются в DevTools за секунду. Всё чувствительное берётся из сессии.</li>
<li>Возврат объекта с методами или инстанса класса — ошибка сериализации в рантайме, не на сборке.</li>
<li>Ожидание, что после экшена данные обновятся сами: без <code>revalidatePath</code>/<code>revalidateTag</code> в ответе не будет нового дерева.</li>
<li>Экшен, объявленный в клиентском файле, — так нельзя: <code>'use server'</code> живёт в отдельном серверном модуле или в inline-функции серверного компонента.</li>
<li>Тяжёлый экшен без ограничения частоты: это открытый эндпоинт, rate limit нужен как на обычном API.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем это отличается от route handler?</strong> Экшен привязан к рендеру и умеет вернуть обновлённое дерево; route handler — обычный REST-эндпоинт, его удобнее звать из внешних клиентов. <strong>Как защититься от CSRF?</strong> Next проверяет соответствие <code>Origin</code> и <code>Host</code>, но при кастомном прокси конфигурацию <code>allowedOrigins</code> надо задавать явно.</p>`,
    code: `'use server';
import { z } from 'zod';
import { auth } from '@/lib/auth';

const Schema = z.object({ title: z.string().min(3), body: z.string().max(5000) });

export async function createPost(prev: State, formData: FormData): Promise<State> {
  const session = await auth();                     // 1. авторизация ВНУТРИ
  if (!session) return { error: 'Не авторизован' };

  const parsed = Schema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) {                            // 2. валидация ВНУТРИ
    return { fieldErrors: parsed.error.flatten().fieldErrors };
  }
  await db.post.create({ data: { ...parsed.data, userId: session.userId } });
  revalidatePath('/posts');                         // 3. инвалидация кеша
  return { ok: true };
}`,
    tip: 'Обязательно скажи фразу: Server Action - это публичный эндпоинт, а не приватная функция. Это отделяет сеньора от миддла в этой теме. Дальше добавь механику: директива делит модуль на сборке, в клиент уходит id из манифеста, ответ приходит RSC-payload-ом, а не JSON.' },

  { id: 'rx12',
    q: 'Где и как валидировать данные в Server Actions? Что с ошибками валидации на клиенте?',
    a: `<h4>Коротко</h4>
<p>Валидация обязательна <strong>на сервере</strong> — экшен открытый эндпоинт, клиентская проверка это только UX. Схема одна на оба слоя (Zod/Valibot). Ожидаемые ошибки <strong>возвращаем значением</strong>, неожиданные — бросаем. Всё, что связано с правами, берём из сессии, а не из <code>formData</code>.</p>

<h4>Как это работает</h4>
<p>Экшен получает <code>FormData</code> — плоскую структуру строк и файлов. Типов там нет: числа приходят строками, чекбокс отсутствует в теле, если не отмечен, а <code>Object.fromEntries</code> схлопывает множественные значения одного имени в одно. Поэтому парсинг делают через <code>zod</code> с <code>coerce</code> для чисел и дат и через <code>formData.getAll()</code> для мультиселектов.</p>
<p><code>safeParse</code> вместо <code>parse</code>: он возвращает результат вместо исключения, и логика ошибок остаётся линейной, без <code>try/catch</code>. Из <code>error.flatten()</code> получаем <code>fieldErrors</code> — карту «имя поля → массив сообщений», ровно то, что удобно рендерить рядом с инпутом.</p>
<p>Возврат вместо броска принципиален для UX. Брошенное исключение поднимется до <code>error.tsx</code> или Error Boundary и сотрёт весь экран вместе с введёнными данными — за сообщение «минимум 3 символа» это неприемлемо. Возвращённый объект попадает в <code>useActionState</code> и рендерится обычным JSX. Бросаем только то, на что пользователь повлиять не может: упала БД, отвалился внешний сервис.</p>
<p>В стейт обязательно кладём <strong>введённые значения</strong>: без JS страница перерисуется целиком, и без <code>defaultValue</code> из стейта форма очистится.</p>

<h4>Почему так</h4>
<p>Общая схема убирает главный источник расхождений: клиент считает поле валидным, сервер — нет, и пользователь получает необъяснимую ошибку. Разделение «ожидаемое возвращаем, неожиданное бросаем» задаёт границу между доменной логикой и авариями: первое рисуем в форме, второе ловим мониторингом.</p>
<p>Цена: возвращаемый тип экшена становится размеченным объединением, его надо описывать и обрабатывать во всех ветках. Плюс два места, где схема применяется, — при неаккуратной сборке клиентская часть Zod (несколько десятков килобайт) утекает в бандл вместе с серверными правилами.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>Object.fromEntries(formData)</code> для формы с чекбоксами и мультиселектами — молча теряет значения.</li>
<li>Числа без <code>z.coerce.number()</code>: <code>'42'</code> не пройдёт <code>z.number()</code>.</li>
<li>Не вернули <code>values</code> — форма очищается при любой ошибке в no-JS сценарии.</li>
<li>Доверие скрытым полям с ценой или id пользователя — классическая дыра.</li>
<li>Сообщения об ошибках без <code>role="alert"</code> и <code>aria-invalid</code>: скринридер про них не узнает.</li>
<li>Импорт серверной схемы с секретами в клиентский компонент — утечка в бандл.</li>
<li>Одна общая строка ошибки вместо <code>fieldErrors</code>: пользователю непонятно, какое поле чинить.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Где валидировать файлы?</strong> Только на сервере: тип и размер с клиента подделываются, а <code>accept</code> в инпуте — подсказка, не защита. <strong>Как связать серверные ошибки с React Hook Form?</strong> Через <code>setError</code> по ключам <code>fieldErrors</code> после ответа экшена — тогда клиентская и серверная валидация рисуются одинаково.</p>`,
    code: `// схема общая для клиента и сервера
export const PostSchema = z.object({
  title: z.string().min(3, 'Минимум 3 символа'),
  body: z.string().min(1),
});

// сервер: ошибки как возвращаемое значение
const parsed = PostSchema.safeParse(raw);
if (!parsed.success) {
  return {
    fieldErrors: parsed.error.flatten().fieldErrors,
    values: raw,          // чтобы форма не очистилась
  };
}

// клиент
const [state, formAction, isPending] = useActionState(createPost, { values: {} });
<input name="title" defaultValue={state.values?.title} aria-invalid={!!state.fieldErrors?.title} />
{state.fieldErrors?.title && <p role="alert">{state.fieldErrors.title[0]}</p>}`,
    tip: 'Скажи: ожидаемые ошибки возвращаем, неожиданные бросаем. Это простое правило сразу расставляет всё по местам. Добавь практическую деталь: обязательно возвращать введённые значения, иначе без JS форма очистится при первой же ошибке валидации.' },

  { id: 'rx13',
    q: 'Что даёт useActionState и чем он отличается от связки useState + обработчик?',
    a: `<h4>Коротко</h4>
<p><code>useActionState(action, initialState, permalink?)</code> возвращает <code>[state, formAction, isPending]</code> и берёт на себя три вещи, которые раньше писали руками: хранение результата, флаг ожидания и обёртку вызова в транзишен. По сути это <strong>асинхронный редьюсер</strong>: экшен получает предыдущее состояние первым аргументом, а возвращённое значение становится новым.</p>

<h4>Как это работает</h4>
<p>Хук создаёт стабильную функцию <code>formAction</code>. Когда её передают в атрибут <code>action</code> формы, React перехватывает сабмит: собирает <code>FormData</code>, вызывает <code>action(prevState, formData)</code> внутри транзишена, держит <code>isPending</code> до резолва и записывает результат в состояние. Если экшен серверный, между этим уходит POST с id функции и в ответ приходит RSC-payload.</p>
<p>Главное отличие от <code>onSubmit</code> — <strong>прогрессивное улучшение</strong>. До гидратации React подставляет в форму настоящий <code>action</code>-URL, и браузер отправит обычный POST сам. Обработчик <code>onSubmit</code> так не умеет: без JS он просто не существует. Третий аргумент <code>permalink</code> задаёт URL страницы, на которую браузер уйдёт в no-JS сценарии.</p>
<p>Порядок: несколько сабмитов подряд React ставит в очередь и применяет результаты последовательно, поэтому «состояние от старого запроса» не перетрёт свежее. Uncontrolled-форма при успешном сабмите очищается сама — React сбрасывает DOM-форму, если она не была перерендерена другим состоянием.</p>
<p>В React 18 это был <code>useFormState</code> из <code>react-dom</code>; в 19 — <code>useActionState</code> из <code>react</code>, и добавился <code>isPending</code>.</p>

<h4>Почему так</h4>
<p>Модель «состояние = результат последнего экшена» убирает целый класс багов: ручные <code>setLoading(true)</code> с забытым <code>finally</code>, гонки между двумя сабмитами, рассинхрон флага и данных. Форма описывается как чистая функция от одного объекта состояния, и это состояние приходит с того же места, где выполнилась мутация.</p>
<p>Цена: сигнатура экшена становится нестандартной (<code>prevState</code> первым аргументом), и переиспользовать его как обычную функцию уже неудобно — приходится либо игнорировать первый аргумент, либо делать обёртку. И состояние не сбрасывается: сообщение «Сохранено» будет висеть, пока не отправишь форму снова.</p>

<h4>Подводные камни</h4>
<ul>
<li>Экшен передали в <code>onSubmit</code> вместо <code>action</code> — прогрессивное улучшение исчезло, а с ним и половина смысла хука.</li>
<li>Контролируемые поля с <code>value</code>/<code>onChange</code>: автоочистка после успеха не сработает, значения держит React.</li>
<li>Ожидание, что <code>isPending</code> есть и в React 18 — там его нет, статус берут из <code>useFormStatus</code>.</li>
<li>Не сбрасывают состояние успеха, и пользователь видит «Готово» рядом с пустой формой.</li>
<li><code>redirect()</code> внутри экшена: он бросает специальное исключение, поэтому <code>try/catch</code> вокруг него молча съест редирект.</li>
<li>Отсутствие оптимистичности: для мгновенного отклика нужен отдельный <code>useOptimistic</code>.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем отличается от useFormStatus?</strong> <code>useActionState</code> владеет состоянием и вызывается там, где объявлена форма; <code>useFormStatus</code> только читает статус ближайшей формы сверху и живёт внутри неё. <strong>Можно ли без сервера?</strong> Да, любая клиентская async-функция подходит — это про жизненный цикл мутации, не про место исполнения.</p>`,
    code: `'use client';
import { useActionState } from 'react';

const initial = { message: '', fieldErrors: {} as Record<string, string[]> };

export function PostForm() {
  const [state, formAction, isPending] = useActionState(createPost, initial);
  return (
    <form action={formAction}>
      <input name="title" />
      {state.fieldErrors.title && <p role="alert">{state.fieldErrors.title[0]}</p>}
      <button disabled={isPending}>{isPending ? 'Сохраняем...' : 'Сохранить'}</button>
    </form>
  );
}`,
    tip: 'Назови useActionState асинхронным редьюсером - метафора точная и хорошо запоминается интервьюером. И объясни, почему action вместо onSubmit: до гидратации React оставляет форме настоящий action-URL, поэтому она работает без JS.' },

  { id: 'rx14',
    q: 'Как работает useOptimistic и в чём его тонкости?',
    a: `<h4>Коротко</h4>
<p><code>useOptimistic(actualState, updateFn)</code> возвращает <code>[optimisticState, addOptimistic]</code>. Пока идёт транзишен, React рендерит результат применения <code>updateFn</code> к реальному состоянию; как только транзишен завершился — оптимистичный слой <strong>отбрасывается сам</strong>. Хук не хранит состояние, он накладывает временную маску поверх настоящего.</p>

<h4>Как это работает</h4>
<p>React запоминает вызовы <code>addOptimistic</code>, привязанные к текущему транзишену, и на каждом рендере <strong>переигрывает</strong> их поверх свежего <code>actualState</code>: <code>updateFn(actual, payload1)</code>, потом результат с <code>payload2</code> и так далее. Отсюда требование чистоты <code>updateFn</code> — она вызывается многократно.</p>
<p>Когда транзишен завершается — успехом или ошибкой, — список накопленных действий очищается, и компонент рендерит чистое реальное состояние. Поэтому <strong>откат при ошибке бесплатный</strong>: не нужно возвращать старое значение в <code>catch</code>, React просто перестаёт применять маску. По той же причине <code>addOptimistic</code> обязан вызываться <strong>внутри</strong> транзишена или Action — вне его React не знает, когда снимать маску, и вызов не сработает.</p>
<p>Порядок в реальном сценарии: <code>addOptimistic(text)</code> → UI мгновенно показывает элемент с временным id и флагом <code>pending</code> → <code>await createTodo(text)</code> → <code>revalidatePath</code> возвращает свежий список с настоящим id → маска снимается, на экране остаётся серверный элемент. Пользователь не видит подмены, потому что оба рендера происходят в одном коммите.</p>

<h4>Почему так</h4>
<p>Классическая оптимистичность руками — это дублирование состояния: локальная копия, ручной откат в <code>catch</code>, ручная сверка с ответом сервера. Три места, где легко разойтись. Маска поверх источника истины оставляет одну копию данных и делает откат следствием архитектуры, а не кода.</p>
<p>Цена: ты сознательно врёшь пользователю. Если операция часто падает или занимает секунды, оптимистичность вредит — элемент появится и исчезнет, и это выглядит как баг. Плюс задача «показать серверную ошибку рядом с исчезнувшим элементом» решается отдельно, хук про неё ничего не знает.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>addOptimistic</code> вне транзишена — тихо ничего не делает, самая частая жалоба «хук не работает».</li>
<li><code>key={index}</code> в оптимистичном списке: после ревалидации ключи съезжают и React переиспользует не те DOM-узлы.</li>
<li>Мутирующая <code>updateFn</code> (<code>state.push(...)</code>) ломает переигрывание — нужна чистая функция, возвращающая новый массив.</li>
<li>Оптимистичность на длинных операциях: оплата, генерация отчёта, загрузка большого файла — там честный прогресс лучше.</li>
<li>Отсутствие визуального отличия pending-элемента: пользователь считает операцию завершённой и уходит со страницы.</li>
<li>Ожидание, что хук сам покажет ошибку — сообщение придётся вернуть из экшена и отрисовать отдельно.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Что будет при двух быстрых добавлениях подряд?</strong> Оба действия накопятся и переиграются в порядке вызова поверх актуального состояния. <strong>Чем отличается от локального useState для черновика?</strong> <code>useState</code> живёт до явного сброса и требует ручного отката; <code>useOptimistic</code> исчезает сам вместе с транзишеном.</p>`,
    code: `const [optimisticTodos, addOptimistic] = useOptimistic(
  todos,
  (state: Todo[], newText: string) => [
    ...state,
    { id: 'tmp-' + crypto.randomUUID(), text: newText, pending: true },
  ]
);

async function action(formData: FormData) {
  const text = formData.get('text') as string;
  addOptimistic(text);          // внутри Action -> транзишен есть
  await createTodo(text);       // ошибка -> откат сам собой
}

<ul>{optimisticTodos.map(t => (
  <li key={t.id} style={{ opacity: t.pending ? 0.5 : 1 }}>{t.text}</li>
))}</ul>`,
    tip: 'Ключевая мысль: useOptimistic не хранит состояние, он накладывает временный слой поверх реального и переигрывает накопленные действия на каждом рендере. Отсюда и автоматический откат, и требование чистоты updateFn, и правило вызывать addOptimistic только внутри транзишена.' },

  { id: 'rx15',
    q: 'Что такое useFormStatus и почему его нельзя вызвать в самом компоненте формы?',
    a: `<h4>Коротко</h4>
<p><code>useFormStatus</code> из <code>react-dom</code> возвращает <code>{ pending, data, method, action }</code> для ближайшей формы <strong>выше по дереву</strong>. Он читает контекст, который React вешает на <code>&lt;form&gt;</code>, поэтому в компоненте, который сам рендерит эту форму, всегда вернёт <code>pending: false</code>: форма там не выше, а на одном уровне.</p>

<h4>Как это работает</h4>
<p>Когда React перехватывает сабмит формы с функцией в <code>action</code>, он оборачивает вызов в транзишен и публикует статус этого транзишена в специальном контексте, провайдер которого — сам DOM-элемент <code>&lt;form&gt;</code>. Хук — это <code>useContext</code> по этому внутреннему контексту. Контекст в React читается только <strong>сверху вниз</strong>: компонент видит провайдеры своих предков, но не тот, что рендерит сам. Отсюда ограничение — оно не выдумано, а прямое следствие модели.</p>
<p>Значит рабочая схема ровно одна: выделить дочерний компонент (<code>SubmitButton</code>, <code>FormOverlay</code>) и вставить его внутрь <code>&lt;form&gt;</code>.</p>
<p>Поле <code>data</code> — это <code>FormData</code> отправляемой формы, доступная во время запроса: можно показать «Отправляем сообщение для Анны» прямо в кнопке. <code>method</code> и <code>action</code> полезны редко, в основном для аналитики. После завершения все поля возвращаются к <code>null</code>/<code>false</code>.</p>

<h4>Почему так</h4>
<p>Зачем он, если <code>useActionState</code> уже даёт <code>isPending</code>: чтобы компоненты дизайн-системы <strong>не знали о конкретной форме</strong>. Кнопка вставляется в любую форму и блокируется сама — не нужно прокидывать <code>disabled</code> и <code>isPending</code> через три уровня пропсов и не нужно, чтобы каждая форма помнила об этом. Это тот же приём, что и <code>useFormStatus</code>-подобные хуки в UI-китах: связь через дерево, а не через пропсы.</p>
<p>Платим неявностью: поведение кнопки зависит от того, куда её вставили, и это не видно в её сигнатуре. Вне формы хук не падает, а тихо отдаёт <code>pending: false</code> — ошибка не проявится до продакшена.</p>

<h4>Подводные камни</h4>
<ul>
<li>Вызов в компоненте, который рендерит <code>&lt;form&gt;</code> — вечный <code>pending: false</code>. Проверяй это первым делом.</li>
<li>Кнопка с <code>useFormStatus</code>, отрендеренная через портал наружу формы: в DOM она вне, но в React-дереве внутри — здесь как раз сработает, а нативный сабмит нет; нужен атрибут <code>form</code>.</li>
<li>Импорт из <code>react</code> вместо <code>react-dom</code> — хук живёт в рендерере.</li>
<li>Форма без функции в <code>action</code> (обычный <code>onSubmit</code>) — React транзишен не создаёт, статуса нет.</li>
<li>Блокировать кнопку только визуально: <code>disabled</code> обязателен, иначе двойной сабмит по двойному клику.</li>
<li>Показывать <code>data</code> после завершения — она уже <code>null</code>.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сделать оверлей на всю форму во время отправки?</strong> Тем же приёмом: отдельный дочерний компонент внутри формы, читающий <code>pending</code>. <strong>Что если форм несколько?</strong> Хук всегда берёт ближайшую вверх по дереву, вложенные формы в HTML запрещены, так что неоднозначности не возникает.</p>`,
    code: `'use client';
import { useFormStatus } from 'react-dom';

export function SubmitButton({ children }: { children: React.ReactNode }) {
  const { pending, data } = useFormStatus();
  return (
    <button type="submit" disabled={pending} aria-busy={pending}>
      {pending ? 'Отправляем ' + (data?.get('name') ?? '') : children}
    </button>
  );
}

// использование - кнопка ничего не знает о форме
<form action={formAction}>
  <input name="name" />
  <SubmitButton>Отправить</SubmitButton>
</form>`,
    tip: 'Готовый ответ на подвох: если useFormStatus вернул pending false - почти всегда хук вызван в том же компоненте, где объявлен form. Объясни причину через контекст: провайдер стоит на элементе form, а контекст читается только сверху вниз.' },

  { id: 'rx16',
    q: 'Что такое прогрессивное улучшение форм в React 19 / Next и зачем оно нужно в 2026?',
    a: `<h4>Коротко</h4>
<p>Форма работает как обычная HTML-форма, пока JS не загрузился, а после гидратации превращается в SPA-взаимодействие без перезагрузки. React 19 это умеет: <code>&lt;form action={serverAction}&gt;</code> до гидратации отправляется браузером обычным POST, после — перехватывается React. Актуально не ради экзотики, а ради окна между FCP и гидратацией.</p>

<h4>Как это работает</h4>
<p>При SSR React рендерит форму с настоящим атрибутом <code>action</code>, указывающим на URL, и скрытым полем с id серверной функции. Пока бандл грузится и выполняется, нажатие на кнопку даёт нативный POST: сервер выполняет экшен и отдаёт новый HTML целиком. После гидратации React вешает свой обработчик, отменяет нативную отправку и вызывает функцию через RSC-протокол — тот же экшен, тот же результат, но без перезагрузки страницы.</p>
<p>Требования к разметке жёсткие: у каждого поля должен быть <code>name</code> — без JS данные собирает браузер, а не React; значения задаются через <code>defaultValue</code>/<code>defaultChecked</code>, потому что контролируемое <code>value</code> без гидратации никто не выставит; полагаться на <code>onSubmit</code> с <code>preventDefault</code> нельзя; ошибки должны приходить в серверном HTML, а не рисоваться на клиенте.</p>
<p>Окно уязвимости измеримо: на среднем Android по 3G между появлением контента и гидратацией проходят секунды. Клики в этом окне без прогрессивного улучшения теряются молча — пользователь жмёт «Купить» и ничего не происходит.</p>

<h4>Почему так</h4>
<p>Причин четыре, и все прозаичные: медленные сети и слабые устройства; чанк, который не догрузился из-за деплоя или CDN; JS, отключённый корпоративной политикой или расширением; краулеры и превью-боты. SEO и доступность идут бонусом, а не целью.</p>
<p>Цена честная: богатая инлайн-валидация, маски ввода, зависимые поля и многошаговые визарды плохо совместимы с no-JS. Каждый такой сценарий приходится проектировать дважды. Поэтому граница проста: публичные формы (регистрация, поиск, подписка, чекаут) — стоит; админка за логином, где JS всё равно обязателен, — почти никогда.</p>

<h4>Подводные камни</h4>
<ul>
<li>Поле без <code>name</code> — на сервере его просто не будет, и молча.</li>
<li>Контролируемые инпуты «на всякий случай»: без JS форма приходит пустой.</li>
<li>Кнопка <code>type="button"</code> с <code>onClick</code> вместо <code>type="submit"</code> — нативной отправки нет вообще.</li>
<li>Валидация только клиентская: без JS пользователь получит 500 вместо сообщения об ошибке.</li>
<li>Не вернули введённые значения — при ошибке форма очищается, и пользователь вводит всё заново.</li>
<li>Проверять «работает ли без JS» только выключением JS в DevTools: реальный сценарий — JS включён, но ещё не выполнился. Тестируй троттлингом CPU и сети.</li>
<li>Забыть <code>required</code> и <code>type="email"</code>: браузерная валидация — бесплатное прогрессивное улучшение.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как показать ошибку без JS?</strong> Экшен возвращает состояние, страница перерисовывается на сервере, ошибка приходит в HTML. <strong>Что делает третий аргумент useActionState?</strong> <code>permalink</code> задаёт URL, куда браузер уйдёт при no-JS сабмите — нужен, если форма живёт на странице, которую нельзя перерисовать целиком.</p>`,
    code: `// работает без JS: обычный POST, ответ - серверный HTML с ошибками
export function Subscribe() {
  const [state, formAction] = useActionState(subscribe, { error: null });
  return (
    <form action={formAction}>
      <input name="email" type="email" required defaultValue={state.email} />
      {state.error && <p role="alert">{state.error}</p>}
      <SubmitButton>Подписаться</SubmitButton>
    </form>
  );
}
// required и type="email" - это тоже прогрессивное улучшение: браузерная валидация бесплатно`,
    tip: 'Хороший ход - переформулировать задачу: это не про пользователей с выключенным JS, а про окно между FCP и гидратацией, где клики теряются молча. И назови цену: контролируемые поля с инлайн-валидацией и no-JS - разные подходы, их приходится проектировать дважды.' },

  { id: 'rx17',
    q: 'Что React 19 принёс для метаданных документа и ресурсов? Заменяет ли это react-helmet?',
    a: `<h4>Коротко</h4>
<p>React 19 умеет <strong>хостить теги</strong>: <code>&lt;title&gt;</code>, <code>&lt;meta&gt;</code>, <code>&lt;link&gt;</code>, отрендеренные в любом месте дерева, автоматически всплывают в <code>&lt;head&gt;</code> — и при SSR, и на клиенте. Для типовых случаев это закрывает react-helmet без библиотеки, но приоритизации конфликтующих тегов, как в Helmet, здесь нет.</p>

<h4>Как это работает</h4>
<p>Рендерер знает список «поднимаемых» типов элементов. Встретив их в дереве, он не создаёт узел на месте, а вставляет его в <code>document.head</code> и дедуплицирует: <code>&lt;link rel="stylesheet" href&gt;</code> и <code>&lt;script async src&gt;</code> — по <code>href</code>/<code>src</code>, поэтому один и тот же стиль, отрендеренный десятком компонентов, окажется в head один раз. При SSR теги попадают в head потока до того, как отдастся тело.</p>
<p>Стили с <code>precedence</code> дают больше. React управляет порядком вставки по значению precedence (например <code>reset</code> → <code>default</code> → <code>high</code>), а главное — на клиенте <strong>ждёт загрузки таблицы стилей перед коммитом</strong>. Это убирает вспышку нестилизованного контента при ленивой подгрузке компонента со своим CSS. Такой стиль также приостанавливает ближайший <code>Suspense</code>.</p>
<p>Императивные API из <code>react-dom</code> дополняют картину: <code>preload</code> (положить в кеш), <code>preinit</code> (загрузить и выполнить/применить), <code>preconnect</code>, <code>prefetchDNS</code>. Они превращаются в соответствующие <code>&lt;link rel&gt;</code> в head и позволяют начать загрузку шрифта или скрипта до того, как компонент отрендерится.</p>

<h4>Почему так</h4>
<p>Раньше head жил вне React-дерева, и любая библиотека была слоем побочных эффектов: собрать теги в контексте, отрендерить, вручную синхронизировать при размонтировании, отдельно сериализовать для SSR. Переезд внутрь рендерера убирает этот слой и, что важнее, позволяет связать ресурсы с коммитом — ожидание CSS перед показом контента без встроенной поддержки не сделать вообще.</p>
<p>Цена — отсутствие детерминированной приоритизации. Если два компонента отрендерят разный <code>&lt;title&gt;</code>, победит последний по порядку коммита, а не «самый вложенный». Плюс поднимаются не все теги: <code>&lt;base&gt;</code>, <code>&lt;noscript&gt;</code> и часть <code>&lt;meta&gt;</code> с особой семантикой лучше держать в шаблоне.</p>

<h4>Подводные камни</h4>
<ul>
<li>Два <code>&lt;title&gt;</code> в разных ветках — недетерминированный результат при стриминге.</li>
<li><code>&lt;link rel="stylesheet"&gt;</code> без <code>precedence</code> не дедуплицируется и не участвует в ожидании загрузки — половина пользы теряется.</li>
<li>Динамический <code>href</code>, меняющийся каждый рендер: React будет вставлять новые теги вместо переиспользования.</li>
<li>Ожидание, что это работает в Server Components Next для SEO: краулеры получают head из стрима, и <code>generateMetadata</code> надёжнее.</li>
<li><code>preload</code> шрифта без <code>crossOrigin: 'anonymous'</code> — браузер загрузит файл дважды.</li>
<li>Хостинг тегов внутри компонента, который рендерится в списке, — десять одинаковых <code>&lt;meta&gt;</code>, если у них нет дедупликации по href.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Так react-helmet больше не нужен?</strong> Для простых случаев нет; если нужны правила «дочерний перекрывает родительский» и шаблоны заголовков — библиотека или API фреймворка. <strong>Почему в Next всё равно metadata?</strong> Он вычисляется до рендера дерева и попадает в самое начало стрима, а хостинг тегов зависит от того, когда компонент отрендерится.</p>`,
    code: `function Article({ post }: { post: Post }) {
  return (
    <article>
      <title>{post.title} — Блог</title>
      <meta name="description" content={post.excerpt} />
      <link rel="canonical" href={'https://site.ru/posts/' + post.slug} />
      <link rel="stylesheet" href="/article.css" precedence="default" />
      <h1>{post.title}</h1>
    </article>
  );
}

import { preload, preinit } from 'react-dom';
preload('/fonts/inter.woff2', { as: 'font', type: 'font/woff2', crossOrigin: 'anonymous' });`,
    tip: 'Отметь нюанс: в Next App Router нативный metadata API остаётся предпочтительным, потому что он участвует в стриминге head раньше, чем отрендерятся компоненты. И назови главное ограничение React 19 против Helmet - нет приоритизации конфликтующих тегов, побеждает последний по порядку коммита.' },

  { id: 'rx18',
    q: 'Что такое Actions в React 19 как концепция, а не набор хуков?',
    a: `<h4>Коротко</h4>
<p>Action — это соглашение, а не хук: <strong>асинхронная функция, выполненная внутри транзишена</strong>. За счёт этого она бесплатно получает pending-состояние, очередь вызовов и снятие оптимистичных обновлений по завершении. Фундамент — то, что в React 19 <code>startTransition</code> принимает async-функции.</p>

<h4>Как это работает</h4>
<p>До 19-й версии транзишен заканчивался в момент выхода из синхронного колбэка. Теперь React держит «область транзишена» до завершения всех <code>await</code> внутри async-функции: обновления состояния, случившиеся после await, всё ещё принадлежат тому же транзишену. Отсюда и <code>isPending</code>, живущий до конца сетевого запроса, и автоматическое снятие маски <code>useOptimistic</code>.</p>
<p>Поверх этого стоит вся остальная поверхность API: <code>&lt;form action={fn}&gt;</code> — сабмит запускает Action; <code>useActionState</code> — Action как асинхронный редьюсер; <code>useFormStatus</code> — чтение статуса ближайшей формы; <code>useOptimistic</code> — временный слой поверх состояния; атрибут <code>formAction</code> на кнопке — несколько экшенов в одной форме (сохранить черновик и опубликовать).</p>
<p>Ещё одна встроенная гарантия — <strong>очередь</strong>. Несколько Action-ов подряд React выполняет последовательно, а не параллельно: два быстрых клика по «Сохранить» не приведут к гонке, где ответ первого запроса приходит после второго и затирает свежие данные.</p>
<p>Что уходит из кода: ручные <code>isLoading</code>, <code>error</code>, <code>try/catch/finally</code>, ручной сброс uncontrolled-формы после успеха, ручной откат оптимистики.</p>

<h4>Почему так</h4>
<p>Мутация — это цикл с одинаковой структурой: заблокировать UI, отправить, показать результат, разблокировать, откатить при ошибке. Раньше каждый разработчик писал этот цикл заново и по-разному, забывая <code>finally</code> и отмену устаревших ответов. Actions переносят цикл в рантайм и делают его частью модели приоритетов, а не прикладного кода.</p>
<p>Цена: неявность. Из чтения компонента не видно, что вызов уже обёрнут в транзишен и поставлен в очередь; отладка проблем с приоритетами становится сложнее. Плюс последовательное выполнение — не всегда то, что нужно: массовые независимые операции придётся запускать вручную параллельно.</p>

<h4>Подводные камни</h4>
<ul>
<li>Считать Actions серверной фичей. Обычная клиентская async-функция с <code>fetch</code> — полноценный Action; Server Actions лишь частный случай по месту исполнения.</li>
<li>Обновление состояния, вызванное из <code>setTimeout</code> внутри Action, выпадает из транзишена.</li>
<li><code>try/catch</code> вокруг <code>redirect()</code> в Next: редирект реализован броском исключения, catch его проглотит.</li>
<li>Ожидание параллельности: очередь Action-ов сериализует вызовы, массовое удаление 50 строк по одному экшену будет медленным.</li>
<li>Ошибка, брошенная из Action без Error Boundary, уронит поддерево.</li>
<li>Смешение <code>onSubmit</code> и <code>action</code> на одной форме — двойная отправка.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем Action отличается от обычного async-обработчика?</strong> Транзишеном: приоритет, очередь, pending и связь с оптимистичными обновлениями. <strong>Нужен ли Next, чтобы этим пользоваться?</strong> Нет — всё, кроме Server Actions, работает в обычном SPA на React 19.</p>`,
    code: `// Action без всякого сервера
function Profile() {
  const [error, submit, isPending] = useActionState(
    async (_prev: string | null, formData: FormData) => {
      const res = await fetch('/api/name', { method: 'POST', body: formData });
      if (!res.ok) return 'Не удалось сохранить';
      return null;
    },
    null
  );
  return (
    <form action={submit}>
      <input name="name" />
      <button disabled={isPending}>Сохранить</button>
      {error && <p role="alert">{error}</p>}
    </form>
  );
}`,
    tip: 'Проведи границу явно: Actions - это про транзишены и жизненный цикл мутации, Server Actions - про то, где код исполняется. Их часто смешивают. Добавь малоизвестную гарантию: Action-ы выполняются очередью, поэтому два быстрых сабмита не устроят гонку ответов.' },

  { id: 'rx19',
    q: 'Как работает React Compiler? Что он делает с кодом?',
    a: `<h4>Коротко</h4>
<p>React Compiler — плагин к Babel/SWC, который на сборке анализирует компоненты и хуки и <strong>вставляет мемоизацию за тебя</strong>. В компонент добавляется массив-кеш (внутренний хук <code>useMemoCache</code>), где по слотам лежат вычисленные значения и их входы. Он убирает каскадные ререндеры из-за нестабильных ссылок, но не ускоряет сами вычисления.</p>

<h4>Как это работает</h4>
<p>Пайплайн: код разбирается в HIR (промежуточное представление в форме SSA), дальше идут анализ псевдонимов и мутаций (кто на что ссылается и кто что меняет), вывод реактивных зависимостей (какие значения зависят от пропсов и состояния), формирование «реактивных блоков» и кодогенерация.</p>
<p>Что получается на выходе: для каждого вычисляемого значения — проверка вида «изменились ли входы по <code>Object.is</code>; если нет, взять из слота кеша». То же самое делается для <strong>элементов JSX</strong>: <code>&lt;List items={items} /&gt;</code> кешируется как объект-элемент, и при неизменных пропсах реконсилятор увидит ту же ссылку и не пойдёт в поддерево. Именно этого ручная мемоизация почти никогда не делает — руками пишут <code>useMemo</code> вокруг вычислений, а не вокруг кусков разметки.</p>
<p>Размер кеша фиксируется на сборке (<code>useMemoCache(4)</code>), это обычный массив на фибере — по стоимости примерно как несколько лишних <code>useRef</code>. В бандл добавляется немного кода на компонент; в обмен уходят ручные <code>useMemo</code>/<code>useCallback</code>.</p>
<p>Компилятор консервативен: если доказать безопасность не удалось, он <strong>пропускает компонент целиком</strong>, а не генерирует рискованный код.</p>

<h4>Почему так</h4>
<p>Ручная мемоизация плоха тем, что это работа наоборот: разработчик оптимизирует там, где заметил тормоза, а не там, где они есть; массивы зависимостей пишутся руками и потому расходятся с телом функции; <code>memo</code> ставят на компонент, забывая, что проп-колбэк всё равно новый. Компилятор мемоизирует по умолчанию везде, где это доказуемо безопасно, и не ошибается в зависимостях.</p>
<p>Платим тремя вещами: сборка становится медленнее; сгенерированный код труднее читать в дебаггере; и появляется зависимость от того, насколько твой код соответствует правилам React — иначе компонент молча выпадет из оптимизации.</p>

<h4>Подводные камни</h4>
<ul>
<li>Ждать ускорения тяжёлого рендера: 5000 DOM-узлов лечит виртуализация, а не компилятор.</li>
<li>Считать, что теперь можно не думать о зависимостях эффектов — эффекты компилятор не трогает.</li>
<li>Не проверять отчёт сборки: половина компонентов может быть пропущена, и об этом никто не скажет.</li>
<li>Оставлять ручные <code>useMemo</code> везде — не вредно, но мешает читать код и иногда мешает компилятору.</li>
<li>Нестабильные объекты из сторонних хуков компилятор не чинит: он не видит их внутренностей.</li>
<li>Измерять эффект без профайлера — на приложениях с малым числом ререндеров разницы может не быть вовсе.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Нужен ли теперь memo?</strong> Для компонентов внутри скомпилированного кода — почти нет; для границ с чужими библиотеками и для измеренных горячих мест остаётся. <strong>Как проверить, что компонент оптимизирован?</strong> Через eslint-плагин, отчёт компилятора и бейдж в React DevTools рядом с именем компонента.</p>`,
    code: `// вы пишете так
function Cart({ items, onRemove }) {
  const total = items.reduce((s, i) => s + i.price, 0);
  return <List items={items} total={total} onRemove={onRemove} />;
}

// компилятор генерирует примерно это
function Cart({ items, onRemove }) {
  const $ = useMemoCache(4);
  let total;
  if ($[0] !== items) {
    total = items.reduce((s, i) => s + i.price, 0);
    $[0] = items; $[1] = total;
  } else { total = $[1]; }
  // ... аналогично кешируется JSX-элемент
}`,
    tip: 'Скажи, что компилятор мемоизирует части JSX, а не только вычисления - это то, чего ручной useMemo практически не делает. И сразу очерти границу: он убирает лишние ререндеры, но не ускоряет тяжёлый рендер и не трогает эффекты.' },

  { id: 'rx20',
    q: 'Что ломает React Compiler и когда он отказывается оптимизировать компонент?',
    a: `<h4>Коротко</h4>
<p>Надо различать две ситуации. <strong>Bail out</strong> — компилятор не смог доказать безопасность и пропустил компонент: производительность как была, ничего не сломалось. И <strong>изменение поведения</strong> — код случайно полагался на то, что объект пересоздаётся каждый рендер; теперь ссылка стабильна, и что-то перестало срабатывать. Второе — не баг компилятора, а проявившийся баг кода.</p>

<h4>Как это работает</h4>
<p>На этапе анализа компилятор проверяет, можно ли считать рендер чистым. Пропуск вызывают: нарушения правил хуков (условный вызов, вызов в цикле); мутация пропсов или значений, пришедших снаружи; чтение и запись <code>ref.current</code> во время рендера; <code>this</code> в теле компонента; синтаксис, который он не разбирает; и явная директива <code>'use no memo'</code>.</p>
<p>Что видно снаружи: eslint-плагин <code>react-hooks</code> с правилами компилятора подсвечивает такие места прямо в редакторе, а сборка умеет выводить список пропущенных компонентов. В React DevTools у оптимизированных компонентов появляется отметка.</p>
<p>Механика поломки на примере. Раньше <code>const opts = { pageSize: 20 }</code> в теле компонента давал новый объект каждый рендер, и <code>useEffect(..., [opts])</code> стрелял на каждом рендере — иногда именно на это и рассчитывали, например чтобы перезапрашивать данные. Компилятор стабилизировал ссылку — эффект теперь срабатывает один раз, и «пропали обновления». Симметричный случай: сравнение <code>prev !== next</code> по ссылке, которое всегда возвращало <code>true</code>, стало возвращать <code>false</code>.</p>

<h4>Почему так</h4>
<p>Консервативность — сознательный выбор: лучше не оптимизировать, чем сгенерировать код с другим поведением. Именно поэтому пропуск не считается ошибкой и не ломает сборку.</p>
<p>А поведенческие расхождения — цена того, что React никогда не гарантировал <strong>количество</strong> рендеров и свежесть ссылок. Код, опиравшийся на «объект новый каждый раз», нарушал модель и раньше; он просто работал по совпадению. Платит за это команда во время внедрения: нужно прогнать регресс и внимательно смотреть на эффекты с объектами в зависимостях.</p>

<h4>Подводные камни</h4>
<ul>
<li>Включить компилятор на всём проекте разом без отчёта о пропусках — не узнаешь, что половина кода не оптимизирована.</li>
<li>Ставить <code>'use no memo'</code> как быстрый фикс и забывать: директива задумана как временная, её надо отслеживать.</li>
<li>Чтение <code>ref.current</code> в рендере ради «оптимизации» — распространённый паттерн, который выбивает компонент из оптимизации целиком.</li>
<li>Эффекты с объектом или массивом в зависимостях: ровно здесь появляются исчезнувшие обновления.</li>
<li>Ожидание, что компилятор починит нестабильные значения из сторонних хуков — он их не видит.</li>
<li>Мутация пропсов «мы же знаем, что это безопасно»: не безопасно и раньше, а теперь ещё и отключает оптимизацию.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как внедрять на большом проекте?</strong> Поэтапно: сначала eslint-правила и исправление нарушений, потом компилятор на отдельных директориях через опцию фильтрации, потом на всём. <strong>Остаётся ли смысл в ручной мемоизации?</strong> Да — на границе с чужими библиотеками, для значений, уходящих в контекст, и в измеренных узких местах.</p>`,
    code: `// компилятор пропустит: мутация пропа
function Bad({ config }) {
  config.mode = 'dark';          // мутация внешнего значения
  return <View config={config} />;
}

// компилятор пропустит: чтение рефа в рендере
function Bad2() {
  const ref = useRef(0);
  return <div>{ref.current}</div>;   // нарушение чистоты
}

// точечное отключение
function Legacy() {
  'use no memo';
  // ...
}`,
    tip: 'Сильная формулировка: компилятор не создаёт баги, он проявляет уже существующие нарушения чистоты рендера. Именно так это и подают в команде React. И разведи два случая явно: bail out - просто нет оптимизации, а изменение поведения - это код, который опирался на нестабильные ссылки.' },

  { id: 'rx21',
    q: 'Зачем StrictMode вызывает эффекты дважды и что именно он проверяет?',
    a: `<h4>Коротко</h4>
<p>В dev StrictMode делает три вещи: двойной вызов рендер-функций (вместе с <code>useMemo</code>, редьюсерами и инициализаторами состояния), двойной цикл эффектов (setup → cleanup → setup) и предупреждения об устаревших API. В проде ничего этого нет. Правильная реакция на «эффект вызвался дважды» — не считать вызовы, а написать корректный cleanup.</p>

<h4>Как это работает</h4>
<p>Двойной рендер проверяет <strong>чистоту</strong>. React вызывает функцию компонента дважды подряд и коммитит результат второго вызова. Если два прогона дают разное — компонент нечист: мутирует внешнюю переменную, пишет в реф во время рендера, читает <code>Date.now()</code> или <code>Math.random()</code>. Это критично именно для конкурентного рендеринга, где React может отрендерить поддерево, выбросить работу и начать заново. Побочные эффекты в теле компонента в такой модели выполняются лишний раз.</p>
<p>Двойной цикл эффектов симулирует <strong>размонтирование и повторное монтирование</strong> сразу после первого монтирования: <code>setup</code>, <code>cleanup</code>, <code>setup</code>. Проверяется, что cleanup симметричен setup-у. Ловятся: неотписанные слушатели, незакрытые WebSocket-ы, неочищенные таймеры и интервалы, подписки на внешние сторы, неотменённые запросы.</p>
<p>Смысл не в занудстве. React движется к фичам вроде <code>&lt;Activity&gt;</code>/Offscreen, где поддерево прячется и показывается заново с сохранением состояния — там повторное монтирование реально произойдёт в проде. Плюс сама модель Suspense уже сегодня может смонтировать компонент, приостановить его и смонтировать снова.</p>
<p>Начиная с React 19 StrictMode в dev ещё и дважды вызывает ref-колбэки и логирует второй проход приглушённо, чтобы консоль не задваивалась.</p>

<h4>Почему так</h4>
<p>Эти ошибки не проявляются в разработке: подписка утекает молча, второй запрос выглядит как «просто дубль в Network». Они всплывают в проде как рост памяти и странные гонки. Дешевле сделать их видимыми сразу и громко.</p>
<p>Цена: шум в консоли, задвоенные запросы в Network при отладке, ложное впечатление «React стал медленнее». Отключать StrictMode из-за этого — обменивать реальные баги на комфорт.</p>

<h4>Подводные камни</h4>
<ul>
<li>Гасить симптом флагом <code>useRef(false)</code> — эффект «перестал двоиться», а утечка осталась и стрельнёт в проде.</li>
<li>Инициализация вне React (аналитика, сокет, карта) в теле компонента, а не в эффекте с cleanup.</li>
<li>Запрос без <code>AbortController</code>: два ответа приходят в непредсказуемом порядке, и старый затирает новый.</li>
<li>Нечистые инициализаторы: <code>useState(() =&gt; nextId++)</code> увеличит счётчик дважды.</li>
<li>Отключить StrictMode «потому что сторонняя библиотека ругается» — сначала обнови библиотеку, это чаще всего её реальный баг.</li>
<li>Считать, что дублирование эффектов есть и в проде — нет, только dev.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как правильно делать запрос в эффекте?</strong> С <code>AbortController</code> и отменой в cleanup — или вообще библиотекой данных, которая дедуплицирует. <strong>Зачем StrictMode, если конкурентность уже работает?</strong> Он готовит код к повторному монтированию: <code>&lt;Activity&gt;</code>, восстановление состояния при навигации назад и Suspense-переигрывание.</p>`,
    code: `// плохо: маскируем симптом
const done = useRef(false);
useEffect(() => {
  if (done.current) return;
  done.current = true;
  fetchData();
}, []);

// хорошо: cleanup делает эффект безопасным
useEffect(() => {
  const ac = new AbortController();
  fetchData({ signal: ac.signal })
    .then(setData)
    .catch(e => { if (e.name !== 'AbortError') setError(e); });
  return () => ac.abort();
}, []);`,
    tip: 'Ключевая фраза: StrictMode не создаёт проблему, он делает видимым отсутствие cleanup. И добавь, что в проде двойного вызова нет, а готовит он код к реальному повторному монтированию - Activity/Offscreen и переигрыванию под Suspense.' },

  { id: 'rx22',
    q: 'Как порталы взаимодействуют с всплытием событий? Куда всплывёт клик из портала?',
    a: `<h4>Коротко</h4>
<p>Портал меняет <strong>место в DOM</strong>, но не место в React-дереве. Синтетическое событие всплывает по React-дереву: клик в модалке, отрендеренной в <code>document.body</code>, придёт в <code>onClick</code> родительского компонента, хотя в DOM они не вложены. Отсюда весь класс багов с «кликом снаружи».</p>

<h4>Как это работает</h4>
<p>React не вешает обработчики на элементы — он слушает на корневом контейнере и <strong>сам восстанавливает путь всплытия</strong>, поднимаясь по цепочке <code>return</code> в дереве фиберов. У портала фибер остаётся ребёнком своего React-родителя, поэтому путь идёт через него, а не через реальных DOM-предков.</p>
<p>Нативное событие при этом всплывает по DOM обычным образом: до <code>document.body</code>, минуя React-родителя. Получается два разных пути для одного клика. Пока весь код на синтетических обработчиках, расхождение незаметно; как только в игру входит <code>document.addEventListener</code>, начинается путаница.</p>
<p>Классический сценарий: меню в портале, закрытие по клику вне через нативный слушатель с проверкой <code>menuRef.current.contains(e.target)</code>. Для DOM клик по меню действительно вне контейнера-кнопки, проверка возвращает <code>false</code>, меню закрывается сразу после открытия. Лечения два: проверять <code>contains</code> и по узлу портала тоже, либо слушать <code>pointerdown</code> в фазе capture и сравнивать с <code>composedPath()</code>.</p>
<p>Второй баг обратный: портал отрисован внутри подложки с <code>onClick={onClose}</code>, и клик по содержимому модалки закрывает её — потому что по React-дереву он туда всплывает. Лечится <code>stopPropagation</code> на контенте или переносом обработчика на саму подложку с проверкой <code>e.target === e.currentTarget</code>.</p>

<h4>Почему так</h4>
<p>Сохранение React-дерева — сознательный компромисс: иначе портал потерял бы контекст, темы, Error Boundary и Suspense-границы, и модалка стала бы изолированным приложением. Разработчик хочет писать её как обычного ребёнка, а переносится только физическое размещение.</p>
<p>Зачем порталы вообще: обход <code>overflow: hidden</code>, ловушек <code>z-index</code> внутри контекстов наложения и <code>transform</code>/<code>filter</code> у предка, который создаёт containing block и ломает <code>position: fixed</code>. В 2026 половину этих задач решает нативный <code>&lt;dialog&gt;</code> с top layer и <code>popover</code>: там стекинг не зависит от предков вообще.</p>

<h4>Подводные камни</h4>
<ul>
<li>Смешивание нативных и синтетических обработчиков в одном сценарии — источник почти всех багов с порталами.</li>
<li>Фокус не переносится в модалку и не возвращается назад: портал сам по себе доступность не даёт, нужна ловушка фокуса и <code>aria-modal</code>.</li>
<li>Портал в <code>document.body</code> при SSR: на сервере <code>document</code> нет, нужен монтирующий эффект или <code>&lt;dialog&gt;</code>.</li>
<li>Скролл фона не блокируется — на iOS особенно заметно.</li>
<li>Несколько порталов подряд без управления слоями: <code>z-index</code>-война между тултипом, дропдауном и модалкой.</li>
<li>Событие <code>scroll</code> и медиа-события не делегируются — их поведение в портале другое.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сделать click-outside правильно?</strong> Слушать <code>pointerdown</code> в capture и проверять <code>composedPath()</code> — он корректно работает и с порталами, и с shadow DOM. <strong>Нужен ли портал при использовании <code>&lt;dialog&gt;</code>?</strong> Обычно нет: top layer выносит элемент над всем содержимым независимо от места в DOM.</p>`,
    code: `function Modal({ children, onClose }: Props) {
  return createPortal(
    <div className="backdrop" onClick={onClose}>
      <div className="dialog" onClick={e => e.stopPropagation()}>
        {children}
      </div>
    </div>,
    document.body
  );
}

// как не надо: нативный listener видит DOM, а не React-дерево
useEffect(() => {
  const h = (e: MouseEvent) => {
    if (!menuRef.current?.contains(e.target as Node)) close();  // портал => contains false
  };
  document.addEventListener('click', h);
  return () => document.removeEventListener('click', h);
}, []);

// как надо: pointerdown в capture + composedPath (работает с порталом и shadow DOM)
useEffect(() => {
  const h = (e: PointerEvent) => {
    const path = e.composedPath();
    if (!path.includes(menuRef.current!) && !path.includes(triggerRef.current!)) close();
  };
  document.addEventListener('pointerdown', h, true);
  return () => document.removeEventListener('pointerdown', h, true);
}, []);`,
    tip: 'Назови конкретный баг с click-outside и порталом - это показывает, что ты писал модалки в проде, а не читал доку. Готовое решение: pointerdown в capture-фазе плюс composedPath вместо contains.' },

  { id: 'rx23',
    q: 'Как устроены синтетические события и что изменилось в React 17+?',
    a: `<h4>Коротко</h4>
<p>React не вешает listener на каждый элемент. Он использует <strong>делегирование</strong>: один набор обработчиков на корневой контейнер, а путь всплытия восстанавливает сам, поднимаясь по дереву фиберов. Событие оборачивается в <code>SyntheticEvent</code> — нормализованную кроссбраузерную обёртку. В React 17 корнем делегирования стал контейнер вместо <code>document</code>, и исчез пулинг событий.</p>

<h4>Как это работает</h4>
<p>При создании корня React вешает на контейнер обработчики почти всех типов событий — и в фазе всплытия, и в фазе перехвата. Когда событие приходит, React по <code>event.target</code> находит соответствующий фибер, собирает цепочку предков вверх по <code>return</code>, формирует список обработчиков и вызывает их в правильном порядке, симулируя capture и bubble. <code>stopPropagation</code> на синтетическом событии останавливает только этот, симулированный путь.</p>
<p><strong>Изменение React 17 — корень вместо document.</strong> Причина не косметическая: пока React слушал на <code>document</code>, две версии React на одной странице конфликтовали, а <code>stopPropagation</code> в стороннем коде между элементом и document не работал — React уже поймал событие выше. Перенос на контейнер сделал возможной постепенную миграцию по частям страницы и корректное сосуществование с не-React виджетами.</p>
<p><strong>Второе изменение — убран пулинг.</strong> Раньше объект события переиспользовался и обнулялся после обработчика, поэтому чтение <code>e.target.value</code> в <code>setTimeout</code> требовало <code>e.persist()</code>. Экономия памяти перестала окупаться в современных движках, и пулинг убрали.</p>
<p>Мелочи, которые спрашивают: <code>onScroll</code> больше не всплывает (соответствует нативному поведению), <code>onFocus</code>/<code>onBlur</code> реализованы через <code>focusin</code>/<code>focusout</code>, а часть событий — media, <code>scroll</code>, <code>load</code>/<code>error</code> на ресурсах — не делегируются и вешаются прямо на узел.</p>

<h4>Почему так</h4>
<p>Делегирование экономит память и время монтирования: вместо тысяч слушателей на большом списке — десятки на корне. Обёртка <code>SyntheticEvent</code> нормализует различия браузеров и даёт стабильные поля вроде <code>e.key</code> и <code>relatedTarget</code>.</p>
<p>Цена — расхождение с нативной моделью. Порядок относительно нативных слушателей неочевиден: слушатель, повешенный прямо на элемент, отработает <strong>раньше</strong> React-обработчика, потому что React слушает выше. Смешивать оба подхода в одном сценарии опасно, и это чаще всего и ломается.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>e.stopPropagation()</code> в синтетическом обработчике не остановит нативный слушатель на <code>document</code> — нужен <code>e.nativeEvent.stopImmediatePropagation()</code>.</li>
<li>Несколько React-корней на странице: у каждого свой контейнер, события между ними не пересекаются как раньше.</li>
<li>Ожидание, что <code>onChange</code> у React — это нативный <code>change</code>: на самом деле это <code>input</code>, срабатывает на каждый символ.</li>
<li><code>preventDefault</code> в пассивных сценариях (<code>touchstart</code>, <code>wheel</code>) может не сработать — React вешает часть слушателей пассивно.</li>
<li>Портал: синтетическое событие идёт по React-дереву, нативное — по DOM.</li>
<li>Отладка через <code>getEventListeners</code> в консоли: на самом элементе ничего не найдётся, слушатели на корне.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как остановить событие для нативного кода?</strong> Через <code>e.nativeEvent.stopImmediatePropagation()</code>, либо повесить свой слушатель в capture-фазе выше. <strong>Зачем вообще делегирование, если DOM сегодня быстрый?</strong> Экономия при монтировании больших списков и единая точка для нормализации; отказаться от него React не может без ломающего изменения семантики.</p>`,
    code: `// React 17+: pooling нет, это работает
function onChange(e: React.ChangeEvent<HTMLInputElement>) {
  setTimeout(() => console.log(e.target.value), 100);  // ок без e.persist()
}

// Нативный listener в capture-фазе выполнится РАНЬШЕ React-обработчика,
// потому что React слушает на корневом контейнере
useEffect(() => {
  const el = ref.current!;
  el.addEventListener('click', native);      // порядок относительно onClick надо проверять
  return () => el.removeEventListener('click', native);
}, []);`,
    tip: 'Мало кто помнит вторую часть - зачем именно переносили на root: чтобы можно было держать два React на странице при постепенной миграции и чтобы stopPropagation в стороннем коде работал. Назови эту причину и добавь готовый рецепт: остановить событие для нативного кода можно только через e.nativeEvent.stopImmediatePropagation().' },

  { id: 'rx24',
    q: 'Как работают ref-колбэки и что там с cleanup в React 19?',
    a: `<h4>Коротко</h4>
<p>Ref-колбэк вызывается с DOM-узлом, когда узел появился, и раньше вызывался повторно с <code>null</code> при отвязке. В React 19 он может <strong>вернуть функцию очистки</strong> — тогда вместо вызова с <code>null</code> React вызовет её. Плата за это: стрелка с неявным возвратом стала ошибкой.</p>

<h4>Как это работает</h4>
<p>Привязка и отвязка рефов происходят в <strong>commit-фазе</strong>, вокруг мутаций DOM: сначала React отвязывает рефы удаляемых и обновляемых узлов, затем применяет мутации, затем привязывает новые — всё до layout-эффектов. Поэтому внутри <code>useLayoutEffect</code> ref уже заполнен, а во время рендера — нет.</p>
<p><strong>Инлайновый колбэк пересоздаётся каждый рендер.</strong> React сравнивает функции по ссылке: новая функция означает отвязку старой (cleanup или вызов с <code>null</code>) и привязку новой — на каждом коммите. Если внутри создаётся <code>ResizeObserver</code> или вешается подписка, это реальная работа на каждый рендер. Лечится <code>useCallback</code> с честными зависимостями.</p>
<p>Ref-колбэк — единственный способ узнать о появлении конкретного узла <strong>точечно</strong>. Объект-ref не умеет в динамическую коллекцию: для списка нужен <code>Map</code>, который наполняется колбэком по id. Это же делает его штатным инструментом для измерений и для интеграции с observer-ами.</p>
<p>Ловушка 19-й версии: <code>ref={el =&gt; (map[id] = el)}</code> — стрелка неявно возвращает присвоенное значение, React принимает его за cleanup и бросает ошибку. Обязательны фигурные скобки.</p>

<h4>Почему так</h4>
<p>Пара «вызвали с узлом / вызвали с null» асимметрична: в ветке с <code>null</code> у тебя уже нет ссылки на узел, от которого надо отписаться, и приходится складывать её в отдельный реф. Cleanup-замыкание держит узел в области видимости и делает код таким же, как в эффекте. Ошибка при неявном возврате — сознательная жёсткость: молча трактовать возвращённый DOM-узел как функцию нельзя, а игнорировать возврат означало бы вернуть неоднозначность.</p>

<h4>Подводные камни</h4>
<ul>
<li>Инлайновый колбэк с созданием observer — отвязка и привязка на каждом рендере, наблюдатели плодятся.</li>
<li><code>useCallback</code> с пропущенной зависимостью: колбэк держит устаревшее замыкание и пишет в старый стейт.</li>
<li>Смешивание cleanup-стиля и проверки на <code>null</code> в одном колбэке — ветка с <code>null</code> перестанет вызываться, и очистка не сработает.</li>
<li>Чтение <code>ref.current</code> во время рендера: там ещё старое значение, и компилятор из-за этого пропустит компонент.</li>
<li>Реф-колбэк на компоненте, а не на DOM-элементе: получишь то, что компонент отдал через <code>useImperativeHandle</code>, а не узел.</li>
<li>Хранение узлов в <code>Map</code> без удаления при отвязке — утечка на длинных списках.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Когда ref-колбэк лучше useEffect для измерений?</strong> Когда узел появляется и исчезает условно: колбэк вызовется ровно в эти моменты, а эффект придётся завязывать на флаг. <strong>Что вызовется раньше — ref-колбэк или useLayoutEffect?</strong> Ref: привязка рефов идёт до layout-эффектов в той же commit-фазе.</p>`,
    code: `// React 19: cleanup прямо в ref
const measureRef = useCallback((node: HTMLElement | null) => {
  if (!node) return;
  const ro = new ResizeObserver(([entry]) => setWidth(entry.contentRect.width));
  ro.observe(node);
  return () => ro.disconnect();
}, []);

<div ref={measureRef} />

// коллекция рефов для списка: cleanup убирает узел из Map
const nodes = useRef(new Map<string, HTMLElement>());
{items.map(i => (
  <li key={i.id} ref={(el) => {
    nodes.current.set(i.id, el!);
    return () => { nodes.current.delete(i.id); };   // React 19
  }}>{i.text}</li>
))}

// ЛОВУШКА React 19: неявный возврат считается cleanup
<div ref={el => (nodeRef.current = el)} />       // ошибка
<div ref={el => { nodeRef.current = el; }} />    // правильно`,
    tip: 'Обязательно упомяни, что инлайновый ref-колбэк отвязывается и привязывается на каждом рендере - это реальный источник багов с observer-ами. И добавь точный момент вызова: привязка рефов идёт в commit-фазе до layout-эффектов, поэтому в рендере ref ещё пуст.' },

  { id: 'rx25',
    q: 'В каком порядке выполняются эффекты и cleanup при обновлении дерева?',
    a: `<h4>Коротко</h4>
<p>Порядок обхода — <strong>снизу вверх</strong>: дети раньше родителей. При обновлении React делает это в две фазы: сначала <strong>все cleanup</strong> по всему дереву, только потом <strong>все setup</strong> — а не «cleanup и setup покомпонентно». Layout-эффекты всего дерева отрабатывают до paint и, значит, раньше первого обычного эффекта.</p>

<h4>Как это работает</h4>
<p>Обход снизу вверх — следствие устройства реконсилятора: работа над фибером завершается (<code>completeWork</code>) только после всех потомков, и список эффектов складывается в том же порядке. Поэтому ребёнок всегда получает свой эффект первым.</p>
<p>Разделение на две фазы нужно, чтобы избежать состояния, где часть дерева уже пересоздала подписки, а часть ещё держит старые. Практическое следствие: <strong>cleanup родителя выполнится раньше setup ребёнка</strong>. Если ребёнок в setup рассчитывает, что родитель уже подписался, порядок его не спасёт.</p>
<p>Внутри одного компонента несколько эффектов идут в порядке объявления, и cleanup тоже в порядке объявления — не в обратном, в отличие от того, что интуитивно ждут по аналогии со стеком.</p>
<p>По времени: <code>useLayoutEffect</code> вызывается синхронно в commit-фазе, после мутаций DOM и до отрисовки — браузер ещё не показал кадр, поэтому здесь безопасно измерять и корректировать layout без мигания. <code>useEffect</code> планируется на после paint, обычно в задаче планировщика. Исключение: если обновление пришло из дискретного события (клик, ввод), React может флашнуть пассивные эффекты синхронно перед следующим обновлением.</p>

<h4>Почему так</h4>
<p>Модель «сначала всё снять, потом всё поставить» даёт согласованность: в момент любого setup всё дерево уже находится в новом состоянии DOM. Обход снизу вверх даёт другое важное свойство — ребёнок измеряет себя до того, как родитель на основе этих измерений что-то решит.</p>
<p>Цена: порядок между <strong>братьями</strong> зависит от порядка в JSX и никак не гарантирован спецификацией. Строить на нём логику нельзя — при перестановке разметки всё сломается молча. Нужна координация — либо два эффекта в одном компоненте, либо явный контракт через ref или состояние.</p>

<h4>Подводные камни</h4>
<ul>
<li>Логика «родитель подписался, ребёнок читает» в setup — фазы разведены, ожидание неверно.</li>
<li>Тяжёлая работа в <code>useLayoutEffect</code>: она блокирует paint, и это прямая просадка INP.</li>
<li>Ожидание обратного порядка cleanup внутри компонента — он прямой, в порядке объявления.</li>
<li><code>useLayoutEffect</code> при SSR: на сервере не выполняется и печатает предупреждение, нужен <code>useEffect</code> или изоморфная обёртка.</li>
<li>Зависимость между эффектами братских компонентов — работает, пока кто-то не поменял порядок JSX.</li>
<li>Расчёт на то, что после <code>setState</code> в эффекте DOM уже обновлён: обновление уйдёт в следующий цикл.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Когда нужен useLayoutEffect?</strong> Когда результат должен попасть в тот же кадр: измерить и спозиционировать тултип, восстановить скролл, синхронизировать размеры — иначе пользователь увидит мигание. <strong>Что будет с эффектами при приостановке Suspense?</strong> Layout-эффекты уже показанного поддерева получают cleanup, пассивные — тоже; при возврате всё запускается заново.</p>`,
    snippet: `function Parent({ n }) {
  useLayoutEffect(() => { log('P layout'); return () => log('P layout cleanup'); });
  useEffect(() => { log('P effect'); return () => log('P effect cleanup'); });
  return <Child n={n} />;
}

function Child({ n }) {
  useEffect(() => { log('C A'); return () => log('C A cleanup'); });
  useEffect(() => { log('C B'); return () => log('C B cleanup'); });
  return <span>{n}</span>;
}

// Что напечатается при обновлении n?`,
    code: `// Монтирование (снизу вверх, layout до paint):
//   P layout -> paint -> C A, C B -> P effect
//   (у Child нет layout-эффектов, иначе они были бы раньше P layout)

// Обновление: СНАЧАЛА все cleanup по дереву, ПОТОМ все setup
//   P layout cleanup -> P layout -> paint
//   C A cleanup, C B cleanup, P effect cleanup
//   C A, C B, P effect

// Внутри компонента cleanup идёт в порядке объявления, а не в обратном:
//   C A cleanup, C B cleanup  (не B, потом A)`,
    tip: 'Ключевой факт, который проверяют: при обновлении сначала все cleanup по дереву, только потом все setup. Многие думают, что это чередуется покомпонентно. Второй факт на добивание: внутри компонента cleanup идёт в порядке объявления, а не в обратном.' },

  { id: 'rx26',
    q: 'Что такое автоматический батчинг и когда нужен flushSync?',
    a: `<h4>Коротко</h4>
<p>Батчинг — объединение нескольких <code>setState</code> в один рендер. До React 18 батчились только обновления внутри React-обработчиков; в промисах, <code>setTimeout</code> и нативных слушателях каждый вызов давал отдельный рендер. С <code>createRoot</code> батчинг <strong>автоматический везде</strong>. <code>flushSync</code> — аварийный выход, когда после обновления нужно немедленно прочитать реальный DOM.</p>

<h4>Как это работает</h4>
<p><code>setState</code> не рендерит: он кладёт обновление в очередь на хуке и планирует работу. Планирование идёт через микротаск, поэтому все синхронные вызовы в одном тике попадают в один рендер. Отсюда и то, что сразу после <code>setState</code> локальная переменная состояния всё ещё старая: она захвачена в замыкании этого рендера, а нового рендера ещё не было.</p>
<p>До 18-й версии батчинг был привязан к «unstable_batchedUpdates» вокруг обработчиков React — всё, что выходило за них (<code>await</code>, таймер, нативный слушатель), теряло группировку и давало по рендеру на вызов. Автоматический батчинг убрал это различие.</p>
<p><code>flushSync(fn)</code> из <code>react-dom</code> выполняет обновления внутри <code>fn</code> и <strong>синхронно доводит их до коммита</strong> до возврата из вызова. После него DOM обновлён, и можно измерять. Легитимные кейсы: проскроллить к только что добавленному элементу, измерить высоту после вставки, поставить фокус на появившийся инпут, подготовить DOM перед <code>window.print()</code>, отдать синхронно обновлённый DOM стороннему коду.</p>
<p>Отдельно: чтобы прочитать «новое» состояние, <code>flushSync</code> не нужен — для этого функциональный апдейт <code>setCount(c =&gt; c + 1)</code>. Это разные задачи, их часто путают.</p>

<h4>Почему так</h4>
<p>Батчинг убирает промежуточные кадры и лишнюю работу: три обновления — один рендер и один коммит вместо трёх. Без него каждое обновление в цикле давало бы отдельный проход по дереву.</p>
<p>Цена <code>flushSync</code> высокая: он ломает группировку, форсирует синхронный рендер всего затронутого дерева и отменяет преимущества конкурентности — работу нельзя прервать. React в dev печатает предупреждение, если <code>flushSync</code> вызван во время рендера или из lifecycle. Это скальпель: один-два вызова на приложение, а не приём по умолчанию.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>flushSync</code> ради чтения нового состояния — нужен функциональный апдейт, а не синхронный коммит.</li>
<li>Вызов внутри рендера или layout-эффекта: предупреждение и потенциально несогласованное дерево.</li>
<li><code>flushSync</code> в цикле по элементам — рендер на каждой итерации, гарантированный фриз.</li>
<li>Ожидание, что батчинг работает в legacy-режиме <code>ReactDOM.render</code> — там старое поведение.</li>
<li>Расчёт на отдельные рендеры между двумя <code>setState</code> в промисе: после 18-й версии их больше нет, и код с гонками начинает вести себя иначе.</li>
<li>Внутри <code>flushSync</code> обновления не батчатся с внешними — легко получить два коммита вместо одного.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как измерить DOM без flushSync?</strong> Обычно достаточно <code>useLayoutEffect</code>: он выполняется после коммита и до paint. <strong>Что стало с unstable_batchedUpdates?</strong> Больше не нужен: батчинг автоматический, функция осталась ради обратной совместимости.</p>`,
    code: `import { flushSync } from 'react-dom';

function addAndScroll(item: Item) {
  flushSync(() => {
    setItems(prev => [...prev, item]);   // коммит произойдёт до следующей строки
  });
  listRef.current!.scrollTop = listRef.current!.scrollHeight;  // DOM уже обновлён
}

// без flushSync здесь был бы старый scrollHeight

// Отказ от батчинга не нужен для чтения состояния - для этого функциональный апдейт
setCount(c => c + 1);
setCount(c => c + 1);   // 2, а не 1`,
    tip: 'Назови конкретный кейс - измерить DOM или проскроллить к новому элементу. Абстрактное нужен синхронный рендер звучит как заученная фраза. И сразу разведи две задачи: прочитать свежее состояние - это функциональный апдейт, а flushSync нужен только чтобы прочитать свежий DOM.' },

  { id: 'rx27',
    q: 'Что такое ленивая инициализация useState и когда её реально надо применять?',
    a: `<h4>Коротко</h4>
<p><code>useState(expr)</code> вычисляет <code>expr</code> <strong>на каждом рендере</strong>, хотя React берёт результат только при монтировании. <code>useState(() =&gt; expr)</code> вызывает функцию один раз. Экономится вычисление, а не корректность — результат одинаковый, поэтому применять надо там, где вычисление реально дорогое.</p>

<h4>Как это работает</h4>
<p>Аргумент — обычное выражение JavaScript, оно вычисляется до вызова хука, независимо от того, что хук с ним сделает. При монтировании React кладёт значение в слот состояния на фибере; при обновлениях аргумент просто отбрасывается. Если передана функция, React вызывает её (<code>typeof initialState === 'function'</code>) только на первом рендере.</p>
<p>Где разница ощутима: <code>JSON.parse</code> большой строки; чтение <code>localStorage</code> — это ещё и синхронный доступ, блокирующий главный поток; построение <code>Map</code> по массиву на тысячи элементов; генерация коллекции. При 60 рендерах в секунду это чистая потеря без единого эффекта на UI.</p>
<p>У <code>useReducer</code> та же идея через третий аргумент: <code>useReducer(reducer, arg, init)</code> вызовет <code>init(arg)</code> один раз. Бонус в том, что ту же <code>init</code> удобно переиспользовать для полного сброса: <code>dispatch({ type: 'reset', payload: arg })</code> и в редьюсере <code>return init(action.payload)</code>.</p>
<p>Ловушка типов: если само начальное значение — функция (колбэк, компонент, конструктор), React примет её за инициализатор и вызовет. Нужно двойное оборачивание: <code>useState(() =&gt; myFn)</code>.</p>

<h4>Почему так</h4>
<p>API устроено так ради простоты частого случая: <code>useState(0)</code> должно читаться как <code>useState(0)</code>, а не как <code>useState(() =&gt; 0)</code>. Различение по <code>typeof</code> — компромисс между лаконичностью и явностью, и цена этого компромисса ровно одна: функция-значение требует обёртки.</p>
<p>Второй компромисс — соблазн оптимизировать всё подряд. Оборачивать <code>useState(() =&gt; 0)</code> бессмысленно: создание стрелки стоит не меньше, чем литерал, а читаемость хуже. Ленивая инициализация окупается на измеримых вычислениях.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>useState(createStore())</code> вместо <code>useState(createStore)</code> — стор пересоздаётся на каждом рендере, и старый молча остаётся жив.</li>
<li>Побочные эффекты в инициализаторе: в StrictMode он вызывается дважды, и счётчик или запрос задвоятся.</li>
<li>Инициализатор, читающий <code>window</code> или <code>localStorage</code>, ломает SSR и вызывает несовпадение гидратации.</li>
<li>Начальное значение — функция, забыли обёртку: React вызовет её и положит в состояние результат.</li>
<li>Ожидание, что инициализатор пересчитается при смене пропа: он не пересчитается никогда — для этого <code>key</code>.</li>
<li><code>useState(props.value)</code> как «значение по умолчанию» — классический производный стейт, который перестанет обновляться.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сбросить состояние на начальное?</strong> Через <code>key</code> на компоненте или через <code>init</code> в редьюсере — вызывать инициализатор повторно вручную нельзя. <strong>Чем это отличается от useMemo?</strong> <code>useMemo</code> может пересчитаться при смене зависимостей и по спецификации может быть сброшен React; инициализатор состояния выполняется строго один раз.</p>`,
    code: `// плохо: JSON.parse на каждом рендере
const [state, setState] = useState(JSON.parse(localStorage.getItem('draft') ?? '{}'));

// хорошо: один раз при монтировании
const [state, setState] = useState(() => {
  try { return JSON.parse(localStorage.getItem('draft') ?? '{}'); }
  catch { return {}; }
});

// useReducer с init - переиспользуем для сброса
function init(items: Item[]) { return { items, index: new Map(items.map(i => [i.id, i])) }; }
const [state, dispatch] = useReducer(reducer, rawItems, init);`,
    tip: 'Добавь ловушку: если начальное состояние само является функцией, useState вызовет её как инициализатор - нужно двойное оборачивание. И отметь, что инициализатор обязан быть чистым: в StrictMode он вызывается дважды.' },

  { id: 'rx28',
    q: 'Что такое производный стейт и почему синхронизация через useEffect — антипаттерн?',
    a: `<h4>Коротко</h4>
<p>Производное состояние — то, что однозначно вычисляется из пропсов и другого состояния. Правило: <strong>вычислять в рендере, а не хранить и синхронизировать эффектом</strong>. Эффект здесь даёт лишний цикл рендера, второй источник истины и неправильный HTML при SSR.</p>

<h4>Как это работает</h4>
<p>Цепочка при синхронизации через эффект: рендер со старым значением → коммит → браузер рисует кадр → пассивный эффект → <code>setState</code> → второй рендер → второй коммит. Пользователь физически видит один кадр с неактуальными данными, и это не теория: при медленном устройстве или каскаде из нескольких таких эффектов мигание заметно глазом.</p>
<p>Второй источник истины опаснее мигания. Значение хранится и в пропсе, и в состоянии; их связывает массив зависимостей, написанный руками. Забыл зависимость — состояние застыло, и баг проявится только на конкретном переходе.</p>
<p>Альтернативы по возрастанию сложности. Первая — просто вычислить в теле: <code>const full = first + ' ' + last</code>. Вторая — <code>useMemo</code>, если вычисление измеримо дорогое, а не «на всякий случай». Третья, когда нужно <strong>сбросить</strong> состояние при смене сущности, — <code>key</code> на компоненте: React размонтирует старый и смонтирует чистый. Четвёртая, для частичного сброса, — задокументированный паттерн <strong>корректировки в рендере</strong>: хранить предыдущий проп в состоянии и при расхождении вызвать <code>setState</code> прямо в теле. React заметит это, выбросит текущий рендер и перезапустит его до отрисовки — промежуточного кадра не будет, и это дешевле эффекта.</p>

<h4>Почему так</h4>
<p>Эффекты предназначены для синхронизации с <strong>внешним миром</strong>: подписки, таймеры, ручной DOM, аналитика, сетевые запросы вне модели данных. Синхронизация React-состояния с React-пропсами — это внутренняя работа, для которой у React уже есть рендер.</p>
<p>Компромисс у каждой альтернативы свой: вычисление в рендере повторяется на каждом проходе (обычно копейки), <code>useMemo</code> добавляет память и зависимости, <code>key</code> сбрасывает вообще всё, включая скролл и фокус, корректировка в рендере читается непривычно и требует комментария.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>useState(props.value)</code> как «начальное значение»: при смене пропа состояние не обновится, и это классический баг формы редактирования.</li>
<li>Каскад эффектов: один эффект пишет состояние, второй реагирует на него — три-четыре лишних рендера и трудноуловимый порядок.</li>
<li>Синхронизация с сервером в SSR: первый HTML содержит старое значение, гидратация даёт несовпадение или мигание.</li>
<li>Корректировка в рендере без условия — бесконечный цикл; условие обязательно.</li>
<li>Оборачивать всё подряд в <code>useMemo</code> «чтобы не считалось»: сравнение зависимостей тоже стоит времени.</li>
<li>Считать антипаттерном любой эффект: подписка, таймер и ручной DOM — законные случаи.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>А если производное значение дорогое?</strong> <code>useMemo</code>, но после замера в профайлере — часто оказывается, что вычисление стоит доли миллисекунды. <strong>Как сбросить только часть состояния?</strong> Либо вынести её в подкомпонент со своим <code>key</code>, либо корректировка в рендере — оба варианта без промежуточного кадра.</p>`,
    code: `// антипаттерн
const [full, setFull] = useState('');
useEffect(() => { setFull(first + ' ' + last); }, [first, last]);  // лишний рендер

// правильно
const full = first + ' ' + last;

// сброс состояния при смене сущности - через key, а не через эффект
<ProfileForm key={userId} userId={userId} />

// редкий случай: корректировка в рендере (быстрее эффекта)
const [prevId, setPrevId] = useState(userId);
if (userId !== prevId) {
  setPrevId(userId);
  setSelection(null);       // React перезапустит рендер до отрисовки
}`,
    tip: 'Скажи про корректировку состояния прямо в рендере - это официально задокументированный паттерн, и его почти никто не называет. Объясни, почему он дешевле эффекта: React выбрасывает текущий рендер и перезапускает его до отрисовки, промежуточного кадра не возникает.' },

  { id: 'rx29',
    q: 'Как использовать key для сброса состояния компонента и когда это лучше useEffect?',
    a: `<h4>Коротко</h4>
<p>При смене <code>key</code> React считает элемент <strong>другим компонентом</strong>: размонтирует старый со всеми cleanup и монтирует новый с чистым состоянием. Это самый декларативный способ сказать «здесь теперь другая сущность» — и он честнее эффекта, который вручную перечисляет, что обнулить.</p>

<h4>Как это работает</h4>
<p>Реконсиляция сопоставляет старое и новое дерево по позиции и по паре «тип + key». Если тип совпал, а key изменился, React не переиспользует фибер: старый помечается на удаление, создаётся новый. Значит выполняются все cleanup эффектов, ref-ы получают отвязку, состояние хуков и DOM-узлы создаются заново — всё за один проход рендера, без промежуточного кадра со старыми данными.</p>
<p>Типовые применения: форма редактирования при переключении сущности (<code>key={userId}</code>); сброс табов и аккордеона при смене раздела; перезапуск Error Boundary по кнопке «Повторить» (<code>key={attempt}</code>) — иначе граница остаётся в состоянии ошибки навсегда; перезапуск Suspense-границы, чтобы она снова показала fallback вместо удержания старого контента; сброс сторонней библиотеки, которая не умеет обновляться по пропсам.</p>
<p>Важно: <code>key</code> имеет смысл относительно <strong>родителя и позиции</strong>, а не глобально. Одинаковые key в разных списках не конфликтуют, а разные key на одной позиции — уже пересоздание.</p>

<h4>Почему так</h4>
<p>Альтернатива — эффект, который на смену пропа вызывает пять сеттеров, — плоха тем, что список сбрасываемого приходится поддерживать руками. Добавили шестое состояние и забыли про него — получили утечку данных предыдущего пользователя в форму. <code>key</code> делает сброс структурным свойством, а не набором инструкций.</p>
<p>Цена: сброс <strong>тотальный</strong>. Теряются позиция скролла, фокус, незакоммиченный ввод, состояние вложенных компонентов; перезапускаются все эффекты, включая сетевые запросы. На тяжёлом поддереве это заметная работа: полное размонтирование и монтирование вместо обновления.</p>

<h4>Подводные камни</h4>
<ul>
<li>Ставить <code>key={Math.random()}</code> или <code>key={Date.now()}</code> — пересоздание на каждом рендере, потеря фокуса при вводе и разрушенная производительность.</li>
<li><code>key={index}</code> в списке с сортировкой и удалением: состояние строк переезжает не туда, потому что key описывает позицию, а не сущность.</li>
<li>Использовать <code>key</code> там, где нужно сбросить одно поле — заодно улетит скролл и фокус.</li>
<li>Ожидание, что <code>key</code> сбросит состояние <strong>родителя</strong>: он влияет только на элемент, которому поставлен.</li>
<li>Смена key на границе с анимацией выхода — компонент исчезает мгновенно, анимации не будет.</li>
<li>Забыть, что при пересоздании перезапустятся запросы: смена key дважды подряд даст два запроса и возможную гонку.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как перезапустить Error Boundary?</strong> Инкрементировать счётчик и передать его в <code>key</code> границы — либо использовать <code>resetKeys</code> в react-error-boundary. <strong>Чем key отличается от условного рендера с null?</strong> Оба размонтируют, но <code>key</code> делает это в одном проходе и не требует лишнего рендера с пустотой.</p>`,
    code: `// сброс формы при смене пользователя
<ProfileForm key={user.id} user={user} />

// перезапуск Error Boundary
const [attempt, setAttempt] = useState(0);
<ErrorBoundary key={attempt} fallback={<Retry onRetry={() => setAttempt(a => a + 1)} />}>
  <Widget />
</ErrorBoundary>

// сброс только части состояния: выносим её в подкомпонент
<Layout>
  <Sidebar />                        {/* сохраняет состояние */}
  <Content key={sectionId} />        {/* сбрасывается */}
</Layout>`,
    tip: 'Уточни, что key на компоненте - это ещё и способ перезапустить Suspense или Error Boundary; типовой вопрос про кнопку Повторить. И назови цену: сброс тотальный - улетят скролл, фокус, незакоммиченный ввод и перезапустятся все запросы.' },

  { id: 'rx30',
    q: 'Controlled vs uncontrolled компоненты: как выбираешь и где граница?',
    a: `<h4>Коротко</h4>
<p>Controlled: истина в React-состоянии, DOM — производная (<code>value</code> + <code>onChange</code>). Uncontrolled: истина в DOM, React читает значение через ref или <code>FormData</code> (<code>defaultValue</code>). Граница простая: контролируемое поле нужно тогда, когда значение <strong>влияет на рендер до сабмита</strong>. Всё остальное — неконтролируемое.</p>

<h4>Как это работает</h4>
<p>У контролируемого поля React на каждом коммите сравнивает <code>value</code> в пропсах с <code>node.value</code> и при расхождении перезаписывает DOM. Отсюда эффект «поле не печатается», если забыть <code>onChange</code>: React возвращает значение обратно после каждого нажатия. И отсюда же цена — рендер на каждый символ: на форме в сотню полей с общим состоянием в родителе это десятки миллисекунд на клавишу и заметный лаг.</p>
<p>Неконтролируемое поле React трогает один раз: ставит <code>defaultValue</code> при монтировании и больше не вмешивается. Значение при сабмите собирает браузер — <code>new FormData(form)</code> или <code>e.currentTarget.elements</code>. Ввод не вызывает ни одного рендера.</p>
<p>Ловушка смены режима: <code>value={undefined}</code> делает поле неконтролируемым, и когда позже туда приедет строка, React напечатает предупреждение о переключении режима, а состояние поля может дёрнуться. Поэтому всегда <code>value={x ?? ''}</code>.</p>
<p>Отдельный случай — <code>&lt;input type="file"&gt;</code>: его <code>value</code> нельзя задать программно из соображений безопасности, поле всегда неконтролируемое.</p>

<h4>Почему так</h4>
<p>Контролируемая модель даёт единый источник истины и делает возможными зависимые поля, маски, форматирование на лету, счётчик символов, дизейбл кнопки по содержимому и синхронизацию с URL. Неконтролируемая опирается на то, что браузер уже умеет: хранение значения, автозаполнение, восстановление после перезагрузки, отправку без JS.</p>
<p>Практический компромисс 2026 года — React Hook Form: поля неконтролируемые, подписка точечная, валидация полноценная. Он и есть ответ на вопрос «как получить и производительность, и логику».</p>

<h4>Подводные камни</h4>
<ul>
<li><code>value</code> без <code>onChange</code> — поле только для чтения по факту; нужен <code>readOnly</code> или обработчик.</li>
<li><code>value={x ?? ''}</code> забыли — предупреждение о смене режима и странное поведение после первой загрузки данных.</li>
<li>Контролируемое поле с маской: курсор прыгает в конец, потому что React переписывает <code>value</code> целиком; нужна ручная работа с <code>selectionStart</code>.</li>
<li>Неконтролируемое поле без <code>name</code> — при сабмите значения просто нет.</li>
<li>Смена <code>defaultValue</code> после монтирования ничего не сделает: нужен <code>key</code> или императивная запись.</li>
<li>Контролируемая форма ломает прогрессивное улучшение: без JS поля приедут пустыми.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сделать debounce на контролируемом поле?</strong> Держать локальное состояние поля контролируемым, а наверх отдавать отложенное значение — иначе ввод начнёт отставать. <strong>Как совместить с прогрессивным улучшением?</strong> Через <code>defaultValue</code> плюс <code>name</code>: форма работает без JS, а после гидратации логика навешивается сверху.</p>`,
    code: `// controlled: нужен для зависимой логики
<input value={query} onChange={e => setQuery(e.target.value)} />

// uncontrolled: значение читается при сабмите
<form onSubmit={e => {
  e.preventDefault();
  const data = Object.fromEntries(new FormData(e.currentTarget));
}}>
  <input name="email" defaultValue={user.email} />
</form>

// ловушка: undefined делает поле неконтролируемым
<input value={user.name ?? ''} onChange={onChange} />`,
    tip: 'Разграничение, которое звучит по-сеньорски: контролируемое поле нужно тогда, когда значение влияет на рендер до сабмита. Всё остальное - неконтролируемое. Добавь механику: React на каждом коммите сверяет value с DOM и перезаписывает его - отсюда и «поле не печатается» без onChange, и прыгающий курсор в масках.' },

  { id: 'rx31',
    q: 'Почему React Hook Form быстрее контролируемых форм и в чём его подводные камни?',
    a: `<h4>Коротко</h4>
<p>RHF работает с <strong>неконтролируемыми полями</strong>: <code>register</code> вешает ref и нативные обработчики, значения живут в DOM и во внутреннем сторе библиотеки, а не в React-состоянии. Ввод символа не вызывает рендер формы вообще. Подписки на <code>formState</code> построены на прокси — библиотека рендерит только то, что ты действительно читаешь.</p>

<h4>Как это работает</h4>
<p><code>register('email')</code> возвращает <code>{ name, ref, onChange, onBlur }</code>. Ref кладёт узел в реестр полей, обработчики нативные — они пишут значение во внутренний стор и запускают валидацию по выбранному режиму. React-состояние не участвует, поэтому нажатие клавиши не порождает ни одного ререндера.</p>
<p><code>formState</code> — <strong>Proxy</strong>. Он фиксирует, к каким свойствам обратился компонент во время рендера, и подписывает его только на них. Не читаешь <code>errors.email</code> — изменение этой ошибки тебя не разбудит. Отсюда неочевидное правило: деструктурировать <code>formState</code> надо на верхнем уровне рендера. Ленивое чтение внутри колбэка или условия прокси не увидит, и подписка не оформится.</p>
<p>Точечные обновления делаются через <code>useWatch({ control, name })</code> в том компоненте, которому значение нужно, и через <code>Controller</code> для чужих контролируемых инпутов. Метод <code>watch()</code> на уровне формы работает иначе: он подписывает <strong>весь компонент</strong>, где вызван, и перерисовывает форму целиком.</p>

<h4>Почему так</h4>
<p>Библиотека сознательно уходит от модели «форма как React-состояние»: там стоимость линейна по числу полей и платится на каждый символ. Ценой становится потеря декларативности — значения живут вне React, и посмотреть их в DevTools как состояние нельзя, только через <code>getValues()</code>.</p>
<p>Вторая цена — интеграция. Любой UI-кит с контролируемым инпутом требует <code>Controller</code>, и для этого поля производительность возвращается к обычной контролируемой. На форме, где все поля из дизайн-системы, выигрыш RHF почти исчезает — это надо честно понимать до выбора.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>register('email')</code> как проп вместо спреда <code>{...register('email')}</code> — поле не зарегистрируется.</li>
<li>Чтение <code>formState.errors</code> внутри условия или колбэка: прокси не оформит подписку, ошибки не отрисуются.</li>
<li><code>watch()</code> вместо <code>useWatch</code> — вся форма рендерится на каждый ввод, и оптимизация обнуляется.</li>
<li><code>useFieldArray</code> с <code>key={index}</code>: при удалении строки значения съезжают; нужен <code>field.id</code>.</li>
<li>Асинхронные <code>defaultValues</code>: пришли после монтирования — нужен <code>reset(data)</code>, иначе форма останется пустой.</li>
<li>Ожидание, что <code>isDirty</code> сравнивает с текущими данными: он сравнивает с <code>defaultValues</code>, и после <code>reset</code> база меняется.</li>
<li>Валидация в режиме <code>onChange</code> по умолчанию на большой схеме — форма снова тормозит, но уже из-за Zod.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Когда RHF не даёт выигрыша?</strong> Когда почти все поля идут через <code>Controller</code> — там та же контролируемая модель. <strong>Как получить значение без подписки?</strong> <code>getValues()</code> — читает из стора и не вызывает рендер; для отображения нужен <code>useWatch</code>.</p>`,
    code: `const { register, handleSubmit, control, formState: { errors, isSubmitting } } =
  useForm<FormValues>({ resolver: zodResolver(Schema), mode: 'onBlur' });

<form onSubmit={handleSubmit(onValid)}>
  <input {...register('email')} aria-invalid={!!errors.email} />
  {errors.email && <p role="alert">{errors.email.message}</p>}

  {/* сторонний контролируемый компонент */}
  <Controller name="country" control={control}
    render={({ field }) => <Select {...field} options={countries} />} />

  {/* точечная подписка вместо watch() на всю форму */}
  <Total control={control} />
</form>

function Total({ control }) {
  const items = useWatch({ control, name: 'items' });   // перерисуется только Total
  return <b>{items.reduce((s, i) => s + i.price, 0)}</b>;
}`,
    tip: 'Упомяни прокси в formState и требование деструктурировать его на верхнем уровне рендера - это неочевидная деталь, которая доказывает реальный опыт с библиотекой. И честно назови границу: если все поля идут через Controller, выигрыш RHF почти исчезает.' },

  { id: 'rx32',
    q: 'Форма на 100+ полей тормозит при вводе. Как ты будешь её чинить?',
    a: `<h4>Коротко</h4>
<p>Сначала измеряю, потом чиню. React DevTools Profiler с записью ввода показывает, что именно рендерится на нажатие клавиши и сколько это стоит. В девяти случаях из десяти виноват один из трёх факторов: состояние всей формы поднято в родителя, валидация всей схемы идёт на каждый символ, или тяжёлые дочерние компоненты рендерятся без мемоизации.</p>

<h4>Как это работает</h4>
<p>Диагностика по цифрам. В профайлере смотрю ranked-вид: если на один keystroke приходится коммит на 30–80 мс и в списке сотня компонентов — это подъём состояния. Если долгий один компонент — тяжёлый рендер. Если долгий не render, а commit — проблема в количестве DOM-узлов. Ориентир: обработка ввода должна укладываться в бюджет INP, то есть отклик под 200 мс, а лучше в один кадр 16 мс.</p>
<p><strong>Шаг 1 — убрать состояние формы из React.</strong> Переход на неконтролируемые поля (RHF или обычный <code>FormData</code>) убирает рендер на символ полностью. Это почти всегда основной выигрыш.</p>
<p><strong>Шаг 2 — режим валидации.</strong> <code>onBlur</code> или <code>onTouched</code> вместо <code>onChange</code>, а после первой ошибки <code>reValidateMode: 'onChange'</code>, чтобы пользователь видел исправление. Дорогие проверки — уникальность email, обращение к API — с debounce и отменой предыдущего запроса.</p>
<p><strong>Шаг 3 — структура.</strong> Разбить форму на секции-подкомпоненты: шаги визарда, аккордеон, табы — и рендерить только видимую. Длинные повторяющиеся блоки виртуализировать. Поля обернуть в <code>memo</code>, чтобы точечная подписка не тянула соседей.</p>
<p><strong>Шаг 4 — если контролируемость требуется по делу</strong> (маска, зависимые поля): изолировать состояние на уровне поля — локальный <code>useState</code> внутри, наверх отдавать по <code>onBlur</code>. Дорогое превью, зависящее от формы, — через <code>useDeferredValue</code>.</p>

<h4>Почему так</h4>
<p>Порядок шагов не случаен: сначала убираем работу целиком, потом сокращаем её частоту, и только потом оптимизируем то, что осталось. Мемоизация на первом месте — типичная ошибка: она добавляет код и сравнения, но не убирает причину.</p>
<p>Цена решений тоже разная. Уход от контролируемых полей ломает мгновенную валидацию и требует переписать логику. Разбиение на шаги меняет UX и требует согласования с продуктом. Виртуализация ломает Ctrl+F и усложняет доступность. Об этом надо говорить вслух — интервьюер проверяет именно способность назвать цену.</p>

<h4>Подводные камни</h4>
<ul>
<li>Оптимизировать по ощущениям, без профайлера: половина усилий уходит не туда.</li>
<li>Профилировать в dev-сборке и делать выводы: StrictMode и dev-оверхед искажают числа в разы.</li>
<li>Обвесить всё <code>memo</code>, оставив нестабильные колбэки в пропсах — сравнение всегда даёт false.</li>
<li>Debounce на самом <code>value</code> поля: ввод начинает отставать от клавиатуры.</li>
<li>Забыть про валидацию: сама Zod-схема на сотне полей стоит миллисекунды на каждый прогон.</li>
<li>Виртуализировать форму без учёта табуляции — клавиатурная навигация ломается.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как понять, что виноват commit, а не render?</strong> В профайлере это разные полосы; долгий commit при коротком render означает много DOM-мутаций. <strong>Что если бизнес требует валидацию на каждый символ?</strong> Валидировать только изменённое поле, а не всю схему: у Zod для этого частичные схемы, у RHF — валидация по имени поля.</p>`,
    code: `// изоляция состояния в поле вместо подъёма всей формы наверх
const Field = memo(function Field({ name, defaultValue, onCommit }) {
  const [local, setLocal] = useState(defaultValue);
  return (
    <input
      value={local}
      onChange={e => setLocal(e.target.value)}          // рендерится только это поле
      onBlur={() => onCommit(name, local)}              // наверх - только при уходе
    />
  );
});

// дорогое превью не блокирует ввод
const deferredValues = useDeferredValue(values);
<Preview values={deferredValues} />`,
    tip: 'Начни ответ со слова измерю и назови конкретный инструмент и цифру: отклик на ввод должен укладываться в бюджет INP, то есть под 200 мс. Кандидаты, которые сразу сыплют оптимизациями без профилирования, теряют очки.' },

  { id: 'rx33',
    q: 'Как ты организуешь валидацию форм: где схема, где ошибки, что показывать пользователю?',
    a: `<h4>Коротко</h4>
<p>Одна схема — единственный источник истины: лежит в общем модуле, тип формы выводится из неё через <code>z.infer</code>, resolver подключает её к RHF на клиенте, она же валидирует на сервере. Уровней валидации три — браузерная, клиентская схемная и серверная, — и путать их нельзя: доверять можно только последней.</p>

<h4>Как это работает</h4>
<p><strong>Браузерная</strong> (<code>required</code>, <code>type="email"</code>, <code>pattern</code>, <code>min</code>/<code>max</code>) стоит ноль строк, работает до гидратации и без JS, даёт нативные подсказки и участвует в доступности. Её слабость — неуправляемый внешний вид сообщений; отсюда частая практика: оставить атрибуты, но перехватывать отображение через <code>novalidate</code> плюс собственные тексты.</p>
<p><strong>Клиентская схемная</strong> даёт быструю обратную связь и предотвращает лишний раунд-трип. Режим по умолчанию — <code>onTouched</code>: не ругаться, пока пользователь не ушёл из поля. После первой ошибки переключаемся на <code>reValidateMode: 'onChange'</code>, чтобы человек видел момент исправления, а не ждал повторного blur.</p>
<p><strong>Серверная</strong> — единственная, которой можно доверять, и единственная, где возможны проверки уникальности email, прав, остатков на складе, лимитов. Её результат должен приходить <strong>по полям</strong>, а не одной строкой: <code>fieldErrors</code> раскладывается через <code>setError('email', ...)</code>, и ошибка появляется ровно там, где её надо чинить.</p>
<p>Доступность здесь не украшение: <code>aria-invalid</code> на поле, текст ошибки, связанный через <code>aria-describedby</code>, контейнер с <code>role="alert"</code>, и фокус на первое невалидное поле при сабмите — без этого форма непроходима с клавиатуры и со скринридером.</p>

<h4>Почему так</h4>
<p>Дублирование правил — главный источник расхождений: клиент пропустил, сервер отказал, пользователь видит непонятное. Общая схема убирает это по построению.</p>
<p>Цена: схема попадает в клиентский бандл (Zod — десятки килобайт; Valibot заметно легче за счёт древовидной структуры), а серверные правила приходится держать отдельным расширением базовой схемы, чтобы не утащить в браузер лишнее. Плюс общая схема не покрывает межполевые проверки, зависящие от данных БД — их всё равно пишут только на сервере.</p>

<h4>Подводные камни</h4>
<ul>
<li>Валидировать на <code>onChange</code> с первого символа: пользователь получает «некорректный email» на букве «а».</li>
<li>Показывать только первую ошибку формы: человек чинит по одной и злится.</li>
<li>Серверные ошибки общей плашкой вместо привязки к полям.</li>
<li>Ошибка не связана с полем через <code>aria-describedby</code> — скринридер её не прочитает.</li>
<li>Разные тексты на клиенте и сервере для одного правила — выглядит как баг.</li>
<li>Схема с секретами или серверными зависимостями импортируется в клиентский компонент.</li>
<li>Числа и даты без <code>coerce</code>: <code>FormData</code> отдаёт строки, и валидация падает на пустом месте.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Где валидировать межполевые зависимости?</strong> В схеме через <code>refine</code>/<code>superRefine</code> — тогда правило тоже общее. <strong>Как не тащить Zod в бандл?</strong> Держать серверные расширения схемы в отдельном модуле и проверять размер бандла анализатором; либо взять Valibot.</p>`,
    code: `export const Schema = z.object({
  email: z.string().email('Некорректный email'),
  age: z.coerce.number().int().min(18, 'Только 18+'),
});
export type FormValues = z.infer<typeof Schema>;

const { setError, handleSubmit } = useForm<FormValues>({
  resolver: zodResolver(Schema),
  mode: 'onTouched',
  reValidateMode: 'onChange',
});

async function onValid(values: FormValues) {
  const res = await api.register(values);
  if (res.fieldErrors) {
    for (const [field, msgs] of Object.entries(res.fieldErrors)) {
      setError(field as keyof FormValues, { message: msgs[0] });  // серверные ошибки на поля
    }
  }
}`,
    tip: 'Назови три уровня валидации явно - браузерный, клиентский схемный, серверный - и скажи, что доверять можно только третьему. Добавь UX-правило про onTouched с переключением на onChange после первой ошибки: это то, что отличает практика от теоретика.' },

  { id: 'rx34',
    q: 'Когда нужна виртуализация списка и какие проблемы она приносит?',
    a: `<h4>Коротко</h4>
<p>Виртуализация нужна, когда узкое место — <strong>количество DOM-узлов</strong>, а не количество React-рендеров. Признаки: тормозит скролл, а не обновление; память растёт линейно с длиной списка; в профайлере долгий commit при коротком render. Порог зависит от сложности строки: 200 тяжёлых карточек могут быть хуже 5000 простых.</p>

<h4>Как это работает</h4>
<p>Рендерится только видимое окно плюс overscan (буфер в несколько строк сверху и снизу, чтобы при быстром скролле не мелькала пустота). Остальное заменяется распоркой: контейнер получает суммарную высоту всех элементов, а видимые строки позиционируются абсолютно через <code>transform: translateY</code> — не через <code>top</code>, потому что трансформ не вызывает reflow.</p>
<p>Библиотеки различаются моделью размеров. <code>react-window</code> — самый лёгкий, позиции считаются математически из фиксированной высоты, измерений нет вовсе. <code>@tanstack/react-virtual</code> — headless, лучший вариант для таблиц, динамических высот и горизонтальной виртуализации: он измеряет реальные элементы через <code>measureElement</code> и корректирует оценку. <code>react-virtuoso</code> — больше всего «из коробки» для сложных фидов с группировкой и подгрузкой.</p>
<p>Динамические высоты — самая болезненная часть. Оценка <code>estimateSize</code> заведомо неточна, и при скролле вверх после измерения реальных высот позиция контента смещается — тот самый «прыгающий скролл». Библиотеки компенсируют это, подправляя <code>scrollTop</code>, но при сильном расхождении оценки прыжки видны.</p>

<h4>Почему так</h4>
<p>Браузер платит за каждый узел: память, время layout, время paint, обход дерева доступности. На десяти тысячах строк это десятки мегабайт и layout, который не укладывается в кадр. Виртуализация меняет линейную зависимость на константную.</p>
<p>Цена высокая и её надо называть: ломается <strong>Ctrl+F</strong> по странице и печать — элементов физически нет в DOM. Ломается доступность, если не проставить <code>aria-setsize</code>, <code>aria-posinset</code> и корректную роль (<code>listbox</code>, <code>grid</code>): скринридер иначе объявит «список из 12 элементов». Ломаются якорные ссылки, восстановление скролла при возврате назад, sticky-заголовки внутри групп и анимации входа/выхода.</p>
<p>Часто дешевле альтернативы: пагинация или бесконечная лента порциями; <code>content-visibility: auto</code> с <code>contain-intrinsic-size</code> — браузер сам пропускает отрисовку невидимого, DOM при этом остаётся целым, а значит Ctrl+F и доступность работают; и просто упрощение разметки строки, если в ней сорок узлов вместо пяти.</p>

<h4>Подводные камни</h4>
<ul>
<li>Виртуализировать раньше замера — получить всю цену без выгоды.</li>
<li><code>key</code> по индексу виртуального элемента вместо id: состояние строк переезжает при скролле.</li>
<li>Overscan в ноль — белые полосы при быстром скролле; слишком большой — потеря смысла.</li>
<li>Вложенный скролл-контейнер, о котором виртуализатор не знает: <code>getScrollElement</code> должен указывать на реальный скроллер.</li>
<li>Забыть <code>aria</code>-атрибуты и роль — список становится непроходимым для скринридера.</li>
<li>Анимации появления строк: элемент «появляется» просто из-за скролла, и анимация срабатывает постоянно.</li>
<li>Виртуализация внутри страницы, которую надо печатать или экспортировать в PDF.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сохранить работу Ctrl+F?</strong> Взять <code>content-visibility: auto</code> вместо виртуализации, либо добавить собственный поиск по данным. <strong>Как чинить прыгающий скролл?</strong> Улучшать <code>estimateSize</code> (например, кешировать измеренные высоты по id) и использовать якорение скролла на элемент, а не на пиксели.</p>`,
    code: `import { useVirtualizer } from '@tanstack/react-virtual';

const parentRef = useRef<HTMLDivElement>(null);
const rowVirtualizer = useVirtualizer({
  count: rows.length,
  getScrollElement: () => parentRef.current,
  estimateSize: () => 48,
  overscan: 8,
});

<div ref={parentRef} style={{ height: 600, overflow: 'auto' }}>
  <div style={{ height: rowVirtualizer.getTotalSize(), position: 'relative' }}>
    {rowVirtualizer.getVirtualItems().map(v => (
      <div key={rows[v.index].id}
           ref={rowVirtualizer.measureElement}
           data-index={v.index}
           style={{ position: 'absolute', top: 0, left: 0, width: '100%',
                    transform: 'translateY(' + v.start + 'px)' }}>
        <Row row={rows[v.index]} />
      </div>
    ))}
  </div>
</div>`,
    tip: 'Скажи про content-visibility auto с contain-intrinsic-size как про более дешёвую альтернативу для средних списков: DOM остаётся целым, поэтому Ctrl+F и скринридер продолжают работать. Это редко называют, а решение часто рабочее.' },

  { id: 'rx35',
    q: 'Как ты профилируешь React-приложение в DevTools? Что смотришь в flamegraph и ranked?',
    a: `<h4>Коротко</h4>
<p>Профилирую <strong>конкретное взаимодействие</strong>, а не «приложение вообще»: клик по фильтру, ввод символа, открытие модалки. Flamegraph отвечает на вопрос «кто виноват в каскаде», ranked — «что именно медленно». Ключевая настройка — «Record why each component rendered».</p>

<h4>Как это работает</h4>
<p>Профайлер записывает серию <strong>коммитов</strong>. Полоса сверху — это они: высота столбика равна длительности. Первое, на что смотрю, — их количество. Если на одно действие пять коммитов вместо одного, значит есть каскад: эффект пишет состояние, оно вызывает следующий эффект, и так по цепочке. Это структурная проблема, и мемоизация её не решит.</p>
<p><strong>Flamegraph</strong> показывает дерево одного коммита: ширина — время, серые узлы не рендерились. Здесь видно, что при клике на кнопке перерисовалось всё дерево от корня — обычно это состояние, поднятое слишком высоко, или нестабильное значение контекста.</p>
<p><strong>Ranked</strong> сортирует компоненты коммита по времени. Здесь ищу точечную проблему: один компонент на 40 мс — тяжёлое вычисление, огромный список, дорогая сериализация.</p>
<p>Опция «why did this render» подписывает причину каждого рендера: изменились пропсы (и какие именно), состояние, контекст, либо «parent rendered». Это прямой ответ на главный вопрос отладки, и без неё профилирование превращается в гадание.</p>
<p>Дополнительно: подсветка обновлений в настройках DevTools — быстрая визуальная диагностика без записи; компонент <code>&lt;Profiler&gt;</code> для сбора метрик в проде; и вкладка Performance браузера, где React-трек соединяется с long tasks и позволяет связать рендеры с INP.</p>

<h4>Почему так</h4>
<p>Разделение на flamegraph и ranked отражает две разные болезни: «рендерится слишком многое» и «рендерится слишком долго». Лечатся они противоположными средствами — первое структурой состояния и мемоизацией, второе виртуализацией и упрощением вычислений. Начинать надо с первой, потому что она обычно дешевле.</p>
<p>Цена и ограничения: профилирование идёт в dev-сборке, где React делает дополнительные проверки и StrictMode задваивает рендеры — абсолютные числа завышены, доверять надо пропорциям. Для реальных цифр нужен профилирующий прод-билд (<code>react-dom/profiling</code>) или замер через <code>&lt;Profiler&gt;</code> на живых пользователях.</p>

<h4>Подводные камни</h4>
<ul>
<li>Мерить в dev и делать выводы об абсолютных значениях.</li>
<li>Записывать «всё приложение» — в шуме не видно ничего.</li>
<li>Смотреть только flamegraph и не проверять число коммитов: каскад эффектов так и останется незамеченным.</li>
<li>Игнорировать разницу render и commit: долгий commit — это DOM, а не React.</li>
<li>Профилировать на быстрой машине разработчика: throttling CPU 4x-6x приближает к реальным устройствам.</li>
<li>Оптимизировать компонент, который в ranked стоит 0.3 мс.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как измерить производительность у реальных пользователей?</strong> <code>&lt;Profiler&gt;</code> с отправкой в аналитику плюс web-vitals для INP и LCP. <strong>Что означает base duration в Profiler?</strong> Оценку времени рендера без мемоизации — сравнение с actual показывает, сколько мемоизация реально экономит.</p>`,
    code: `// программный замер конкретного поддерева
<Profiler id="OrdersTable" onRender={(id, phase, actual, base, start, commit) => {
  if (actual > 16) analytics.track('slow_render', { id, phase, actual });
}}>
  <OrdersTable />
</Profiler>
// phase: 'mount' | 'update' | 'nested-update'
// actual - фактическое время, base - оценка без мемоизации`,
    tip: 'Проговори разницу назначения: flamegraph отвечает на вопрос кто виноват в каскаде, ranked - что именно медленно. Кандидаты обычно знают только про flamegraph. И добавь честную оговорку: dev-сборка со StrictMode завышает цифры, доверять надо пропорциям, а не абсолютным миллисекундам.' },

  { id: 'rx36',
    q: 'Компонент перерендеривается, хотя пропсы «не менялись». Как ты найдёшь причину?',
    a: `<h4>Коротко</h4>
<p>Первым делом уточняю формулировку: «пропсы не менялись» почти всегда значит «не менялись по значению», а React сравнивает <strong>по ссылке</strong> через <code>Object.is</code>. Объектный литерал, массив, стрелка, результат <code>.map()</code> прямо в JSX — новые ссылки на каждом рендере. Дальше иду по пяти причинам в порядке частоты.</p>

<h4>Как это работает</h4>
<p><strong>1. Родитель отрендерился.</strong> Без <code>memo</code> ребёнок рендерится всегда, независимо от пропсов — это база, а не баг. Profiler с «why did this render» скажет буквально «parent rendered». Лечение: <code>memo</code>, либо приём с <code>children</code> — элемент, созданный выше по дереву, приходит той же ссылкой, и React пропустит поддерево без всякой мемоизации.</p>
<p><strong>2. Нестабильный проп.</strong> Profiler назовёт конкретное имя. Типичные виновники: инлайновый объект конфигурации, массив колонок таблицы, стрелка в обработчике, объект стилей.</p>
<p><strong>3. Контекст.</strong> Причина «context changed» означает либо нестабильное value провайдера, либо слишком широкий контекст. Здесь важно помнить: <code>memo</code> потребителя не спасает — обновление приходит по зависимостям на фибере, минуя сравнение пропсов.</p>
<p><strong>4. Селекторы стора и сторонние хуки.</strong> Селектор, возвращающий новый объект (<code>state =&gt; ({ a: state.a, b: state.b })</code>), даёт новую ссылку при каждом изменении любой части стора. В Zustand нужен <code>useShallow</code>, в Redux — <code>shallowEqual</code> или <code>createSelector</code>. То же с чужими хуками, которые не мемоизируют результат.</p>
<p><strong>5. <code>memo</code> есть, но не работает.</strong> Либо среди пропсов нестабильная функция, либо кастомный компаратор написан неверно — он должен вернуть <code>true</code>, когда рендер <strong>не нужен</strong>, и это регулярно путают.</p>
<p>Для точечной отладки — маленький хук, который сравнивает пропсы с предыдущими и печатает дифф с именами полей.</p>

<h4>Почему так</h4>
<p>Сравнение по ссылке — сознательный выбор: глубокое сравнение стоит времени, пропорционального размеру данных, и на больших объектах обошлось бы дороже самого рендера. React перекладывает решение на разработчика, который знает, что в его данных иммутабельно.</p>
<p>Цена такого дизайна ровно та, о которой этот вопрос: интуиция «значение то же» расходится с моделью «ссылка другая», и почти весь класс проблем с лишними рендерами растёт отсюда.</p>

<h4>Подводные камни</h4>
<ul>
<li>Ставить <code>memo</code>, не проверив пропсы: с нестабильным колбэком он бесполезен и только добавляет сравнение.</li>
<li>Считать лишний рендер багом: рендер дешёвого компонента может стоить микросекунды, и оптимизация не окупится.</li>
<li>Компаратор с перепутанной семантикой возврата.</li>
<li>Мемоизация ребёнка при нестабильном контексте — не сработает.</li>
<li>Дефолтные значения пропсов объектами: <code>{ options = {} }</code> создаёт новый объект каждый рендер.</li>
<li>Спред <code>{...props}</code> в мемоизированный компонент — гарантированно тащит все нестабильные ссылки родителя.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Почему memo не помог?</strong> Ищи функцию или литерал среди пропсов, либо контекст. <strong>Всегда ли лишний рендер надо чинить?</strong> Нет: чинить стоит, когда он измеримо влияет на INP или на длительность коммита; во всех остальных случаях он дешевле, чем усложнение кода.</p>`,
    code: `function useWhyDidYouUpdate(name: string, props: Record<string, unknown>) {
  const prev = useRef<Record<string, unknown>>();
  useEffect(() => {
    if (prev.current) {
      const changed = Object.entries(props)
        .filter(([k, v]) => prev.current![k] !== v)
        .map(([k, v]) => [k, { from: prev.current![k], to: v }]);
      if (changed.length) console.log('[why-update]', name, Object.fromEntries(changed));
    }
    prev.current = props;
  });
}

// частая причина: новая ссылка в JSX
<Table columns={[{ key: 'name' }]} onRow={r => open(r)} />   // оба пропа новые каждый рендер`,
    tip: 'Отдельно назови селекторы сторов без shallow-сравнения - это очень частая реальная причина, о которой почти не говорят на собеседованиях. И не забудь оговорку зрелого инженера: лишний рендер сам по себе не баг, чинить его стоит только когда он виден в профайлере.' },

  { id: 'rx37',
    q: 'Как правильно мемоизировать значение контекста и когда нужно разделять контексты?',
    a: `<h4>Коротко</h4>
<p>Контекст сравнивает значение <strong>по ссылке</strong> через <code>Object.is</code>, поэтому литерал <code>{{ user, setUser }}</code> в <code>value</code> будит всех потребителей на каждом рендере провайдера. Первый шаг — <code>useMemo</code>. Но он не лечит вторую проблему: селекторов у контекста нет, и при реальном изменении обновятся все, даже те, кому нужно другое поле.</p>

<h4>Как это работает</h4>
<p>Критерий разделения контекстов — не домен, а <strong>частота изменения</strong>. Медленно меняющееся (тема, локаль, текущий пользователь, права) отделяется от быстро меняющегося (позиция курсора, черновик формы, состояние перетаскивания). Смешаешь их в одном провайдере — редко нужное значение будет пересчитывать половину дерева на каждое движение мыши.</p>
<p>Второй приём — вынести <strong>стабильные функции</strong> в отдельный контекст. <code>dispatch</code> из <code>useReducer</code> стабилен по определению; набор действий стабилизируется <code>useMemo</code> с пустыми зависимостями, если внутри используются только сеттеры. Потребители такого контекста не перерисовываются при смене состояния вообще ни разу.</p>
<p>Третий слой — <code>children</code> как проп. Дети приходят готовыми элементами сверху; при рендере провайдера их ссылки те же, реконсилятор делает bailout и не спускается в поддерево. Перерисуются только реальные потребители.</p>
<p>Если и этого мало — внешний стор плюс <code>useSyncExternalStore</code> с селектором. Через контекст тогда идёт только ссылка на стор, которая не меняется никогда, а подписка на срез живёт мимо реконсиляции.</p>

<h4>Почему так</h4>
<p>Контекст — механизм доставки, а не хранения. Он решает задачу «дотянуть значение до глубоко вложенного компонента без prop drilling», и делает это на реконсиляции, где единственный доступный инструмент — сравнение ссылки. Селекторы потребовали бы отдельного механизма подписки; React намеренно оставил это библиотекам.</p>
<p>Цена всех приёмов — усложнение. Два-три провайдера вместо одного, хуки-обёртки, риск, что новый разработчик подпишется не на тот контекст. Поэтому дробить стоит по факту измеренной проблемы, а не превентивно: контекст с темой, меняющейся раз в сессию, оптимизировать бессмысленно.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>useMemo</code> с неполными зависимостями — потребители видят устаревшие данные; это молчаливый баг, а не падение.</li>
<li><code>memo</code> на потребителе как «оптимизация» — не работает, контекст обновляет фибер напрямую.</li>
<li>Провайдер сам рендерит дерево вместо <code>children</code> — вся выгода от разделения теряется.</li>
<li>Мемоизировать значение, которое и так примитив: <code>useMemo</code> вокруг строки только добавляет работу.</li>
<li>Дробить контексты до десятка провайдеров: дерево становится нечитаемым, а выигрыш нулевой.</li>
<li>Отдавать в контекст объект, собираемый из пропсов, без мемоизации — то же, что литерал.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Почему не сделать селекторы в контексте?</strong> Это требует подписки с произвольным сравнением — другая модель; частично это решает <code>use</code>-context-selector и полностью — внешний стор. <strong>Когда пора уходить от контекста?</strong> Когда значение меняется чаще, чем раз в несколько секунд, и читается точечно из десятков мест.</p>`,
    code: `function AppProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);

  const actions = useMemo(() => ({
    login: (u: User) => setUser(u),
    logout: () => setUser(null),
  }), []);                                     // стабильно навсегда

  return (
    <UserCtx value={user}>
      <ActionsCtx value={actions}>{children}</ActionsCtx>
    </UserCtx>
  );
  // children пришли сверху - не пересоздаются при рендере провайдера
}`,
    tip: 'Сформулируй критерий разделения контекстов как разную частоту изменения, а не разный домен. Так решение звучит обоснованно, а не по вкусу. И добавь приём с children как пропом: элементы приходят сверху той же ссылкой, поэтому поддерево не перерисовывается вовсе.' },

  { id: 'rx38',
    q: 'Как ты проектируешь кастомные хуки? Какие правила отличают хороший хук от плохого?',
    a: `<h4>Коротко</h4>
<p>Хук — это переиспользование <strong>логики, связанной с состоянием</strong>, а не способ спрятать код. Если внутри нет других хуков, это обычная функция и префикс <code>use</code> ей не нужен. Главное правило качества — <strong>стабильные ссылки на выходе</strong>: хук, возвращающий новый объект каждый рендер, ломает мемоизацию всем своим потребителям.</p>

<h4>Как это работает</h4>
<p><strong>Одна ответственность.</strong> <code>useUser</code> не должен заодно писать аналитику и синхронизировать localStorage. Смешение видно по числу аргументов и по тому, что хук нельзя использовать в половине мест без побочных эффектов.</p>
<p><strong>Стабильность выхода.</strong> Функции — через <code>useCallback</code>, составной результат — через <code>useMemo</code>. Иначе каждый компонент, положивший результат хука в зависимости эффекта или в пропсы мемоизированного ребёнка, получает лишний цикл. С React Compiler это делается автоматически, но контракт всё равно надо держать в голове: хук — публичное API.</p>
<p><strong>Форма возврата.</strong> Кортеж для двух-трёх значений (можно свободно переименовывать при деструктуризации), объект — когда больше, чтобы не запоминать порядок и брать только нужное.</p>
<p><strong>Хук не решает, как рендерить.</strong> Он возвращает данные и действия, а не JSX: иначе он перестаёт быть переиспользуемым и становится компонентом с неудобным интерфейсом.</p>
<p><strong>Разделение слоёв.</strong> <code>useOrders</code> (загрузка, кеш) и <code>useOrdersTable</code> (сортировка, выделение, пагинация) — разные хуки: они тестируются и переиспользуются независимо, и второй работает с любым источником данных.</p>
<p>Два приёма, которые сильно повышают качество: параметр-объект вместо позиционных аргументов (расширяется без ломающих изменений) и приём колбэков через ref — паттерн <code>useEvent</code>, чтобы нестабильный <code>onSuccess</code> не перезапускал подписку.</p>

<h4>Почему так</h4>
<p>Хуки заменили HOC и render props именно потому, что дают плоскую композицию без обёрток в дереве. Но у них другая цена: связь между хуком и компонентом невидима в JSX, поэтому неявные побочные эффекты внутри хука обнаруживаются только чтением исходников.</p>
<p>Ещё одна цена — <strong>состояние не разделяется</strong>. Два компонента, вызвавшие <code>useCart()</code>, получат две независимые копии состояния. Кандидаты регулярно ожидают обратного; общее состояние требует контекста или внешнего стора.</p>

<h4>Подводные камни</h4>
<ul>
<li>Хук-обёртка над одним <code>useState</code> «для красоты» — минус читаемость, плюс файл.</li>
<li>Возврат нового объекта без мемоизации — тихая деоптимизация у всех потребителей.</li>
<li>Колбэк в зависимостях эффекта: подписка пересоздаётся на каждый рендер родителя.</li>
<li>Хук, который сам решает показывать тост или редиректить, — непереиспользуем и неудобен в тестах.</li>
<li>Ожидание общего состояния между вызовами одного хука.</li>
<li>Условный вызов хука внутри своего хука — нарушение правил и bail out компилятора.</li>
<li>Слишком много аргументов позиционно: пятый булев параметр никто не прочитает.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сделать состояние общим для нескольких компонентов?</strong> Контекст с провайдером или внешний стор — сам по себе хук копий не разделяет. <strong>Зачем useEvent, если есть useCallback?</strong> <code>useCallback</code> замораживает замыкание вместе с зависимостями; <code>useEvent</code> даёт стабильную ссылку и при этом всегда свежее тело.</p>`,
    code: `function useDebouncedValue<T>(value: T, delay = 300): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

// приём: нестабильный колбэк через ref, чтобы не перезапускать подписку
function useEvent<T extends (...args: any[]) => any>(fn: T) {
  const ref = useRef(fn);
  useLayoutEffect(() => { ref.current = fn; });
  return useCallback(((...args) => ref.current(...args)) as T, []);
}`,
    tip: 'Правило стабильные ссылки на выходе - самое ценное здесь. Хук, возвращающий новый объект каждый рендер, ломает мемоизацию всем своим потребителям. Второе, что стоит сказать вслух: хук не разделяет состояние между вызовами - два компонента получат две независимые копии.' },

  { id: 'rx39',
    q: 'Как ты тестируешь кастомные хуки?',
    a: `<h4>Коротко</h4>
<p>Инструмент — <code>renderHook</code> из <code>@testing-library/react</code> (с React 18 он вернулся в основной пакет, отдельная <code>@testing-library/react-hooks</code> не нужна). Но главный принцип другой: если хук неразрывно связан с UI, тестировать его надо <strong>через компонент</strong>. <code>renderHook</code> — для универсальных хуков библиотечного уровня.</p>

<h4>Как это работает</h4>
<p><code>renderHook(cb, options)</code> монтирует крошечный компонент, который вызывает <code>cb</code>, и отдаёт <code>result.current</code> — то, что хук вернул на последнем рендере, — плюс <code>rerender(newProps)</code> для смены входных данных и <code>unmount()</code> для проверки cleanup.</p>
<p>Обновления, приходящие не через хелперы RTL (прокрутка фейковых таймеров, ручной резолв промиса, вызов колбэка из мока), оборачиваются в <code>act</code>. Асинхронные результаты ждутся через <code>waitFor</code> по <code>result.current</code>.</p>
<p>Что проверять, кроме значений: <strong>стабильность ссылок</strong>. Если хук обещает, что возвращаемая функция не пересоздаётся, это часть его публичного контракта — и её надо закрепить тестом, иначе рефакторинг молча сломает мемоизацию у всех потребителей.</p>
<p>Зависимости от окружения — через <code>wrapper</code>: <code>QueryClientProvider</code>, роутер, провайдер стора. Сеть — через MSW, а не мок <code>fetch</code>: тогда тест проверяет и URL, и тело, и обработку статусов.</p>
<p>Обязательно проверять cleanup: <code>unmount()</code> и ассерт, что подписка снята, таймер очищен, <code>AbortController</code> вызван.</p>

<h4>Почему так</h4>
<p>Тест через компонент устойчивее к рефакторингу: он привязан к наблюдаемому поведению, а не к форме возвращаемого объекта. Переименуешь поле внутри хука — компонентный тест не заметит, а изолированный упадёт, хотя ничего не сломалось.</p>
<p>Цена изоляции — обратная сторона: изолированный тест быстрее, точнее локализует ошибку и не требует рендерить UI. Поэтому граница проходит по назначению хука, а не по вкусу: библиотечный хук с публичным API — <code>renderHook</code>; прикладной хук одной фичи — через её компонент.</p>

<h4>Подводные камни</h4>
<ul>
<li>Забыть <code>act</code> вокруг прокрутки фейковых таймеров — предупреждение и непредсказуемый <code>result.current</code>.</li>
<li><code>userEvent</code> с фейковыми таймерами без <code>advanceTimers</code> в <code>setup()</code> — тест зависает.</li>
<li>Держать ссылку на <code>result.current</code> в переменной: она устаревает после rerender, читать надо каждый раз заново.</li>
<li>Не тестировать размонтирование — утечки не ловятся вообще.</li>
<li>Мокать <code>fetch</code> вместо MSW: проверяется факт вызова своей же функции.</li>
<li>Тестировать внутренние детали (какой именно <code>useState</code> вызвался) вместо контракта.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как протестировать хук с контекстом?</strong> Опция <code>wrapper</code> в <code>renderHook</code> — тот же провайдер, что в приложении. <strong>Как проверить, что эффект отписался?</strong> <code>unmount()</code> и ассерт на мок <code>removeEventListener</code> или на вызов <code>abort</code>.</p>`,
    code: `import { renderHook, act, waitFor } from '@testing-library/react';

test('дебаунсит значение', async () => {
  vi.useFakeTimers();
  const { result, rerender } = renderHook(
    ({ v }) => useDebouncedValue(v, 300),
    { initialProps: { v: 'a' } }
  );
  rerender({ v: 'b' });
  expect(result.current).toBe('a');
  act(() => { vi.advanceTimersByTime(300); });
  expect(result.current).toBe('b');
});

test('возвращает стабильную функцию', () => {
  const { result, rerender } = renderHook(() => useToggle());
  const first = result.current[1];
  rerender();
  expect(result.current[1]).toBe(first);
});`,
    tip: 'Мысль, которая выделяет: проверять стабильность возвращаемых ссылок и корректность cleanup при unmount как часть контракта хука. Почти никто про это не думает в тестах. И проговори границу: прикладной хук тестируется через компонент, renderHook - для библиотечных.' },

  { id: 'rx40',
    q: 'Как ты выбираешь запросы в Testing Library и почему порядок именно такой?',
    a: `<h4>Коротко</h4>
<p>Порядок такой: <code>getByRole</code> с опцией <code>name</code> → <code>getByLabelText</code> для полей форм → <code>getByPlaceholderText</code> → <code>getByText</code> → <code>getByDisplayValue</code> → <code>getByAltText</code>/<code>getByTitle</code> → и только в крайнем случае <code>getByTestId</code>. Причина не в эстетике: <code>getByRole</code> читает <strong>дерево доступности</strong>, и тест бесплатно становится проверкой доступности.</p>

<h4>Как это работает</h4>
<p>Браузер строит дерево доступности из семантики разметки: тег, ARIA-атрибуты, вычисленное доступное имя (из содержимого, <code>aria-label</code>, связанного <code>&lt;label&gt;</code>). <code>getByRole('button', { name: /сохранить/i })</code> ищет именно в нём. Если запрос находит элемент — его найдёт и скринридер, и клавиатурная навигация. Если <code>&lt;div onClick&gt;</code> по роли не находится, это не неудобство библиотеки, а корректный сигнал: для пользователя со скринридером этой кнопки не существует.</p>
<p><code>getByTestId</code> — escape hatch: он не проверяет ничего пользовательского и оправдан там, где семантики нет в принципе — контейнеры, обёртки, элементы с чисто визуальной ролью.</p>
<p>Три семейства запросов и их назначение: <code>getBy</code> — элемент есть сейчас, бросает с понятным дампом, если нет; <code>queryBy</code> — единственный способ проверить <strong>отсутствие</strong>, потому что возвращает <code>null</code> вместо броска; <code>findBy</code> — асинхронный, это <code>getBy</code> внутри <code>waitFor</code>, для элементов, которые появятся после запроса или транзишена. Плюс варианты <code>AllBy</code> для коллекций.</p>

<h4>Почему так</h4>
<p>Философия библиотеки: тест должен искать элемент так, как его находит человек. Такой тест устойчив к рефакторингу разметки — переименовал класс, поменял <code>div</code> на <code>section</code>, тест не заметил. И он ломается ровно тогда, когда ломается пользовательский сценарий.</p>
<p>Цена: запросы по роли многословнее и медленнее селекторов, а на плохо размеченном легаси половина элементов вообще недоступна по роли — придётся либо чинить разметку, либо ставить <code>data-testid</code>. Это неудобство и есть механизм давления в сторону семантики.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>waitFor</code> + <code>getBy</code> вместо <code>findBy</code>: то же самое, но многословнее и хуже читается.</li>
<li>Проверять отсутствие через <code>getBy</code> в <code>expect(...).toThrow()</code> — правильный инструмент <code>queryBy</code>.</li>
<li><code>getByText</code> по фразе, разорванной на несколько узлов: matcher по умолчанию работает по одному элементу, нужна функция-matcher.</li>
<li><code>container.querySelector('.btn-primary')</code> — тест привязан к стилям и ничего не проверяет по существу.</li>
<li>Точное совпадение строки вместо регулярки: любой пробел или неразрывный пробел ломает тест.</li>
<li><code>getByTestId</code> как основной инструмент — тесты зелёные, доступность сломана.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как найти элемент без доступного имени?</strong> Правильный ответ — добавить его: <code>aria-label</code> или связанный <code>&lt;label&gt;</code>; это исправление продукта, а не теста. <strong>Чем getByLabelText лучше getByPlaceholderText?</strong> Плейсхолдер не является заменой label: он исчезает при вводе и не читается частью скринридеров.</p>`,
    code: `// хорошо: по роли и доступному имени
await userEvent.click(screen.getByRole('button', { name: /сохранить/i }));
expect(screen.getByRole('textbox', { name: /email/i })).toHaveValue('a@b.ru');

// отсутствие - только queryBy
expect(screen.queryByRole('alert')).not.toBeInTheDocument();

// появится позже - findBy, а не waitFor + getBy
expect(await screen.findByRole('alert')).toHaveTextContent('Сохранено');

// плохо: тест не проверяет доступность и ломается при рефакторинге разметки
expect(container.querySelector('.btn-primary')).toBeTruthy();`,
    tip: 'Объясни причину, а не список: getByRole читает accessibility tree, поэтому тест заодно проверяет доступность. Это и есть аргумент за такой порядок. Сильный ход - сказать, что если элемент не находится по роли, чинить надо разметку, а не тест.' },

  { id: 'rx41',
    q: 'Когда нужен act, когда waitFor, и почему тесты «мигают» в CI?',
    a: `<h4>Коротко</h4>
<p><code>act</code> гарантирует, что все обновления состояния и эффекты, вызванные внутри, применены до продолжения теста. RTL уже оборачивает в него <code>render</code>, <code>fireEvent</code> и <code>userEvent</code>, поэтому руками его почти не пишут. <code>waitFor</code> — про ожидание условия. Мигание в CI почти всегда означает гонку, которую медленная и параллельная машина просто обнажила.</p>

<h4>Как это работает</h4>
<p>Внутри <code>act</code> React включает флаг, который заставляет его синхронно доводить работу до конца: применить очередь обновлений, выполнить эффекты, обработать порождённые ими обновления. Без этого тест может прочитать DOM в момент, когда эффект ещё не выполнился. Ручной <code>act</code> нужен там, где состояние меняется <strong>вне</strong> хелперов: прокрутка фейковых таймеров, ручной резолв промиса, вызов колбэка из мока.</p>
<p><code>waitFor</code> устроен как ретрай: он повторяет колбэк (по умолчанию каждые 50 мс, до таймаута в 1000 мс), пока тот не перестанет бросать. Использовать его стоит для побочных эффектов — «мок вызвался», «стор обновился». Для «элемент появится» лучше <code>findBy</code>: короче и уже включает <code>waitFor</code>.</p>
<p><strong>Почему мигает CI.</strong> Асинхронное обновление без ожидания — тест успевает проверить до прихода данных, и на быстрой локальной машине проскакивает. Несколько ассертов внутри одного <code>waitFor</code> — при падении непонятно, какая именно проверка не прошла, и ретраи маскируют причину. Фейковые таймеры вперемешку с <code>userEvent</code> без <code>advanceTimers</code> — тест зависает до таймаута. Неочищенные моки, таймеры и обработчики между тестами. Зависимость от порядка выполнения при параллельном запуске.</p>
<p>Правило: <strong>ноль произвольных задержек</strong>. Ни одного <code>setTimeout</code> на 100 мс — только ожидание конкретного условия.</p>

<h4>Почему так</h4>
<p><code>act</code> существует потому, что React намеренно асинхронен: обновления батчатся, пассивные эффекты выполняются после paint. Тест же должен видеть детерминированное состояние. <code>act</code> — это явная точка синхронизации между двумя моделями времени.</p>
<p>Цена: предупреждение «not wrapped in act» одно из самых раздражающих в экосистеме, и его часто гасят, вместо того чтобы понять, какое обновление осталось необработанным. Обычно это признак реальной гонки — эффект, который стреляет после того, как тест уже закончился.</p>

<h4>Подводные камни</h4>
<ul>
<li>Несколько ассертов внутри одного <code>waitFor</code>: держи ровно одну, остальные — снаружи после ожидания.</li>
<li>Ассерт на <strong>отсутствие</strong> внутри <code>waitFor</code> — он проходит сразу на первой итерации и ничего не проверяет.</li>
<li><code>userEvent</code> без <code>await</code>: в v14 все методы асинхронные.</li>
<li>Фейковые таймеры без <code>advanceTimers</code> в <code>userEvent.setup()</code>.</li>
<li>Увеличивать таймаут <code>waitFor</code>, чтобы «перестало мигать» — маскировка гонки, а не её устранение.</li>
<li>Не сбрасывать моки и таймеры между тестами: состояние течёт и ломает соседей при перестановке порядка.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как поймать плавающий тест локально?</strong> Прогнать сотню раз с рандомизированным порядком и с throttling CPU — гонка проявится. <strong>Что делать с предупреждением про act, если код правильный?</strong> Значит есть обновление после завершения теста: чаще всего незакрытая подписка или запрос без отмены в cleanup.</p>`,
    code: `// userEvent + фейковые таймеры: обязательно связать
const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });

// ручной act нужен только вне хелперов RTL
act(() => { vi.advanceTimersByTime(1000); });

// один ассерт внутри waitFor
await waitFor(() => expect(saveMock).toHaveBeenCalledTimes(1));
expect(saveMock).toHaveBeenCalledWith({ id: 1 });   // остальное - снаружи

// предпочтительно вместо waitFor + getBy
expect(await screen.findByText('Готово')).toBeVisible();`,
    tip: 'Совет, который звучит опытно: держать в waitFor ровно одну ассерцию. Иначе при падении непонятно, какая именно проверка не прошла. И отдельно назови ловушку: проверка на отсутствие внутри waitFor проходит на первой же итерации и не проверяет ничего.' },

  { id: 'rx42',
    q: 'Зачем MSW вместо мока fetch и как ты организуешь моки сети в тестах?',
    a: `<h4>Коротко</h4>
<p>MSW перехватывает запросы на уровне <strong>сети</strong> — Service Worker в браузере, интерсептор запросов в Node, — а не подменяет <code>fetch</code>. Поэтому тестируется реальный код запроса: URL, метод, заголовки, сериализация тела, разбор ответа, обработка статусов, ретраи, отмена. Мок <code>fetch</code> всё это пропускает и проверяет лишь то, что ты вызвал свою же функцию.</p>

<h4>Как это работает</h4>
<p>Хендлер описывает эндпоинт: <code>http.get('/api/orders', resolver)</code>. Резолвер получает разобранный запрос (параметры пути, query, тело) и возвращает <code>HttpResponse</code>. Всё, что лежит между твоим кодом и хендлером, — настоящий стек fetch, включая <code>AbortSignal</code>.</p>
<p>Второй большой плюс — <strong>переиспользование</strong>. Один набор хендлеров работает в юнит-тестах, в Storybook, в Playwright и в локальной разработке без бэкенда. Мок <code>fetch</code> живёт только в тестах, и параллельно приходится поддерживать второй набор фикстур.</p>
<p>Организация. Базовые хендлеры счастливого пути — в общем модуле. Сервер поднимается в <code>beforeAll</code> с <code>onUnhandledRequest: 'error'</code>: без этого забытый мок молча уйдёт в реальную сеть и тест начнёт мигать. <code>server.resetHandlers()</code> в <code>afterEach</code>, иначе переопределения протекают между тестами. <code>server.close()</code> в <code>afterAll</code>. Сценарии конкретного теста — через <code>server.use()</code> прямо в нём, рядом с ассертами.</p>
<p>Покрывать надо не только успех: 500, 401 с редиректом на логин, пустой список, невалидный JSON, медленный ответ через <code>delay()</code> для проверки скелетона, отменённый запрос.</p>

<h4>Почему так</h4>
<p>Ценность теста определяется тем, сколько настоящего кода он исполняет. Мок <code>fetch</code> вырезает весь транспортный слой — а именно там живут реальные баги: не тот метод, забытый заголовок, неправильно собранный query, необработанный 204 без тела.</p>
<p>Цена MSW: дополнительная зависимость и своя специфика настройки в jsdom (полифиллы для <code>TextEncoder</code>, <code>fetch</code>, <code>BroadcastChannel</code> в старых окружениях), плюс хендлеры надо поддерживать в согласии с контрактом API. Последнее решается генерацией хендлеров из OpenAPI-схемы.</p>

<h4>Подводные камни</h4>
<ul>
<li>Забыть <code>resetHandlers()</code> — переопределение из одного теста ломает следующий, причём непредсказуемо при параллельном запуске.</li>
<li><code>onUnhandledRequest</code> по умолчанию (<code>'warn'</code>): запрос уходит наружу, тест зависит от сети.</li>
<li>Относительный URL в Node-окружении без базового адреса — хендлер не срабатывает.</li>
<li>Тестировать только счастливый путь: обработка ошибок остаётся непокрытой ровно там, где ошибки и случаются.</li>
<li>Хендлеры расходятся с реальным API — тесты зелёные, прод сломан; лечится контрактными тестами или генерацией из схемы.</li>
<li>Мокать внутренние функции приложения вместо сети — тест снова проверяет сам себя.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем MSW отличается от подмены модуля API-клиента?</strong> Подмена вырезает весь клиент; MSW оставляет его в игре и проверяет. <strong>Как избежать расхождения моков и бэкенда?</strong> Генерировать хендлеры из OpenAPI и держать контрактный тест, который прогоняет схему против реального сервиса.</p>`,
    code: `// handlers.ts
export const handlers = [
  http.get('/api/orders', () => HttpResponse.json([{ id: 1, total: 100 }])),
];

// setup.ts
beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

// в конкретном тесте - переопределяем сценарий ошибки
test('показывает ошибку при 500', async () => {
  server.use(http.get('/api/orders', () => new HttpResponse(null, { status: 500 })));
  render(<Orders />);
  expect(await screen.findByRole('alert')).toHaveTextContent(/не удалось/i);
});`,
    tip: 'Аргумент, который решает спор: MSW тестирует ваш слой запросов, мок fetch тестирует, что вы вызвали свою же функцию. Плюс переиспользование в Storybook и Playwright. И назови настройку, которая спасает от мигающих тестов: onUnhandledRequest error.' },

  { id: 'rx43',
    q: 'Как типизировать дженерик-компонент в React с TypeScript?',
    a: `<h4>Коротко</h4>
<p>Обычная функция-компонент типизируется дженериком напрямую: TypeScript выведет <code>T</code> из пропсов в месте использования. Ломались всегда обёртки — <code>forwardRef</code> и <code>memo</code> возвращают не-дженерик тип и стирают параметр. В React 19 <code>forwardRef</code> не нужен, так что осталась только проблема с <code>memo</code>.</p>

<h4>Как это работает</h4>
<p>Вывод идёт по связи между пропсами. В <code>&lt;List items={orders} renderItem={o =&gt; ...} /&gt;</code> компилятор берёт <code>T</code> из <code>items: readonly T[]</code> и подставляет его в <code>renderItem: (item: T) =&gt; ReactNode</code> и <code>getKey: (item: T) =&gt; React.Key</code>. Дженерик здесь не украшение: без него <code>renderItem</code> получит <code>unknown</code> или <code>any</code>, и весь смысл компонента исчезнет.</p>
<p>Синтаксическая ловушка: в <code>.tsx</code> запись <code>&lt;T&gt;</code> в стрелочной функции парсится как JSX-элемент. Нужна либо висячая запятая <code>&lt;T,&gt;</code>, либо ограничение <code>&lt;T extends unknown&gt;</code>. В обычном объявлении <code>function List&lt;T&gt;</code> проблемы нет — ещё один довод в пользу function-деклараций для компонентов.</p>
<p>Сужение: <code>T extends { id: string }</code> позволяет обойтись без <code>getKey</code>, но привязывает компонент к форме данных. Для литеральных значений в TS 5+ есть <code>const</code>-параметр (<code>&lt;const T&gt;</code>), чтобы вывод не расширялся до <code>string[]</code> вместо кортежа литералов.</p>
<p><code>memo(List)</code> возвращает <code>MemoExoticComponent</code>, у которого дженерик уже стёрт. Штатное решение — приведение <code>as typeof List</code>: типы сохраняются, поведение мемоизации остаётся.</p>

<h4>Почему так</h4>
<p>Дженерик-компонент — это способ связать два пропса контрактом, который проверяется на месте вызова. Альтернатива — <code>any</code> в рендер-функции — снимает всю защиту ровно там, где ошибиться проще всего: при обращении к полю элемента.</p>
<p>Цена: сообщения об ошибках при неудачном выводе становятся длинными и малочитаемыми, а сложные дженерики заметно нагружают tsserver. Поэтому дженерик оправдан для 3–5 переиспользуемых примитивов дизайн-системы, а не для каждого компонента списка в фиче.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>&lt;T&gt;</code> в стрелке внутри <code>.tsx</code> — синтаксическая ошибка, нужна запятая.</li>
<li><code>memo</code> без приведения — компонент внезапно перестаёт выводить тип, и ошибки вылезают у потребителей.</li>
<li>Дефолт <code>&lt;T = any&gt;</code>: выглядит удобно, отключает проверку целиком.</li>
<li><code>items: T[]</code> вместо <code>readonly T[]</code> — не примешь <code>as const</code>-массив и результат <code>Object.freeze</code>.</li>
<li>Дженерик, который нигде не выводится из пропсов: TypeScript подставит <code>unknown</code>, и ошибка проявится внутри компонента.</li>
<li>Перегруженные условные типы ради красоты — минуты ожидания подсказок в редакторе.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сохранить дженерик под forwardRef в React 18?</strong> Приведение обёртки или объявление собственного типа рендер-функции; в 19 проблема исчезает вместе с <code>forwardRef</code>. <strong>Когда дженерик избыточен?</strong> Когда компонент работает с одной конкретной сущностью — тогда честный тип читается лучше абстракции.</p>`,
    code: `type ListProps<T> = {
  items: readonly T[];
  getKey: (item: T) => React.Key;
  renderItem: (item: T, index: number) => React.ReactNode;
  empty?: React.ReactNode;
};

export function List<T>({ items, getKey, renderItem, empty }: ListProps<T>) {
  if (!items.length) return <>{empty}</>;
  return <ul>{items.map((it, i) => <li key={getKey(it)}>{renderItem(it, i)}</li>)}</ul>;
}

// memo теряет дженерик - возвращаем его приведением
export const MemoList = memo(List) as typeof List;

// в .tsx стрелка требует запятой, иначе парсится как JSX
const identity = <T,>(v: T): T => v;`,
    tip: 'Упомяни, что memo и forwardRef стирают дженерик и требуют приведения as typeof Component. Это боль всех, кто писал дизайн-систему, и её узнают сразу. Плюс мелочь, которая выдаёт практика: в .tsx стрелке нужна висячая запятая, иначе <T> парсится как JSX.' },

  { id: 'rx44',
    q: 'Как сделать полиморфный компонент с пропом as и корректной типизацией?',
    a: `<h4>Коротко</h4>
<p>Полиморфный компонент рендерится разным тегом: <code>&lt;Text as="a" href="..."&gt;</code>. Типизация обязана давать <strong>ровно те пропсы</strong>, которые допустимы для выбранного тега, и ошибку при недопустимых. Сделать это можно, но цена высокая — и правильный ответ включает альтернативу <code>asChild</code>.</p>

<h4>Как это работает</h4>
<p>Скелет типа: дженерик <code>C extends React.ElementType</code> со значением по умолчанию; собственные пропсы объединяются с <code>React.ComponentPropsWithoutRef&lt;C&gt;</code>; из нативных вычитаются ключи собственных через <code>Omit</code>, иначе при совпадении имён (например <code>size</code> у <code>input</code>) типы конфликтуют и схлопываются в <code>never</code>. Ref добавляется отдельно как <code>React.ComponentPropsWithRef&lt;C&gt;['ref']</code>, чтобы не потерять правильный тип узла.</p>
<p>В рантайме всё просто: <code>const Tag = as || 'span'</code> и спред остатка пропсов. Важно, чтобы переменная начиналась с заглавной буквы — иначе JSX сочтёт её именем DOM-тега.</p>
<p>Альтернатива <code>asChild</code> из Radix: компонент не рендерит свой тег вообще, а <strong>клонирует единственного ребёнка</strong> через <code>cloneElement</code>, слив свои пропсы, обработчики и ref с его собственными. Типизация тривиальная — обычный булев проп, — а семантику выбирает разработчик, написав нужный тег руками.</p>

<h4>Почему так</h4>
<p>Полиморфизм решает реальную проблему дизайн-системы: кнопка, которая иногда должна быть ссылкой, заголовок, который иногда <code>h2</code>, а иногда <code>h3</code>. Без этого появляются <code>ButtonLink</code>, <code>LinkButton</code> и десяток почти одинаковых компонентов.</p>
<p>Цена, которую нужно назвать честно: эти типы разворачиваются в огромные объединения всех HTML-элементов и заметно замедляют tsserver в большом проекте — подсказки и проверка типов начинают тормозить на секунды. Сообщения об ошибках становятся нечитаемыми простынями. И легко потерять доступность: <code>as="div"</code> у кнопки убивает Enter/Space, фокус и роль. Именно поэтому Radix пошёл в <code>asChild</code>: тот же результат без деградации инструментов.</p>

<h4>Подводные камни</h4>
<ul>
<li>Забыть <code>Omit</code> при конфликте имён — проп получает тип <code>never</code>, и ошибка выглядит необъяснимо.</li>
<li>Строчная буква в переменной тега: <code>&lt;tag /&gt;</code> отрендерится как несуществующий DOM-элемент.</li>
<li>Не ограничить набор тегов: <code>as="table"</code> у кнопки типизируется корректно и ломает разметку.</li>
<li>Потеря семантики и клавиатуры при подмене интерактивного тега на <code>div</code>/<code>span</code>.</li>
<li><code>asChild</code> с несколькими детьми — <code>cloneElement</code> работает ровно с одним, иначе рантайм-ошибка.</li>
<li>При <code>asChild</code> забыть слить обработчики: свой <code>onClick</code> перетрёт пользовательский.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как ограничить допустимые теги?</strong> Сузить дженерик: <code>C extends 'a' | 'button' | 'span'</code> — и типы проще, и доступность не потеряется. <strong>Что лучше в дизайн-системе?</strong> <code>asChild</code>: дешевле для tsserver, честнее по семантике; полиморфный <code>as</code> оставляют для чисто текстовых примитивов.</p>`,
    code: `type AsProp<C extends React.ElementType> = { as?: C };
type PropsToOmit<C extends React.ElementType, P> = keyof (AsProp<C> & P);

type Polymorphic<C extends React.ElementType, Props = {}> =
  React.PropsWithChildren<Props & AsProp<C>> &
  Omit<React.ComponentPropsWithoutRef<C>, PropsToOmit<C, Props>> &
  { ref?: React.ComponentPropsWithRef<C>['ref'] };

type TextProps = { size?: 'sm' | 'lg' };

export function Text<C extends React.ElementType = 'span'>(
  { as, size = 'sm', children, ...rest }: Polymorphic<C, TextProps>
) {
  const Tag = as || 'span';
  return <Tag data-size={size} {...rest}>{children}</Tag>;
}

<Text as="a" href="/docs">Док</Text>      // href разрешён
<Text as="span" href="/docs" />           // ошибка типов

// альтернатива без тяжёлых типов: asChild клонирует ребёнка
function Button({ asChild, ...props }: { asChild?: boolean } & ButtonProps) {
  const Comp = asChild ? Slot : 'button';
  return <Comp {...props} />;
}
<Button asChild><a href="/docs">Док</a></Button>   // семантику выбирает вызывающий`,
    tip: 'Назови цену полиморфных типов - деградацию tsserver и нечитаемые ошибки - и предложи asChild как альтернативу. Это ответ архитектора, а не разработчика. Добавь практичный компромисс: сузить дженерик до трёх-четырёх допустимых тегов вместо всего ElementType.' },

  { id: 'rx45',
    q: 'Как ты типизируешь пропсы компонента и refs в TypeScript? Какие утилиты используешь?',
    a: `<h4>Коротко</h4>
<p>Базовый набор: <code>React.ComponentProps&lt;'button'&gt;</code> для пропсов тега, <code>ComponentPropsWithoutRef</code> и <code>ComponentPropsWithRef</code> — когда нужно явно; <code>React.ComponentProps&lt;typeof MyComp&gt;</code> достаёт пропсы чужого компонента, если он не экспортировал тип. Рефы в React 19 — обычный проп <code>ref?: React.Ref&lt;HTMLInputElement&gt;</code>. <code>React.FC</code> не использую.</p>

<h4>Как это работает</h4>
<p><strong>Расширение нативного элемента.</strong> <code>interface ButtonProps extends ComponentPropsWithoutRef&lt;'button'&gt; { variant?: 'primary' | 'ghost' }</code> — компонент сразу принимает <code>onClick</code>, <code>disabled</code>, <code>type</code>, все <code>aria-*</code> и <code>data-*</code>. Если свой проп конфликтует по имени с нативным, нативный вычитается через <code>Omit</code>, иначе типы пересекутся и дадут <code>never</code>.</p>
<p><strong>Дети.</strong> <code>React.ReactNode</code> — всё, что можно отрендерить, включая <code>null</code>, строки и массивы. <code>React.ReactElement</code> — когда нужен именно элемент (для <code>cloneElement</code> или <code>asChild</code>). Тип <code>JSX.Element</code> уже, чем кажется, и на возвращаемое значение компонента лучше не ставить.</p>
<p><strong>Рефы.</strong> <code>useRef&lt;HTMLInputElement&gt;(null)</code> даёт объект с nullable <code>current</code>; <code>useRef&lt;number&gt;(0)</code> — мутабельный контейнер для значения между рендерами. В React 19 приём ref снаружи — просто проп; для императивного хендла — <code>React.Ref&lt;MyHandle&gt;</code> вместе с <code>useImperativeHandle</code>.</p>
<p><strong>Обработчики.</strong> Готовые типы <code>React.ChangeEventHandler&lt;HTMLInputElement&gt;</code>, <code>React.MouseEventHandler</code> вместо ручной сигнатуры — они дают правильный <code>currentTarget</code>, что важнее <code>target</code>: у первого тип точный, у второго это любой узел внутри.</p>
<p><strong>Почему не React.FC.</strong> Он мешает дженерикам, добавляет лишние поля вроде <code>propTypes</code>, а исторически ещё и подмешивал <code>children</code> всем подряд. Обычная функция с явным типом пропсов проще и работает во всех случаях.</p>

<h4>Почему так</h4>
<p>Смысл этих утилит — не описывать вручную то, что уже описано в типах React и DOM. Ручной <code>{ onClick?: () =&gt; void }</code> теряет объект события, не даёт <code>aria-*</code> и расходится со спецификацией при каждом обновлении.</p>
<p>Цена: <code>extends ComponentPropsWithoutRef</code> открывает наружу <strong>всё</strong>, включая <code>style</code>, <code>className</code> и <code>onDrag</code>. Иногда это нежелательно — компонент дизайн-системы, разрешающий произвольный <code>style</code>, перестаёт быть контрактом. Тогда пропсы перечисляются явно, и это осознанный выбор в пользу строгости.</p>

<h4>Подводные камни</h4>
<ul>
<li>Конфликт имён без <code>Omit</code>: проп получает <code>never</code>, и сообщение об ошибке этого не объясняет.</li>
<li><code>e.target</code> вместо <code>e.currentTarget</code> — тип шире, чем ожидается, и приходится кастовать.</li>
<li><code>React.FC</code> плюс дженерик — не работает, тип стирается.</li>
<li><code>useRef&lt;HTMLDivElement&gt;()</code> без <code>null</code>: получишь <code>MutableRefObject</code>, который React не примет в атрибут <code>ref</code>.</li>
<li>Расширять <code>ComponentPropsWithoutRef</code> у компонента, который ref всё же принимает: снаружи ref не типизируется.</li>
<li><code>any</code> в пропсах-колбэках «чтобы не мучиться» — там ошибки и живут.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем ComponentProps отличается от HTMLAttributes?</strong> <code>HTMLAttributes</code> — только атрибуты, без специфичных для тега (<code>href</code>, <code>type</code>) и без ref. <strong>Как типизировать компонент, который может вернуть null?</strong> Никак специально: возвращаемый тип выводится сам, и <code>ReactNode</code> его покрывает.</p>`,
    code: `interface ButtonProps extends React.ComponentPropsWithoutRef<'button'> {
  variant?: 'primary' | 'ghost';
  ref?: React.Ref<HTMLButtonElement>;      // React 19: ref обычный проп
}

export function Button({ variant = 'primary', className, ref, ...rest }: ButtonProps) {
  return <button ref={ref} data-variant={variant} className={className} {...rest} />;
}

// переопределение конфликтующего пропа
type InputProps = Omit<React.ComponentPropsWithoutRef<'input'>, 'onChange'> & {
  onChange: (value: string) => void;
};

// пропсы чужого компонента без экспорта типа
type DatePickerProps = React.ComponentProps<typeof DatePicker>;`,
    tip: 'Скажи, почему не используешь React.FC - это короткий маркер, по которому видно, что ты типизируешь React осознанно, а не по шаблону из туториала. И добавь деталь про currentTarget вместо target в обработчиках: у первого тип точный, у второго это любой узел внутри.' },

  { id: 'rx46',
    q: 'Как ты делаешь анимации в React? Что даёт Framer Motion и что такое layout animations?',
    a: `<h4>Коротко</h4>
<p>Иерархия по стоимости: простые состояния — CSS-переходы и <code>@keyframes</code> (ноль JS, работа в компоузиторе); появление и удаление из DOM — библиотека, которая удерживает элемент до конца анимации (<code>AnimatePresence</code>); изменения вёрстки — <strong>layout animations</strong> через FLIP. Анимировать имеет смысл только <code>transform</code> и <code>opacity</code>.</p>

<h4>Как это работает</h4>
<p><strong>Почему CSS не хватает на удаление.</strong> Как только React убирает элемент из дерева, узел исчезает из DOM в том же коммите — анимировать нечего. <code>AnimatePresence</code> перехватывает это: держит удалённый элемент смонтированным, проигрывает <code>exit</code> и только потом отпускает. Для этого у детей обязаны быть стабильные <code>key</code>.</p>
<p><strong>Layout animations и FLIP.</strong> Проп <code>layout</code> анимирует изменение позиции и размера, вызванное <strong>вёрсткой</strong>, а не явными значениями: элемент переехал, потому что над ним что-то удалили. Механика FLIP: измерить положение <strong>F</strong>irst, дать браузеру применить новое <strong>L</strong>ast, вычислить разницу и <strong>I</strong>nvert её обратным <code>transform</code>, затем <strong>P</strong>lay — анимировать трансформ к нулю. Раз двигается только трансформ, layout за кадр не пересчитывается.</p>
<p><code>layoutId</code> даёт shared-element переход: два элемента с одинаковым id в разных местах дерева анимируются друг в друга — так делают «карточка разворачивается в модалку».</p>
<p>Что анимировать: <code>transform</code> и <code>opacity</code> обрабатываются компоузитором и не требуют пересчёта layout и paint. <code>width</code>, <code>height</code>, <code>top</code>, <code>margin</code> вызывают reflow на каждом кадре — на списке это гарантированные пропуски кадров.</p>

<h4>Почему так</h4>
<p>Библиотека берёт на себя две вещи, которые на CSS не делаются: удержание элемента при выходе и автоматический FLIP для непредсказуемых изменений вёрстки. За это платим бандлом — полный <code>motion</code> заметно тяжёлый, поэтому в проде берут <code>LazyMotion</code> с подгружаемым набором фич и <code>m</code>-компонентами вместо <code>motion</code>.</p>
<p>Второй компромисс — доступность. Анимация без уважения к <code>prefers-reduced-motion</code> может вызывать физический дискомфорт у людей с вестибулярными расстройствами. Это не опция: длительность обнуляется или переход заменяется простым появлением.</p>

<h4>Подводные камни</h4>
<ul>
<li>Анимировать <code>height</code> в списке — reflow каждый кадр; для раскрытия используют <code>grid-template-rows</code> или <code>scaleY</code> с компенсацией.</li>
<li><code>AnimatePresence</code> с <code>key</code> по индексу: exit проигрывается не у того элемента.</li>
<li>Забыть <code>prefers-reduced-motion</code>.</li>
<li>Импортировать полный <code>motion</code> в приложении с одной анимацией — десятки килобайт впустую.</li>
<li><code>layout</code> на элементе с текстом без <code>layout="position"</code> — текст растягивается вместе с контейнером.</li>
<li>Анимации входа в виртуализированном списке: элементы «появляются» просто из-за скролла.</li>
<li>Анимировать через <code>setState</code> в <code>requestAnimationFrame</code> — рендер React на каждый кадр вместо работы компоузитора.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Когда достаточно CSS?</strong> Всегда, кроме удаления из DOM, непредсказуемых изменений вёрстки и жестов. <strong>Что выбрать для переходов между страницами?</strong> Нативный View Transitions API: он дешевле, потому что анимирует снимки в компоузиторе, и в React 19 есть компонент-обёртка.</p>`,
    code: `import { motion, AnimatePresence, useReducedMotion } from 'motion/react';

function Card({ item, expanded, onToggle }) {
  const reduce = useReducedMotion();
  return (
    <motion.div layout layoutId={'card-' + item.id} onClick={onToggle}
      transition={reduce ? { duration: 0 } : { type: 'spring', stiffness: 300, damping: 30 }}>
      <motion.h3 layout="position">{item.title}</motion.h3>
      <AnimatePresence>
        {expanded && (
          <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            {item.body}
          </motion.p>
        )}
      </AnimatePresence>
    </motion.div>
  );
}`,
    tip: 'Объясни layout animations через FLIP - First, Last, Invert, Play: измерить до и после, компенсировать обратным трансформом, анимировать к нулю. Знание механики отличает от знания названия пропа. И объясни, почему CSS не умеет exit-анимации: узел исчезает из DOM в том же коммите.' },

  { id: 'rx47',
    q: 'Что такое View Transitions и как они соотносятся с React?',
    a: `<h4>Коротко</h4>
<p>View Transitions — браузерный API: браузер снимает текущее состояние, ты <strong>синхронно</strong> меняешь DOM внутри <code>document.startViewTransition</code>, браузер снимает второе состояние и анимирует переход между снимками через дерево псевдоэлементов. Анимирует компоузитор, а не главный поток, поэтому это дешевле любой JS-библиотеки.</p>

<h4>Как это работает</h4>
<p>После вызова браузер строит дерево псевдоэлементов: <code>::view-transition-group</code>, внутри — <code>::view-transition-old</code> и <code>::view-transition-new</code>. По умолчанию это кросс-фейд корня. Элементы, которым присвоен <code>view-transition-name</code>, выделяются в собственные группы и анимируются отдельно — так получается morph одного элемента в другой при смене экрана.</p>
<p><strong>Конфликт с React</strong> в асинхронности: API требует, чтобы DOM изменился синхронно внутри колбэка, а React решает, когда коммитить, сам. Обходной путь через <code>flushSync</code> работал, но убивал конкурентный рендеринг и запрещал приостановку. React решил это компонентом <code>&lt;ViewTransition&gt;</code>: он знает границы коммита и сам открывает и закрывает транзишен. Переход запускается для обновлений внутри <code>startTransition</code> и при реавиле Suspense-границы, что автоматически покрывает навигацию.</p>
<p>Обязательные детали: <code>view-transition-name</code> должен быть <strong>уникален в момент перехода</strong> — два одинаковых имени на экране ломают анимацию целиком; проверка поддержки (<code>document.startViewTransition</code> может отсутствовать) с корректным фолбэком; и отключение через <code>prefers-reduced-motion</code>.</p>

<h4>Почему так</h4>
<p>Идея API — снять с разработчика необходимость координировать два состояния UI вручную. Библиотеке для shared-element перехода нужно держать оба элемента в дереве, измерять их и синхронизировать; браузеру достаточно двух снимков, которые он и так делает при отрисовке.</p>
<p>Цена: контроль ниже, чем у JS-анимации. Прервать переход на середине и перенаправить его нельзя так же гибко; жесты (свайп назад с отслеживанием пальца) требуют отдельного API. Снимки статичны — видео и анимированный контент во время перехода замирают. И это всё ещё сравнительно новая платформенная возможность, поэтому фолбэк обязателен.</p>

<h4>Подводные камни</h4>
<ul>
<li>Дублирующийся <code>view-transition-name</code> (например у элементов списка) — анимация не запускается вовсе.</li>
<li><code>flushSync</code> ради перехода — отключает конкурентность и может вызвать предупреждение при вызове во время рендера.</li>
<li>Забыть фолбэк для браузеров без поддержки: переход не произойдёт, а если код на него завязан — навигация сломается.</li>
<li>Долгие переходы: пользователь ждёт анимацию вместо контента, INP растёт.</li>
<li>Анимировать переход, за которым следует загрузка данных, — снимок «после» окажется скелетоном.</li>
<li>Не отключить анимацию при <code>prefers-reduced-motion</code>.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Чем это лучше Framer Motion?</strong> Работа в компоузиторе и отсутствие бандла; хуже — контроль и поддержка жестов. <strong>Как сделать переход между страницами в MPA?</strong> Через cross-document view transitions: правило <code>@view-transition { navigation: auto; }</code> в CSS, без JS вообще.</p>`,
    code: `// нативный API
function navigate(url: string) {
  if (!document.startViewTransition) { setRoute(url); return; }
  document.startViewTransition(() => flushSync(() => setRoute(url)));
}

// React: без flushSync
import { unstable_ViewTransition as ViewTransition } from 'react';

<ViewTransition>
  <Suspense fallback={<Skeleton />}>
    <Page id={id} />
  </Suspense>
</ViewTransition>

// CSS
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*) { animation: none; }
}`,
    tip: 'Назови конкретную причину, почему View Transitions плохо дружили с React: API требует синхронного изменения DOM, а React обновляет асинхронно. Отсюда и появился компонент ViewTransition. Добавь практическую ловушку: view-transition-name обязан быть уникален в момент перехода, дубли ломают анимацию целиком.' },

  { id: 'rx48',
    q: 'Как ты организуешь интернационализацию в React/Next приложении?',
    a: `<h4>Коротко</h4>
<p>Три слоя. <strong>Хранение</strong>: JSON по неймспейсам, ключи семантические (<code>checkout.submit</code>), а не по тексту. <strong>Форматирование</strong>: нативный <code>Intl</code> — никаких самописных склонений и форматов дат. <strong>Доставка</strong>: локаль в сегменте пути, словарь только нужного языка, в RSC — перевод на сервере, чтобы словарь вообще не ехал в браузер.</p>

<h4>Как это работает</h4>
<p><strong>Главная техническая ошибка — конкатенация строк.</strong> «Найдено » + n + « товаров» невозможно перевести: в русском четыре плюральные формы (one/few/many/other), в английском две, в арабском шесть. Правильный инструмент — ICU MessageFormat: <code>{count, plural, one {# товар} few {# товара} many {# товаров} other {# товара}}</code>. Правило выбора формы берётся из <code>Intl.PluralRules</code>, то есть из данных CLDR, а не из твоего <code>if</code>.</p>
<p>Форматирование числами и датами — тоже <code>Intl</code>: <code>NumberFormat</code> (валюта, проценты, компактная запись), <code>DateTimeFormat</code>, <code>RelativeTimeFormat</code> («вчера» вместо «1 день назад»), <code>ListFormat</code> («A, B и C»). Всё это уже в браузере и в Node, бандл не растёт.</p>
<p>В App Router локаль живёт в сегменте <code>/[locale]/...</code>, определяется в middleware по cookie и заголовку <code>Accept-Language</code>, а <code>generateStaticParams</code> позволяет отдать статику под каждый язык. Ключевой момент производительности — <strong>грузить только нужную локаль</strong>: динамический импорт словаря по коду языка, иначе в бандл уезжают все переводы сразу.</p>
<p>Не забыть про разметку: <code>lang</code> и <code>dir</code> на <code>&lt;html&gt;</code>; для RTL — логические CSS-свойства (<code>margin-inline-start</code> вместо <code>margin-left</code>), иначе арабская версия рассыплется; <code>hreflang</code> и локализованные <code>metadata</code> для SEO; интерполяция React-элементов через Trans-компонент, а не <code>dangerouslySetInnerHTML</code>.</p>

<h4>Почему так</h4>
<p>Языки различаются не только словами: порядком слов, направлением письма, числом форм множественного числа, форматом дат и разделителями разрядов. Любая самописная логика воспроизводит подмножество CLDR и рано или поздно расходится с ним. <code>Intl</code> — это CLDR, уже встроенный в платформу.</p>
<p>Цена i18n честная: словари надо синхронизировать между языками (пропущенный ключ — фолбэк или пустое место), длина текста меняется на 30–40% и ломает вёрстку с фиксированной шириной, а перевод строк в коде превращает читаемый JSX в набор ключей. Отсюда правило: ключи должны быть семантическими и группироваться по экрану, иначе через год их никто не найдёт.</p>

<h4>Подводные камни</h4>
<ul>
<li>Конкатенация вместо плейсхолдеров — самый частый и самый дорогой в исправлении баг.</li>
<li>Ключ, равный английскому тексту: изменение исходной фразы ломает все переводы.</li>
<li>Загрузка всех локалей в бандл — легко сотни килобайт.</li>
<li>Даты через <code>toLocaleDateString</code> без явной локали: результат зависит от настроек пользователя и отличается на сервере и клиенте, отсюда несовпадение гидратации.</li>
<li>Забыть <code>dir="rtl"</code> и физические CSS-свойства.</li>
<li>Тексты в изображениях и в <code>alt</code> без перевода.</li>
<li>Не покрыть фолбэком отсутствующий ключ — пользователь видит <code>checkout.submit</code>.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как не тащить словарь на клиент?</strong> Переводить в серверных компонентах и передавать вниз готовые строки; клиентскому провайдеру отдавать только те ключи, что реально нужны интерактивным частям. <strong>Как ловить пропущенные переводы?</strong> Скриптом сверять наборы ключей между локалями в CI и падать на расхождении.</p>`,
    code: `// ICU: плюрализация, а не конкатенация
{
  "cart.items": "{count, plural, one {# товар} few {# товара} many {# товаров} other {# товара}}",
  "order.status": "Заказ {id} от {date, date, medium}"
}

// форматирование через Intl, без самописных функций
new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB' }).format(1990);
new Intl.RelativeTimeFormat('ru', { numeric: 'auto' }).format(-1, 'day');   // вчера

// Next App Router
export function generateStaticParams() {
  return ['ru', 'en'].map(locale => ({ locale }));
}`,
    tip: 'Скажи про четыре плюральные формы в русском и ICU MessageFormat - это сразу показывает, что ты делал i18n, а не подключал библиотеку по инструкции. Второй маркер опыта: toLocaleDateString без явной локали даёт разный результат на сервере и клиенте и ломает гидратацию.' },

  { id: 'rx49',
    q: 'Что ты проверяешь в React-компоненте с точки зрения доступности?',
    a: `<h4>Коротко</h4>
<p>Первое правило — <strong>семантика вместо ARIA</strong>. Нативный <code>&lt;button&gt;</code> бесплатно даёт роль, фокус, Enter и Space, состояние <code>disabled</code> и корректное поведение в формах; <code>&lt;div onClick&gt;</code> не даёт ничего, и чинить его пятью ARIA-атрибутами хуже, чем взять правильный тег. Дальше — доступное имя, фокус, клавиатура, live-регионы.</p>

<h4>Как это работает</h4>
<p><strong>Доступное имя.</strong> У каждого интерактивного элемента должно быть имя: текст внутри, <code>aria-label</code>, <code>aria-labelledby</code>. Кнопка-иконка без имени звучит как «кнопка» — пользователь не знает, что она делает. Проверяется одной строкой в тесте: <code>getByRole('button', { name: ... })</code>.</p>
<p><strong>Формы.</strong> Связь <code>&lt;label htmlFor&gt;</code> с <code>id</code> поля, где id генерируется через <code>useId</code>. Ошибка помечается <code>aria-invalid</code> и связывается с полем через <code>aria-describedby</code>; сам текст ошибки — в контейнере с <code>role="alert"</code>, чтобы он был объявлен.</p>
<p><strong>Фокус.</strong> Порядок обхода должен совпадать с визуальным; видимость фокуса обязательна — <code>:focus-visible</code>, а не <code>outline: none</code>; весь сценарий должен проходиться без мыши. Ловушки: <code>tabindex</code> больше нуля ломает порядок, а элемент, скрытый только визуально, остаётся в порядке табуляции.</p>
<p><strong>Динамика.</strong> Изменения, о которых надо сообщить, идут в live-регион: <code>role="status"</code> (<code>aria-live="polite"</code>) для нейтральных, <code>role="alert"</code> для ошибок. Регион должен существовать в DOM <strong>до</strong> появления текста, иначе часть скринридеров его не прочитает.</p>
<p><strong>Модалки.</strong> Фокус внутрь при открытии, ловушка фокуса, Escape, возврат фокуса на триггер, <code>aria-modal</code>, недоступность фона. Нативный <code>&lt;dialog&gt;</code> с <code>showModal()</code> делает большую часть этого сам, включая top layer и inert-фон.</p>
<p>Инструменты в процессе, а не постфактум: <code>eslint-plugin-jsx-a11y</code>, <code>axe-core</code> в тестах и Storybook, ручной проход клавиатурой и скринридером.</p>

<h4>Почему так</h4>
<p>Нативные элементы несут поведение, накопленное платформой: разное на десктопе и мобильном, разное в разных скринридерах, работающее с голосовым управлением и переключателями. Воспроизвести это вручную нельзя — можно только приблизить.</p>
<p>Цена честная: автоматические проверки ловят порядка трети реальных проблем. Контраст, осмысленность порядка фокуса, адекватность объявлений — только руками. Поэтому «axe зелёный» не равно «доступно», и говорить об этом на собеседовании выгодно.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>outline: none</code> без замены — клавиатурный пользователь теряет позицию на экране.</li>
<li><code>aria-label</code> на неинтерактивном <code>div</code> — не даёт ни роли, ни фокуса.</li>
<li>Дублирование: <code>&lt;button aria-label="Сохранить"&gt;Сохранить&lt;/button&gt;</code> — имя перекрывается, читается один раз, но расхождение текстов путает голосовое управление.</li>
<li>Live-регион, создаваемый вместе с сообщением, — объявление не произойдёт.</li>
<li>Плейсхолдер вместо label: исчезает при вводе, не читается частью скринридеров.</li>
<li><code>disabled</code> на кнопке отправки без объяснения причины: фокус на неё не встаёт, и пользователь не понимает, что не так.</li>
<li>Скрытие через <code>display: none</code> того, что должно быть доступно только визуально скрытым — нужен класс <code>visually-hidden</code>.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Что проверить в первую очередь на готовом экране?</strong> Пройти его целиком с клавиатуры: это ловит больше половины проблем за минуту. <strong>Когда ARIA всё же нужна?</strong> Для составных виджетов без нативного аналога — комбобокс, дерево, таб-панель; и там лучше взять готовую библиотеку с реализованным паттерном из WAI-ARIA Authoring Practices.</p>`,
    code: `// автоматическая проверка в тестах
import { axe } from 'jest-axe';
test('без нарушений a11y', async () => {
  const { container } = render(<Checkout />);
  expect(await axe(container)).toHaveNoViolations();
});

// live-регион для асинхронного результата
<div role="status" aria-live="polite">{saved && 'Изменения сохранены'}</div>

// ошибка поля правильно связана
const id = useId();
<input id={id} aria-invalid={!!error} aria-describedby={error ? id + '-err' : undefined} />
{error && <p id={id + '-err'} role="alert">{error}</p>}`,
    tip: 'Свяжи a11y с тестами: getByRole в Testing Library не найдёт div с onClick, поэтому доступная разметка получается побочным эффектом хороших тестов. И скажи вслух ограничение: автоматические проверки ловят около трети проблем, остальное - проход клавиатурой и скринридером.' },

  { id: 'rx50',
    q: 'Расскажи про Feature-Sliced Design: слои, правила импортов и где он не работает.',
    a: `<h4>Коротко</h4>
<p>FSD задаёт три измерения: <strong>слои</strong> (app, pages, widgets, features, entities, shared; <code>processes</code> объявлен устаревшим), <strong>слайсы</strong> внутри слоя по бизнес-домену (user, order, cart) и <strong>сегменты</strong> внутри слайса по технической природе (ui, model, api, lib, config). Правило одно: импортировать можно только из слоёв строго ниже.</p>

<h4>Как это работает</h4>
<p>Помимо направления вниз действует запрет на импорты <strong>внутри одного слоя</strong>: слайсы-соседи друг друга не видят. Это и есть механизм, который убивает циклические зависимости и делает удаление фичи предсказуемым — вырезал папку, и хвостов не осталось.</p>
<p>Второе правило — публичный API. Наружу торчит только <code>index.ts</code> слайса; импорт вглубь (<code>features/auth/ui/LoginForm</code>) запрещён. Это даёт свободу рефакторить внутренности без правок в потребителях.</p>
<p>Ключевой момент: правила должны проверяться <strong>линтером</strong> — <code>steiger</code> для FSD целиком или <code>eslint-plugin-boundaries</code> для описания слоёв руками. Соглашение без автоматической проверки перестаёт соблюдаться за пару спринтов, и это не про дисциплину людей, а про то, что нарушение не видно на ревью diff-а.</p>

<h4>Почему так</h4>
<p>Обычное деление по типам (<code>components</code>, <code>hooks</code>, <code>utils</code>) не масштабируется: код одной фичи размазан по шести папкам, удалить её невозможно, зависимости идут во все стороны. FSD переводит структуру на язык домена и вводит явное направление зависимостей — то же, зачем в бэкенде нужна чистая архитектура.</p>
<p>Цена и она реальная. Слой <code>features</code> разрастается и превращается в свалку из десятков однофайловых слайсов. Сущность, нужная двум слайсам одного слоя, вынуждает либо дублировать, либо тащить в <code>shared</code>, где ей не место. Спор «это widget или feature» не имеет объективного ответа и съедает время ревью. Плюс много файлов-барррелей и лишних <code>index.ts</code>.</p>
<p>Ответ методологии на это — <strong>pages-first подход</strong> из FSD 2.1: начинать со страниц, держать код там, и выносить вниз только когда переиспользование <strong>случилось</strong>, а не когда его предположили.</p>

<h4>Подводные камни</h4>
<ul>
<li>Преждевременное вынесение в <code>features</code> — главная реальная ошибка внедрения.</li>
<li>Импорт мимо публичного API: работает, ломает инкапсуляцию, не ловится без линтера.</li>
<li><code>shared</code> как «папка для всего»: туда стекается бизнес-логика, и слой перестаёт быть переиспользуемым.</li>
<li>Кросс-импорты между слайсами одного слоя «только в этот раз».</li>
<li>Барели, ломающие tree-shaking: <code>index.ts</code>, реэкспортирующий всё, тянет в бандл лишнее.</li>
<li>Внедрение FSD на команде из двух человек и проекте на двадцать экранов — оверхед превысит пользу.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Куда положить общий для двух фич код?</strong> В нижний слой — <code>entities</code>, если это про сущность, или <code>shared</code>, если это техническая утилита; кросс-импорт запрещён именно чтобы заставить принять это решение. <strong>Как жить с Next App Router, где есть своя папка <code>app</code>?</strong> Оставить роутинг Next тонким, а страницы держать в FSD-слое <code>pages</code> и импортировать оттуда.</p>`,
    code: `src/
  app/        # провайдеры, роутер, стили - знает про всё
  pages/      # композиция страниц
  widgets/    # самостоятельные блоки UI (Header, OrderCard)
  features/   # пользовательские сценарии (AddToCart, LoginForm)
  entities/   # бизнес-сущности (User, Product) + их ui и model
  shared/     # ui-kit, api-клиент, утилиты - не знает ни про что

// нарушение: entities импортирует из features
import { addToCart } from 'features/add-to-cart';   // запрещено линтером

// правильно: features использует entities
import { ProductCard } from 'entities/product';`,
    tip: 'Обязательно скажи про pages-first из FSD 2.1 и про то, что преждевременное вынесение в features - главная реальная ошибка. Это показывает опыт эксплуатации, а не чтения доки. И подчеркни, что правило импортов обязано проверяться линтером: соглашение без автоматики перестаёт работать за пару спринтов.' },

  { id: 'rx51',
    q: 'Атомарный дизайн, FSD, слоистая архитектура — как выбрать и как они сочетаются?',
    a: `<h4>Коротко</h4>
<p>Они про разное и не конкурируют. <strong>Atomic Design</strong> — про UI-компоненты (atoms → molecules → organisms → templates → pages), про бизнес-логику и данные он молчит. <strong>FSD</strong> — про деление по бизнес-доменам и направление зависимостей. <strong>Слоистая/чистая архитектура</strong> — про изоляцию домена от инфраструктуры. Рабочая комбинация: Atomic внутри <code>shared/ui</code>, FSD — для всего остального.</p>

<h4>Как это работает</h4>
<p>Atomic Design честно работает там, где компоненты действительно не знают про домен: кнопка, инпут, иконка, поле с подписью. Как только компонент начинает знать про заказ или пользователя, классификация «молекула или организм» теряет объективный критерий — и превращается в спор на ревью без правильного ответа.</p>
<p>FSD подхватывает ровно с этого места: деление идёт по домену, а не по визуальной сложности. <code>entities/product</code> знает про товар, <code>features/add-to-cart</code> — про сценарий, <code>widgets/order-card</code> — про самостоятельный блок.</p>
<p>Чистая архитектура добавляет третье измерение — независимость домена от способа доставки данных. На фронтенде она проявляется скромнее, чем на бэкенде: обычно достаточно, чтобы модель не знала про конкретный HTTP-клиент, а компоненты не импортировали DTO напрямую.</p>
<p>Критерий выбора — масштаб команды. До трёх-пяти человек и пары десятков экранов: плоская структура по фичам, без церемоний; FSD здесь чистый оверхед. Несколько команд в одной кодовой базе: нужны жёсткие границы и автоматическая проверка — FSD окупается. Микрофронтенды: границы между модулями важнее внутренней структуры каждого.</p>

<h4>Почему так</h4>
<p>Любая методология — это способ сузить пространство решений, чтобы новый человек не изобретал структуру заново. Ценность не в названии, а в том, что ответ на вопрос «куда положить этот файл» не требует обсуждения.</p>
<p>Отсюда главный практический вывод, который важнее выбора методологии: <strong>направление зависимостей должно проверяться автоматически</strong>. Архитектура без линтера деградирует за квартал независимо от того, как она названа — просто потому, что нарушение не видно в diff-е и всегда есть срочная задача.</p>
<p>Цена жёсткой методологии — бюрократия: лишние файлы, барели, обсуждения границ. Цена её отсутствия — размазанный код и невозможность удалить фичу. Выбор между ними зависит от того, сколько людей одновременно правят репозиторий.</p>

<h4>Подводные камни</h4>
<ul>
<li>Внедрять FSD на маленькой команде «на вырост» — платишь сейчас, выгода гипотетическая.</li>
<li>Тянуть Atomic Design на доменные компоненты: споры без критерия.</li>
<li>Методология без линтера — декларация, а не архитектура.</li>
<li>Полная миграция большого проекта разом вместо постепенной по новым фичам.</li>
<li>Копировать чистую архитектуру с бэкенда буквально: три слоя абстракций вокруг одного fetch.</li>
<li>Спорить о названиях слоёв вместо того, чтобы зафиксировать правило импортов.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как мигрировать постепенно?</strong> Новые фичи по новым правилам, линтер только на новых директориях, старый код переносится при касании. <strong>Что делать, если команда не согласна?</strong> Зафиксировать минимум — направление зависимостей и публичный API слайса — и включить его в CI; остальное можно обсуждать бесконечно.</p>`,
    code: `// Комбинация на практике
src/
  shared/ui/       # Atomic Design живёт здесь: Button, Input, Icon
  entities/user/
    ui/UserAvatar.tsx
    model/store.ts
    api/queries.ts
  features/auth/

// граница проверяется линтером
// eslint-plugin-boundaries / steiger
{
  "boundaries/elements": [
    { "type": "shared",   "pattern": "src/shared/*" },
    { "type": "entities", "pattern": "src/entities/*" }
  ],
  "boundaries/element-types": [{ "from": "entities", "allow": ["shared"] }]
}`,
    tip: 'Ключевая фраза: архитектура, не проверяемая линтером, разрушается за квартал. Она переводит разговор с названий методологий на реальную дисциплину. И привяжи выбор к масштабу команды, а не к моде: до пяти человек FSD - оверхед, на нескольких командах он окупается.' },

  { id: 'rx52',
    q: 'Как устроена обработка ошибок в RSC и Next App Router? В чём разница error.tsx и global-error.tsx?',
    a: `<h4>Коротко</h4>
<p><code>error.tsx</code> — клиентский Error Boundary (обязательно <code>'use client'</code>), которым Next автоматически оборачивает сегмент маршрута. Он ловит ошибки этого сегмента и его детей, но <strong>не ловит ошибки собственного layout</strong>, потому что рендерится внутри него. <code>global-error.tsx</code> ловит именно корневой layout и заменяет его целиком.</p>

<h4>Как это работает</h4>
<p>Граница получает два пропа: <code>error</code> и <code>reset</code>. <code>reset()</code> пытается перерендерить сегмент заново — работает, если ошибка была временной (сеть моргнула), и не работает, если причина в данных.</p>
<p><strong>global-error.tsx</strong> подменяет корневой layout, поэтому обязан рендерить собственные <code>&lt;html&gt;</code> и <code>&lt;body&gt;</code>. Забыть это — получить белый экран вместо страницы ошибки. В dev-режиме он не показывается: там Next отдаёт свой оверлей, и проверять его нужно в проде.</p>
<p><strong>Серверные ошибки в проде обезличены.</strong> Next вырезает сообщение и стек, оставляя только <code>error.digest</code> — хеш, по которому ошибка находится в серверных логах. Это защита от утечки внутренних данных, и команде это надо проговорить: искать текст ошибки в браузере бесполезно, digest нужно передать в мониторинг.</p>
<p><strong>Управляющие исключения.</strong> <code>notFound()</code> и <code>redirect()</code> реализованы через <code>throw</code> специального объекта, который Next перехватывает выше. Обернёшь их в <code>try/catch</code> — блок съест управляющее исключение, и вместо редиректа получишь обработку «ошибки». Правильно вызывать их <strong>после</strong> try/catch.</p>
<p>Ошибки Server Actions — отдельная тема: ожидаемые (валидация, конфликт) возвращаем значением, иначе граница сотрёт форму вместе с введёнными данными.</p>

<h4>Почему так</h4>
<p>Разделение границ по сегментам даёт локализацию отказа: упавший виджет аналитики не должен уносить весь дашборд. Клиентская природа <code>error.tsx</code> нужна, чтобы работали <code>reset</code> и интерактивность страницы ошибки.</p>
<p>Цена обезличивания серверных ошибок — усложнённая отладка прода: без настроенного мониторинга у тебя есть только хеш и ничего больше. Поэтому логирование в <code>useEffect</code> границы и на сервере — не опция, а обязательная часть настройки.</p>

<h4>Подводные камни</h4>
<ul>
<li>Ждать, что <code>error.tsx</code> поймает ошибку своего layout — нужна граница уровнем выше.</li>
<li><code>global-error.tsx</code> без <code>&lt;html&gt;</code> и <code>&lt;body&gt;</code> — белый экран.</li>
<li><code>redirect()</code> внутри <code>try/catch</code> — молча не срабатывает.</li>
<li>Не логировать ошибку в границе: в мониторинге её не будет вообще, у пользователя только «что-то пошло не так».</li>
<li>Ошибки в обработчиках событий и в асинхронном коде Error Boundary <strong>не ловит</strong> — это ограничение React, а не Next.</li>
<li>Кнопка «Повторить» без ограничения попыток: если ошибка детерминированная, пользователь зациклится.</li>
<li>Проверять <code>global-error</code> только в dev, где он не показывается.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как показать 404 из серверного компонента?</strong> Вызвать <code>notFound()</code> — отрисуется ближайший <code>not-found.tsx</code>. <strong>Что не ловит Error Boundary?</strong> Ошибки в обработчиках, в <code>setTimeout</code>, в асинхронном коде после await и ошибки самого себя — их надо ловить вручную и переводить в состояние.</p>`,
    code: `'use client';
export default function Error({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  useEffect(() => { logToSentry(error); }, [error]);   // иначе ошибка невидима для мониторинга
  return (
    <div role="alert">
      <p>Что-то пошло не так</p>
      {error.digest && <code>{error.digest}</code>}
      <button onClick={reset}>Повторить</button>
    </div>
  );
}

// ЛОВУШКА: redirect бросает исключение
try {
  await save();
  redirect('/done');       // будет поймано catch ниже!
} catch (e) { /* ... */ }
// правильно: redirect после try/catch`,
    tip: 'Назови две неочевидности: error.tsx не ловит ошибки своего же layout, и redirect/notFound работают через throw, поэтому ломаются внутри try/catch. Третья, которая добивает: в проде серверная ошибка приходит без текста и стека, только с error.digest для поиска в логах.' },

  { id: 'rx53',
    q: 'Как работает стриминг в Next App Router и что делает loading.tsx?',
    a: `<h4>Коротко</h4>
<p>Стриминг — сервер отдаёт HTML кусками по мере готовности вместо ожидания самых медленных данных. <code>loading.tsx</code> — сахар: Next оборачивает <code>page.tsx</code> сегмента в <code>&lt;Suspense&gt;</code> с этим фолбэком. Гранулярность у него грубая — точнее расставлять границы руками вокруг конкретных медленных блоков.</p>

<h4>Как это работает</h4>
<p>Технически это <code>renderToReadableStream</code>. Сначала уходит <strong>shell</strong> — всё, что отрендерилось без приостановки, плюс заглушки на местах Suspense-границ. Затем, по мере резолва промисов, сервер дописывает в тот же поток куски HTML и крошечные inline-скрипты, которые переставляют готовый контент на место фолбэка. Гидратация при этом идёт выборочно: части, чей HTML уже приехал, становятся интерактивными раньше остальных.</p>
<p>Что это даёт по метрикам: <strong>TTFB</strong> падает — первый байт не ждёт БД; <strong>FCP</strong> падает вместе с ним; <strong>LCP</strong> улучшается, только если крупный элемент попал в shell, иначе он приедет тем же потоком и выигрыша не будет.</p>
<p><strong>Ограничения, которые часто забывают.</strong> После первого байта статус ответа и заголовки уже отправлены — <code>redirect()</code>, смена HTTP-статуса и установка cookie после начала стрима невозможны; всё это решается до shell. Некоторые прокси, серверы и CDN <strong>буферизуют</strong> ответ и отдают его целиком, полностью убивая эффект — это проверяется <code>curl -N</code> на проде, а не в дев-режиме.</p>

<h4>Почему так</h4>
<p>Классический SSR — это блокирующая модель: пока не готовы все данные, не отдаётся ничего. Одна медленная панель на странице задерживает весь HTML. Стриминг разрывает эту связь: медленное перестаёт быть общим знаменателем.</p>
<p>Цена: сложнее отладка (ответ приходит частями, и ошибка после shell уже не превратится в 500), выше требования к инфраструктуре, и появляется риск CLS — если скелетон не совпадает по размерам с контентом, страница прыгает при подстановке.</p>

<h4>Подводные камни</h4>
<ul>
<li><code>loading.tsx</code> на весь сегмент: быстрый заголовок и навигация тоже прячутся под скелетон.</li>
<li>Скелетон другой высоты — прыжок макета и просадка CLS.</li>
<li><code>await</code> в корневом layout: он рендерится до shell, и стриминга не будет вообще — вся страница снова ждёт самый медленный запрос.</li>
<li>Попытка сделать <code>redirect()</code> после начала стрима — уже поздно.</li>
<li>Буферизующий прокси в проде: локально всё отлично, на сервере эффекта нет.</li>
<li>Слишком много мелких границ: контент появляется мозаикой и мельтешит.</li>
<li>Ожидание, что стриминг ускорит сами запросы — он меняет только порядок доставки.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как проверить, что стриминг реально работает?</strong> <code>curl -N</code> на прод-URL: куски должны приходить с задержкой, а не одним блоком. <strong>Что делать, если нужен статус 404 при отсутствии данных?</strong> Проверить это до первого байта — в том же сегменте до Suspense-границы — и вызвать <code>notFound()</code> там.</p>`,
    code: `// грубо: весь сегмент под одним скелетоном
// app/orders/loading.tsx
export default function Loading() { return <OrdersSkeleton />; }

// точнее: быстрое сразу, медленное - потоком
export default function Page() {
  return (
    <>
      <Header />                                  {/* в shell, мгновенно */}
      <Suspense fallback={<StatsSkeleton />}>
        <Stats />                                 {/* медленный запрос */}
      </Suspense>
      <Suspense fallback={<TableSkeleton />}>
        <OrdersTable />                           {/* очень медленный */}
      </Suspense>
    </>
  );
}`,
    tip: 'Скажи про ограничение: после начала стриминга статус ответа и заголовки уже ушли, поэтому редирект и 404 надо решать до первого байта. И назови убийцу стриминга, который встречается чаще всего: await в корневом layout - он рендерится до shell и снова блокирует всю страницу.' },

  { id: 'rx54',
    q: 'Что такое параллельные маршруты в Next и какие задачи они решают?',
    a: `<h4>Коротко</h4>
<p>Параллельные маршруты — слоты, объявленные папками с <code>@</code> (<code>app/@team</code>, <code>app/@analytics</code>). Layout получает каждый слот <strong>отдельным пропом</strong> и размещает сам. Каждый слот имеет собственную навигацию, свои <code>loading.tsx</code> и <code>error.tsx</code>. Самая болезненная деталь — обязательный <code>default.tsx</code>.</p>

<h4>Как это работает</h4>
<p>Папка со слотом не создаёт сегмент URL — она добавляет ветку в дерево маршрутизации. Next держит для каждого слота <strong>отдельное состояние</strong>: свой активный подмаршрут, своя граница ошибки, свой Suspense. Отсюда и польза: упавшая аналитика не уносит панель команды, а медленный слот стримится независимо и не задерживает быстрые.</p>
<p><strong><code>default.tsx</code> и два вида навигации.</strong> При клиентской навигации Next помнит, что было в каждом слоте, и не трогает неактивные. При <strong>полной перезагрузке</strong> состояние слотов взять неоткуда: рендерится <code>default.tsx</code>. Если его нет — Next отдаёт 404 для всей страницы. Отсюда самый частый баг: всё работает при переходах и разваливается при F5 или при открытии ссылки из мессенджера.</p>
<p>Второй типовой кейс — условный рендер целых разделов: layout по роли рендерит либо <code>{admin}</code>, либо <code>{user}</code>, и внутри каждого слота живёт полноценное дерево маршрутов со своей навигацией.</p>

<h4>Почему так</h4>
<p>Обычная композиция компонентов не даёт независимых границ и независимых URL-состояний: один <code>error.tsx</code> на сегмент, один <code>loading.tsx</code>, одна история навигации. Для дашборда, где панели живут своей жизнью, это неудобно. Слоты дают то же, что вложенные роутеры в SPA, но декларативно и с сохранением серверного рендеринга.</p>
<p>Цена: структура папок усложняется и становится непонятной без знания конвенций; отладка того, какой именно слот отрендерился, требует внимания; и правило про <code>default.tsx</code> невозможно вывести из кода — его нужно просто знать.</p>

<h4>Подводные камни</h4>
<ul>
<li>Забыть <code>default.tsx</code> — 404 при полной перезагрузке; проверять всегда через F5, а не только кликами.</li>
<li>Считать, что слот добавляет сегмент в URL — не добавляет, адрес формируют обычные сегменты.</li>
<li>Не добавить слот в пропсы layout: он тихо не отрендерится, ошибки не будет.</li>
<li>Взаимозависимые слоты: если один нуждается в данных другого, независимость мнимая и лучше обычная композиция.</li>
<li>Условный рендер слота по роли, вычисленной на клиенте: серверный рендер отдаст не то, будет мигание.</li>
<li>Много слотов ради красоты — сложность растёт быстрее пользы.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сделать так, чтобы слот менял URL?</strong> Внутри слота объявляются обычные сегменты; активный подмаршрут слота отражается в адресе, если он объявлен как реальный путь. <strong>Зачем это, если можно просто отрендерить два компонента?</strong> Ради независимых границ ошибки, загрузки и навигации — компоненты этого не дают.</p>`,
    code: `app/
  layout.tsx
  @team/page.tsx
  @team/default.tsx        # обязателен: иначе 404 при полной перезагрузке
  @analytics/page.tsx
  @analytics/default.tsx
  page.tsx

export default function Layout({
  children, team, analytics,
}: { children: React.ReactNode; team: React.ReactNode; analytics: React.ReactNode }) {
  const role = getRole();
  return (
    <div className="grid">
      {children}
      {role === 'admin' ? analytics : null}
      {team}
    </div>
  );
}`,
    tip: 'default.tsx и разница между клиентской навигацией и полной перезагрузкой - главный практический подвох параллельных маршрутов. Назови его сам и добавь симптом: работает при переходах, разваливается при F5 или при открытии ссылки из мессенджера.' },

  { id: 'rx55',
    q: 'Что такое перехватывающие маршруты и как сделать модалку с сохранением URL?',
    a: `<h4>Коротко</h4>
<p>Перехватывающие маршруты позволяют при <strong>клиентской навигации</strong> отрендерить один маршрут в контексте другого, не уходя со страницы. Синтаксис относительный: <code>(.)</code> — тот же уровень, <code>(..)</code> — на уровень выше, <code>(..)(..)</code> — на два, <code>(...)</code> — от корня <code>app</code>. Каноничный кейс — модалка с собственным URL.</p>

<h4>Как это работает</h4>
<p>Сценарий галереи: клик по фото в ленте открывает модалку поверх ленты и меняет адрес на <code>/photo/123</code>. Прямой заход по этому URL, обновление страницы или переход из мессенджера отдают полноценную страницу фото. Ссылка шарится, кнопка «назад» закрывает модалку — то есть URL остаётся честным состоянием приложения.</p>
<p>Собирается это в связке с <strong>параллельным маршрутом</strong>: слот <code>@modal</code> плюс перехватывающий сегмент <code>@modal/(.)photo/[id]</code>. Полный маршрут <code>photo/[id]/page.tsx</code> при этом никуда не девается. При клиентской навигации Next подставляет перехваченную версию в слот; при полной загрузке слот берёт <code>default.tsx</code>, который возвращает <code>null</code>, и рендерится настоящая страница.</p>
<p>Закрытие модалки — это <code>router.back()</code>, а не размонтирование компонента: состояние живёт в истории браузера, и просто убрать модалку из дерева нельзя, иначе URL останется прежним.</p>
<p>Тонкость счёта уровней: <code>(..)</code> считает <strong>сегменты маршрута</strong>, а не папки файловой системы. Группы вида <code>(marketing)</code> сегментов не создают, и из-за этого счёт регулярно сбивается — это первая вещь, которую надо проверить, если перехват не срабатывает.</p>

<h4>Почему так</h4>
<p>Модалка без URL — плохой UX: её нельзя расшарить, кнопка «назад» закрывает всю страницу, обновление теряет контекст. Ручная реализация «модалка плюс query-параметр» требует дублировать содержимое в двух местах: в модалке и на полной странице. Перехват даёт один компонент и два способа его показать.</p>
<p>Цена: конвенция сложная, из структуры папок неочевидная, и человек без знания синтаксиса не поймёт, что происходит. Плюс перехват работает <strong>только</strong> через <code>&lt;Link&gt;</code> и методы роутера — при <code>window.location.href</code> будет обычная навигация.</p>

<h4>Подводные камни</h4>
<ul>
<li>Забыть <code>default.tsx</code> в слоте — 404 при перезагрузке.</li>
<li>Считать <code>(..)</code> по папкам, а не по сегментам; группы <code>(...)</code> сбивают счёт.</li>
<li>Закрывать модалку размонтированием вместо <code>router.back()</code> — URL остаётся на фото.</li>
<li>Дублировать разметку в перехвате и в полной странице вместо общего компонента.</li>
<li>Не проверить прямой заход по URL — на проде это основной сценарий из поиска и соцсетей.</li>
<li>Забыть доступность модалки: фокус, Escape, <code>aria-modal</code> — перехват их не даёт.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Почему перехват не сработал?</strong> Либо навигация была не через <code>Link</code>, либо неверно посчитаны уровни <code>(..)</code>. <strong>Когда проще обойтись без этого?</strong> Когда модалка не нуждается в собственном URL — тогда обычное состояние компонента честнее и понятнее.</p>`,
    code: `app/
  feed/page.tsx
  photo/[id]/page.tsx                 # полная страница (прямой заход)
  @modal/default.tsx                  # return null
  @modal/(.)photo/[id]/page.tsx       # перехват при клиентской навигации
  layout.tsx                          # рендерит {children} и {modal}

// @modal/(.)photo/[id]/page.tsx
'use client';
export default function PhotoModal({ params }) {
  const router = useRouter();
  return (
    <Dialog open onOpenChange={() => router.back()}>   {/* назад, а не unmount */}
      <Photo id={params.id} />
    </Dialog>
  );
}`,
    tip: 'Уточни, что уровни в скобках считаются по сегментам маршрута, а не по папкам - route groups в скобках сегмент не создают, и на этом все спотыкаются. И назови вторую ловушку: закрытие модалки - это router.back(), а не размонтирование, иначе URL останется на фото.' },

  { id: 'rx56',
    q: 'Для чего используется middleware в Next и какие у него ограничения?',
    a: `<h4>Коротко</h4>
<p>Middleware — код в <code>middleware.ts</code>, выполняющийся <strong>до</strong> обработки запроса на всех путях, подходящих под <code>matcher</code>. Умеет <code>redirect</code>, <code>rewrite</code> (адрес в строке не меняется), установку заголовков и cookie, ранний ответ. Главное правило: <strong>middleware проверяет наличие токена, а не права</strong>.</p>

<h4>Как это работает</h4>
<p>Запрос попадает в middleware до роутинга и до рендера. Ответ <code>NextResponse.next()</code> пропускает его дальше, <code>rewrite</code> подменяет внутренний путь без изменения URL у пользователя, <code>redirect</code> обрывает обработку. Заголовки, выставленные здесь, доходят и до ответа, и до серверных компонентов.</p>
<p>Хорошие кейсы: определение локали и редирект на <code>/ru/...</code>; A/B-тесты через rewrite на разные варианты страницы; геороутинг; security-заголовки и CSP-nonce; лёгкая проверка сессионной куки; флаги фич.</p>
<p><strong>Плохие кейсы</strong> — и это то, что проверяют. Полноценная авторизация в middleware не работает: код исполняется в Edge Runtime, где нет Node API, нет драйверов БД, нет <code>bcrypt</code>, ограничены размер бандла и CPU-время. Проверить пароль или сходить в базу за ролями там нельзя.</p>
<p>Второй аргумент — стоимость. Middleware выполняется на <strong>каждом</strong> подходящем запросе, включая префетчи <code>&lt;Link&gt;</code>, которых на странице со списком могут быть десятки. Отсюда требование сужать <code>matcher</code>: исключить <code>_next/static</code>, <code>_next/image</code>, favicon и статику, иначе платишь латентностью и деньгами за раздачу картинок.</p>

<h4>Почему так</h4>
<p>Edge-исполнение выбрано ради околонулевого холодного старта и близости к пользователю: редирект по локали должен стоить единицы миллисекунд, а не поднимать Node-функцию. Ограничения среды — прямая цена этого выбора.</p>
<p>Отсюда правильный паттерн: в middleware дешёвая проверка наличия и формальной валидности токена плюс редирект анонимов; настоящая проверка прав — в layout, page или Server Action, <strong>рядом с доступом к данным</strong>. Так защита не обходится прямым запросом к экшену и не зависит от того, покрыл ли matcher нужный путь.</p>

<h4>Подводные камни</h4>
<ul>
<li>Считать middleware защитой: экшены и route handlers доступны напрямую, и матчер их может не покрывать.</li>
<li>Широкий matcher — middleware на каждом запросе за картинкой.</li>
<li>Тяжёлая работа в Edge: проверка JWT-подписи через Web Crypto нормальна, поход в БД — нет.</li>
<li>Ожидание, что <code>rewrite</code> изменит URL в браузере — не изменит, для этого <code>redirect</code>.</li>
<li>Забыть, что префетч тоже проходит через middleware, и построить на нём аналитику посещений.</li>
<li>Ставить cookie в middleware и ждать, что они уже видны текущему рендеру — они уйдут в ответе.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Где тогда проверять права?</strong> В слое доступа к данным: функция, читающая заказ, сама проверяет, что он принадлежит текущему пользователю — тогда защита не зависит от маршрута. <strong>Можно ли запустить middleware на Node?</strong> В свежих версиях Next появилась экспериментальная поддержка Node-рантайма для middleware, но по умолчанию это Edge, и рассчитывать стоит на его ограничения.</p>`,
    code: `export const config = {
  matcher: ['/((?!api|_next/static|_next/image|favicon.ico).*)'],
};

export function middleware(req: NextRequest) {
  const token = req.cookies.get('session')?.value;
  if (!token && req.nextUrl.pathname.startsWith('/app')) {
    const url = req.nextUrl.clone();
    url.pathname = '/login';
    url.searchParams.set('from', req.nextUrl.pathname);
    return NextResponse.redirect(url);          // дешёвая проверка
  }
  const res = NextResponse.next();
  res.headers.set('x-nonce', crypto.randomUUID());
  return res;
}
// реальная проверка прав - в самом page/action, не здесь`,
    tip: 'Формулировка, которая заходит: middleware проверяет наличие токена, а не права. Права проверяются там, где происходит доступ к данным. Второй аргумент по делу: middleware срабатывает и на префетчах Link, поэтому широкий matcher - это реальные деньги и латентность.' },

  { id: 'rx57',
    q: 'Edge Runtime или Node.js Runtime — как выбираешь?',
    a: `<h4>Коротко</h4>
<p>Edge Runtime — урезанная среда на V8 isolates с Web API: есть <code>fetch</code>, <code>Request</code>/<code>Response</code>, <code>Web Crypto</code>, <code>TextEncoder</code>; нет <code>fs</code>, <code>net</code>, <code>child_process</code> и нативных модулей, плюс жёсткие лимиты на бандл и CPU-время. Берётся там, где <strong>важна латентность, а работы мало</strong>. Всё остальное — Node.</p>

<h4>Как это работает</h4>
<p>Edge-функция — не отдельный процесс, а изолят внутри уже запущенного рантайма, поэтому холодный старт околонулевой, а инстансы поднимаются в точках присутствия рядом с пользователем. Node-функция — полноценный процесс с холодным стартом в сотни миллисекунд и обычно один-два региона.</p>
<p><strong>Главная ловушка, о которой почти не говорят:</strong> если Edge-функция ходит в базу, живущую в одном регионе, выигрыш от близости <strong>обнуляется или становится отрицательным</strong>. Запрос летит от пользователя к ближайшему эджу (быстро), оттуда через полмира к БД и обратно (медленно), и так на каждый запрос в рамках обработки. Node-функция, стоящая рядом с базой, в этом сценарии быстрее. Edge выигрывает при данных, реплицированных глобально, при работе с внешними API или вообще без БД.</p>
<p>Что хорошо ложится на Edge: middleware, редиректы, A/B-тесты, геолокация и персонализация заголовков, простая проверка токена, стриминг ответа, лёгкие прокси. Что требует Node: ORM и драйверы БД, тяжёлые вычисления, работа с файлами, генерация PDF и изображений, любые пакеты с нативными зависимостями.</p>
<p>Выбор в Next — экспорт <code>runtime</code> из route handler или страницы; по умолчанию <code>'nodejs'</code>.</p>

<h4>Почему так</h4>
<p>Разделение — компромисс между скоростью старта и полнотой платформы. Изоляты дёшевы именно потому, что не дают доступа к файловой системе и сокетам. Попытка «сделать всё на Edge» упирается в это ограничение и заканчивается переписыванием слоя данных на HTTP-прокси перед базой.</p>
<p>Вторая цена — отладка и наблюдаемость: инструменты Node там недоступны, стек-трейсы беднее, лимит времени выполнения жёсткий, и превышение выглядит как обрыв ответа.</p>

<h4>Подводные камни</h4>
<ul>
<li>Edge плюс региональная БД — измеренная деградация вместо ускорения.</li>
<li>Импорт пакета с нативной зависимостью в Edge-модуль: сборка падает или падает рантайм.</li>
<li>Превышение лимита CPU: обрыв соединения без внятной ошибки.</li>
<li>Ожидание, что <code>process.env</code> работает так же: часть переменных недоступна, секреты пробрасываются иначе.</li>
<li><code>new Date()</code> и таймзоны: Edge-инстанс в другом регионе, локальное время отличается.</li>
<li>Переводить весь проект на Edge «для скорости» без замера — типичная ошибка.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как получить пользу от Edge с обычной БД?</strong> Кешировать на эдже то, что можно (ISR, CDN), а обращения к базе оставить Node-функции в её регионе. <strong>Как измерить разницу?</strong> Сравнить p75 TTFB из разных географий на реальном трафике, а не локально.</p>`,
    code: `// в route handler или page
export const runtime = 'edge';    // или 'nodejs' (по умолчанию)

// Edge: ок - нет БД, важна скорость
export const runtime = 'edge';
export async function GET(req: Request) {
  const country = req.headers.get('x-vercel-ip-country') ?? 'RU';
  return Response.json({ currency: country === 'RU' ? 'RUB' : 'USD' });
}

// Node: обязателен - ORM, нативные зависимости
export const runtime = 'nodejs';
export async function GET() {
  const rows = await prisma.order.findMany();
  return Response.json(rows);
}`,
    tip: 'Про обнуление выигрыша Edge при одном региональном инстансе БД почти никто не говорит. Это самый сильный аргумент в этом вопросе: запрос летит от пользователя к эджу быстро, а от эджа к базе через полмира - и суммарно выходит медленнее Node рядом с БД.' },

  { id: 'rx58',
    q: 'Как работает next/image изнутри и какие у него подводные камни?',
    a: `<h4>Коротко</h4>
<p>Компонент разворачивается в <code>&lt;img&gt;</code> с вычисленными <code>srcset</code> и <code>sizes</code>, указывающими на роут оптимизатора <code>/_next/image?url=...&amp;w=...&amp;q=...</code>. Сервер по первому запросу ресайзит через <code>sharp</code>, конвертирует в AVIF/WebP по заголовку <code>Accept</code> и кеширует. Две ошибки, которые чаще всего съедают Core Web Vitals: забытый <code>priority</code> на LCP-картинке и отсутствующий <code>sizes</code> при <code>fill</code>.</p>

<h4>Как это работает</h4>
<p><strong>Против CLS.</strong> Для локального импорта размеры известны на сборке и подставляются автоматически — место резервируется до загрузки. Для внешнего URL надо указать <code>width</code>/<code>height</code> либо <code>fill</code> с позиционированным контейнером и заданным <code>aspect-ratio</code>. <code>placeholder="blur"</code> для статических импортов генерирует base64-заглушку на сборке; для внешних нужен свой <code>blurDataURL</code>.</p>
<p><strong><code>priority</code> и LCP.</strong> По умолчанию всё грузится лениво и с низким приоритетом. Герой-изображение, которое и есть LCP-элемент, в этом режиме начинает грузиться позже, чем могло бы — метрика проседает на сотни миллисекунд. <code>priority</code> добавляет <code>fetchpriority="high"</code> и preload-ссылку. Ставить его надо ровно на одну-две картинки над сгибом, иначе смысл приоритета теряется.</p>
<p><strong><code>sizes</code> и <code>fill</code>.</strong> Без <code>sizes</code> браузер считает, что изображение занимает всю ширину вьюпорта, и выбирает самый большой вариант из <code>srcset</code>. На карточке шириной 300 px это означает загрузку 1920-пиксельного файла.</p>
<p><strong>Деньги.</strong> Оптимизация тарифицируется по количеству <strong>уникальных исходных изображений</strong>, а не по числу вариантов. Сузить <code>deviceSizes</code> под реальные брейкпоинты полезно для трафика, но на счёт влияет именно число разных исходников. Внешние домены обязательно перечисляются в <code>remotePatterns</code> — иначе оптимизатор станет открытым прокси.</p>

<h4>Почему так</h4>
<p>Компонент решает четыре задачи разом: адаптивный <code>srcset</code>, современные форматы, ленивая загрузка и резервирование места. Руками это делается, но забывается — особенно <code>sizes</code> и размеры.</p>
<p>Цена: инфраструктурная зависимость. Оптимизатор — это серверный роут, ему нужны CPU, диск под кеш и правильно настроенный CDN. При статическом экспорте он не работает вовсе. Если картинки уже оптимизирует внешний CDN (Cloudinary, imgix), правильнее задать свой <code>loader</code> или <code>unoptimized</code> и не платить дважды.</p>

<h4>Подводные камни</h4>
<ul>
<li>Нет <code>priority</code> на LCP-изображении — самая частая причина плохого LCP на лендинге.</li>
<li><code>priority</code> на всех картинках сразу: приоритет перестаёт быть приоритетом, конкуренция за канал.</li>
<li><code>fill</code> без <code>sizes</code> — загрузка максимального варианта.</li>
<li><code>fill</code> без <code>position: relative</code> у родителя — картинка растянется по ближайшему позиционированному предку.</li>
<li>Пустой <code>alt</code> у смысловых изображений; для декоративных <code>alt=""</code> как раз правильно.</li>
<li>Статический экспорт с включённым оптимизатором — сборка падает.</li>
<li>Незакешированный оптимизатор перед CDN: каждый запрос заново жмёт картинку.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как понять, что LCP — это картинка?</strong> В Lighthouse и в PerformanceObserver виден конкретный LCP-элемент. <strong>Что делать с картинками из CMS?</strong> Отдавать размеры из CMS вместе с URL и генерировать <code>blurDataURL</code> на сервере — иначе CLS вернётся.</p>`,
    code: `// LCP-изображение: priority обязателен
<Image src={hero} alt="" priority sizes="100vw" placeholder="blur" />

// fill: нужен позиционированный контейнер и sizes
<div style={{ position: 'relative', aspectRatio: '16/9' }}>
  <Image src={url} alt={title} fill
    sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
    style={{ objectFit: 'cover' }} />
</div>

// next.config
images: {
  remotePatterns: [{ protocol: 'https', hostname: 'cdn.example.com' }],
  deviceSizes: [640, 828, 1200, 1920],   // сузить = меньше вариантов и денег
}`,
    tip: 'Назови priority для LCP и sizes при fill как две ошибки, которые чаще всего съедают Core Web Vitals в реальных проектах. И добавь оговорку про деньги: биллинг оптимизатора считается по числу уникальных исходных изображений, а не по вариантам.' },

  { id: 'rx59',
    q: 'Что делает next/font под капотом и как он борется с CLS?',
    a: `<h4>Коротко</h4>
<p>Две вещи. <strong>Самохостинг</strong>: файлы шрифта скачиваются на сборке и кладутся в статику — в рантайме ни одного запроса к <code>fonts.googleapis.com</code>. И более интересное — <strong>автоматический fallback с <code>size-adjust</code></strong>: Next читает метрики шрифта на сборке и подгоняет системный фолбэк так, чтобы подмена не двигала вёрстку.</p>

<h4>Как это работает</h4>
<p><strong>Самохостинг</strong> убирает три вещи: лишнюю цепочку DNS + TCP + TLS к стороннему домену, render-blocking запрос за CSS с описанием <code>@font-face</code> (он всегда идёт до самого файла шрифта) и юридический вопрос — загрузка Google Fonts прямо из браузера пользователя в ЕС трактовалась как передача IP третьей стороне.</p>
<p><strong>Механика fallback.</strong> Next парсит файл шрифта и достаёт метрики: <code>unitsPerEm</code>, <code>ascent</code>, <code>descent</code>, <code>lineGap</code>, среднюю ширину глифа. Затем генерирует <code>@font-face</code> для локального системного шрифта (Arial на Windows, Helvetica на macOS) с подобранными <code>size-adjust</code>, <code>ascent-override</code>, <code>descent-override</code>. Итог: фолбэк занимает <strong>ровно столько же места</strong>, сколько займёт целевой шрифт, и момент подмены не сдвигает ни строки — CLS около нуля даже при <code>display: swap</code>.</p>
<p>Плюс сабсеттинг по указанным <code>subsets</code>. Для кириллицы обязательно <code>['cyrillic', 'latin']</code> — иначе русские символы не попадут в файл и будут отрисованы фолбэком, что выглядит как сломанная типографика на половине сайта.</p>
<p><strong>Ограничение:</strong> шрифт объявляется в <strong>модульной области</strong>, а не внутри компонента, — иначе сборщик не может статически проанализировать вызов и подготовить файлы. Локальные шрифты подключаются через <code>next/font/local</code>; вариативный формат предпочтителен — один файл вместо шести начертаний.</p>

<h4>Почему так</h4>
<p>Шрифты — классический источник CLS: текст сначала рисуется фолбэком, потом подменяется, и всё под ним сдвигается. Исторические обходные пути были плохими: <code>display: block</code> прячет текст на время загрузки (FOIT, страдает FCP), <code>display: optional</code> может вообще не показать нужный шрифт. Подгонка метрик решает проблему без выбора между невидимым текстом и прыжком.</p>
<p>Цена: шрифт становится частью бандла статики и версионируется вместе со сборкой; обновление шрифта требует пересборки. Плюс подобранные метрики — приближение: на очень длинных строках расхождение в переносах всё же возможно.</p>

<h4>Подводные камни</h4>
<ul>
<li>Забыть <code>cyrillic</code> в <code>subsets</code> — русский текст едет фолбэком, и никто не понимает почему.</li>
<li>Объявление шрифта внутри компонента — сборка ругается или шрифт не подключается.</li>
<li>Подключать шесть начертаний вместо вариативного файла: лишние сотни килобайт.</li>
<li>Использовать <code>@import</code> из Google Fonts параллельно с <code>next/font</code> — шрифт грузится дважды.</li>
<li>Отключить <code>adjustFontFallback</code> «чтобы точнее» — вернёшь CLS.</li>
<li>Не задать <code>variable</code> и завязаться на класс: тогда шрифт нельзя применить через CSS-переменную в дизайн-токенах.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Что такое FOIT и FOUT?</strong> FOIT — невидимый текст, пока грузится шрифт (<code>display: block</code>); FOUT — показ фолбэком с последующей подменой (<code>display: swap</code>). Подгонка метрик делает FOUT незаметным. <strong>Нужен ли preload?</strong> <code>next/font</code> добавляет его сам для используемых шрифтов; вручную дублировать не надо.</p>`,
    code: `import { Inter } from 'next/font/display';   // объявление на уровне модуля
const inter = Inter({
  subsets: ['cyrillic', 'latin'],           // без cyrillic русский уйдёт в фолбэк
  display: 'swap',
  variable: '--font-inter',
  adjustFontFallback: true,                 // подбор метрик фолбэка (по умолчанию)
});

export default function RootLayout({ children }) {
  return <html lang="ru" className={inter.variable}><body>{children}</body></html>;
}

// сгенерированный фолбэк выглядит примерно так:
// @font-face { font-family: 'Inter Fallback'; src: local('Arial');
//   size-adjust: 107.12%; ascent-override: 90.2%; descent-override: 22.5%; }`,
    tip: 'Механика size-adjust на основе метрик (unitsPerEm, ascent, descent), прочитанных из файла шрифта на сборке, - самая содержательная часть ответа. Просто самохостинг знают все. Практичная добавка: без cyrillic в subsets русский текст молча уезжает на фолбэк.' },

  { id: 'rx60',
    q: 'Как ты организуешь миграцию с Pages Router на App Router?',
    a: `<h4>Коротко</h4>
<p>Ключевой факт: <strong>роутеры сосуществуют</strong> в одном приложении, при конфликте пути выигрывает App Router. Поэтому миграция инкрементальная — по маршруту за раз, без большого взрыва. Начинать надо с наименее критичного лист-маршрута, чтобы отладить инфраструктуру, а не с главной страницы.</p>

<h4>Как это работает</h4>
<p><strong>Порядок шагов.</strong> Поднять Next и React до нужных мажоров, оставаясь на Pages, и убедиться, что всё работает. Создать <code>app/layout.tsx</code> — он заменяет <code>_app</code> и <code>_document</code>, теги <code>&lt;html&gt;</code> и <code>&lt;body&gt;</code> живут теперь здесь. Общие провайдеры вынести в клиентский компонент и подключить в корневом layout. Затем мигрировать один периферийный маршрут, прогнать его через прод, и только потом двигаться внутрь.</p>
<p><strong>Что переписывается механически.</strong> <code>getServerSideProps</code>/<code>getStaticProps</code> → async Server Component с обычным <code>await</code>. <code>next/router</code> → <code>next/navigation</code>: <code>useRouter</code>, <code>usePathname</code>, <code>useSearchParams</code>. <code>next/head</code> → экспорт <code>metadata</code> или <code>generateMetadata</code>. API routes → route handlers на Web-стандартах (<code>Request</code>/<code>Response</code>). В Next 15 <code>params</code> и <code>searchParams</code> стали промисами — их надо <code>await</code>-ить.</p>
<p><strong>Реальные грабли.</strong> Сторонние библиотеки без <code>'use client'</code>, падающие при серверном рендере, — оборачиваются в собственный клиентский модуль. CSS-in-JS требует отдельной настройки для RSC, а часть решений вообще не поддерживается — это может стать поводом переехать на CSS-модули или Tailwind. <code>useSearchParams</code> вынуждает обернуть компонент в <code>Suspense</code>, иначе весь маршрут становится динамическим и теряет статику. Дефолты кеширования изменились между версиями — их надо проверять, а не помнить. И нет эквивалента <code>router.events</code>: привычные прогресс-бары навигации приходится делать иначе.</p>

<h4>Почему так</h4>
<p>Инкрементальность — не любезность, а необходимость: App Router меняет не синтаксис, а модель — где выполняется код, что попадает в бандл, когда данные кешируются. Переписать всё разом означает поменять все эти оси одновременно и потерять способность понять, что именно сломалось.</p>
<p>Цена миграции честная: два роутера в одной кодовой базе какое-то время, дублирование части кода, невозможность пользоваться общим состоянием между ними (клиентский стор в Pages и в App — разные деревья). Поэтому период сосуществования лучше делать коротким и не растягивать на годы.</p>

<h4>Подводные камни</h4>
<ul>
<li>Начать с главной страницы: любая ошибка сразу в проде и на всей аудитории.</li>
<li>Тащить всё в клиент через <code>'use client'</code> на корневом layout — получишь Pages Router с лишними шагами.</li>
<li>Не обернуть <code>useSearchParams</code> в Suspense: маршрут молча теряет статическую генерацию.</li>
<li>Забыть, что <code>params</code> теперь промис, — ошибка проявится только в рантайме конкретного маршрута.</li>
<li>Оставить общий клиентский стор между роутерами и ждать синхронизации.</li>
<li>Мигрировать без метрик: не с чем сравнивать, и регресс LCP/TTFB заметят пользователи.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как сделать прогресс-бар навигации без router.events?</strong> Через <code>useLinkStatus</code> в свежих версиях либо через <code>loading.tsx</code> и <code>isPending</code> транзишена. <strong>Что делать с библиотекой, которая не работает в RSC?</strong> Обернуть её в собственный клиентский модуль с <code>'use client'</code> и не тащить эту границу выше, чем нужно.</p>`,
    code: `// было: pages/products/[id].tsx
export async function getServerSideProps({ params }) {
  const product = await getProduct(params.id);
  return { props: { product } };
}

// стало: app/products/[id]/page.tsx
export default async function Page({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;                  // Next 15: params - промис
  const product = await getProduct(id);
  return <ProductView product={product} />;
}

export async function generateMetadata({ params }) {
  const { id } = await params;
  return { title: (await getProduct(id)).title };
}

// useSearchParams требует Suspense, иначе маршрут станет полностью динамическим
<Suspense fallback={null}><Filters /></Suspense>`,
    tip: 'Скажи, что мигрируешь сначала неважный лист-маршрут для отладки инфраструктуры, а не главную. Это сразу читается как реальный опыт миграции. И назови главную мысль: App Router меняет не синтаксис, а модель - где выполняется код, что едет в бандл, когда кешируются данные.' },

  { id: 'rx61',
    q: 'Когда Next.js не нужен и лучше взять Vite + SPA?',
    a: `<h4>Коротко</h4>
<p>Критерий одной фразой: <strong>если нет SEO и нет требования к быстрому первому контенту для анонимных пользователей — SSR это чистый налог</strong>. Next окупается на публичном контенте, на метриках, влияющих на конверсию, и там, где серверные мутации нужны без отдельного бэкенда. Всё остальное дешевле собрать на Vite.</p>

<h4>Как это работает</h4>
<p><strong>Когда Vite + SPA лучше.</strong> Приложение целиком за логином — админка, дашборд, внутренний инструмент: индексировать нечего, а после логина всё равно всё динамическое. Приложение клиентское по природе — редактор, канвас, карта, IDE, чат: серверный рендер такого экрана бессмыслен. Нужен статический хостинг без Node — S3, nginx, GitHub Pages, закрытый контур без SSR-инфраструктуры. Команда маленькая, и специфика RSC (гидратация, границы сервер/клиент, слои кеширования) превращается в постоянный налог на каждую задачу.</p>
<p><strong>Что теряется.</strong> SEO — для лендинга решается пререндерингом или отдельным статическим сайтом. Первый контент на медленных сетях: SPA показывает пустой экран до загрузки бандла. Серверный доступ к секретам без собственного бэкенда.</p>
<p><strong>Что приобретается.</strong> Одна среда исполнения вместо двух — исчезает целый класс вопросов «почему это работает локально и падает на сервере». Предсказуемый деплой статики. Более простая отладка. И дешёвый хостинг.</p>
<p>Промежуточные варианты стоит называть: Vite плюс TanStack Router и TanStack Query покрывают почти все потребности SPA с типобезопасным роутингом; Astro — для контентных сайтов с островками React; связка «лендинг на Next плюс SPA на Vite за логином» — вполне рабочее разделение по зонам ответственности.</p>

<h4>Почему так</h4>
<p>SSR решает задачу доставки контента незнакомому пользователю по медленной сети до того, как загрузится JS. За логином этой задачи нет: пользователь уже вошёл, бандл почти наверняка в кеше, а данные всё равно приватные и не кешируются. Платить сложностью за нерешаемую задачу — это и есть определение оверинжиниринга.</p>
<p>Обратная сторона честности: выбор SPA закрывает дорогу к дешёвому SEO и к быстрому первому байту, а обратная миграция стоит дорого. Поэтому решение принимается по требованиям продукта, а не по вкусу — и его стоит зафиксировать письменно.</p>

<h4>Подводные камни</h4>
<ul>
<li>Брать Next «потому что стандарт» на внутренний дашборд — и полгода объяснять команде границы <code>'use client'</code>.</li>
<li>Брать SPA для публичного маркетингового сайта и потом чинить SEO костылями.</li>
<li>Считать, что SPA не нуждается в оптимизации: разделение бандла и приоритеты загрузки нужны и там.</li>
<li>Игнорировать, что Next тянет за собой инфраструктуру: Node-рантайм, кеш, мониторинг сервера.</li>
<li>Смешивать: SPA внутри Next «чтобы было» — платишь за оба подхода.</li>
<li>Не учитывать команду: незнакомый фреймворк стоит месяцев продуктивности.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>А если SEO нужен только для лендинга?</strong> Разделить: статический сайт или Next для публичной части, SPA за логином — граница проходит по домену или по пути. <strong>Как получить быстрый первый контент в SPA?</strong> Пререндеринг оболочки, критический CSS инлайном, разделение бандла по маршрутам и скелетоны вместо пустого экрана.</p>`,
    code: `// Признаки того, что Next не нужен:
// - всё за авторизацией, SEO не требуется
// - нет собственного бэкенда на Node (или бэкенд на Go/Java/Python)
// - деплой в закрытый контур без SSR-инфраструктуры
// - приложение стейтфул и клиентское по природе (редактор, дашборд реального времени)

// Признаки того, что Next нужен:
// - публичный контент, индексируемый поиском
// - маркетинговые метрики LCP/TTFB критичны для конверсии
// - нужны серверные мутации без отдельного бэкенда
// - ISR/кеширование контента снимает нагрузку с БД`,
    tip: 'Сформулируй критерий одной фразой: если нет SEO и нет требования к быстрому первому контенту для анонимных пользователей - SSR это чистый налог. И предложи разделение как отдельный вариант: публичный лендинг на Next, приложение за логином на Vite.' },

  { id: 'rx62',
    q: 'Сравни Next.js, React Router 7 (Remix) и TanStack Start. Что выберешь и почему?',
    a: `<h4>Коротко</h4>
<p>Три разные философии. <strong>Next</strong> — вокруг RSC: серверный рендер по умолчанию, границы <code>'use client'</code>, многоуровневое кеширование, Server Actions. <strong>React Router 7</strong> (в него влился Remix) — вокруг веб-стандартов: <code>loader</code>/<code>action</code>, Request/Response, прогрессивное улучшение. <strong>TanStack Start</strong> — вокруг типобезопасности: типизированные маршруты и search params как полноценное состояние.</p>

<h4>Как это работает</h4>
<p><strong>Next.</strong> Данные загружаются там, где рендерится компонент; кеш многоуровневый — Request Memoization, Data Cache, Full Route Cache, Router Cache. Сильные стороны: максимальная экосистема, готовые оптимизации (<code>next/image</code>, <code>next/font</code>, ISR), больше всего вакансий и материалов. Цена: модель кеширования сложна и её дефолты менялись между мажорами; код плотно завязан на фреймворк.</p>
<p><strong>React Router 7.</strong> Данные объявляются на маршруте: <code>loader</code> стартует параллельно с загрузкой чанка компонента, что структурно убирает водопады. <code>action</code> принимает <code>FormData</code>, работа идёт с нативными Request/Response. RSC не обязателен, хостится где угодно, ментальная модель самая простая из трёх. Цена: меньше готовых оптимизаций — часть вещей делается руками.</p>
<p><strong>TanStack Start.</strong> Ставка на end-to-end типы: путь, параметры и search params типизированы и валидируются схемой, а <code>useSearch</code> возвращает разобранный объект. Для дашборда с двадцатью фильтрами в URL это качественно другой уровень надёжности. Плюс глубокая интеграция с TanStack Query. Цена: молодая экосистема, меньше рецептов, выше риск ранних граблей.</p>

<h4>Почему так</h4>
<p>Критерий выбора по типу продукта. Публичный контентный продукт с требованиями к SEO и кешу — Next. Приложение с формами и классической серверной моделью, где важны простота и переносимость, — React Router 7. Дата-интенсивный дашборд с URL-состоянием — TanStack Start, осознанно как ранний адоптер.</p>
<p>И отдельный пункт, который стоит проговорить: миграция между фреймворками стоит дорого — это не библиотека, а модель данных, роутинга и деплоя разом. Поэтому «что уже знает команда» — легитимный технический аргумент, а не отговорка: полгода на освоение чужой модели дороже, чем недостающая фича.</p>

<h4>Подводные камни</h4>
<ul>
<li>Выбирать Next по инерции для приложения за логином — платишь сложностью RSC без выгоды.</li>
<li>Недооценивать кеш Next: неожиданно закешированный <code>fetch</code> — классическая продовая проблема.</li>
<li>Брать TanStack Start на критичный проект без запаса времени на неизбежные ранние баги.</li>
<li>Сравнивать по бенчмаркам «hello world»: разница видна на реальном приложении с данными.</li>
<li>Игнорировать вопрос хостинга: Next хочет Node или свою платформу, React Router разворачивается почти везде.</li>
<li>Считать, что RSC — обязательное будущее для всех: у роутер-лоадеров своя, вполне живая модель.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>В чём принципиальная разница loader и RSC?</strong> Loader объявляет данные на уровне маршрута и стартует их параллельно; RSC привязывает данные к компоненту и потому склонен к водопадам без ручной параллелизации. <strong>Что выберешь лично?</strong> Отвечай через требования продукта и опыт команды — универсального ответа нет, и интервьюер проверяет именно это.</p>`,
    code: `// React Router 7: loader/action на веб-стандартах
export async function loader({ params }: LoaderFunctionArgs) {
  return json(await getOrder(params.id));
}
export async function action({ request }: ActionFunctionArgs) {
  const form = await request.formData();
  return redirect('/orders');
}

// Next: async Server Component + Server Action
export default async function Page({ params }) { const o = await getOrder(params.id); }

// TanStack Start: типизированный маршрут и search params
export const Route = createFileRoute('/orders')({
  validateSearch: z.object({ status: z.enum(['new', 'done']).catch('new') }),
  loader: ({ deps }) => getOrders(deps.status),
});`,
    tip: 'Заверши мыслью, что стоимость миграции между фреймворками выше их технических различий, поэтому опыт команды - легитимный технический аргумент, а не отговорка. И проведи содержательную границу: loader объявляет данные на маршруте и стартует их параллельно, RSC привязывает данные к компоненту и потому склонен к водопадам.' },

  { id: 'rx63',
    q: 'Как ты делишь бандл на чанки в React-приложении и как избегаешь мигания при lazy-загрузке?',
    a: `<h4>Коротко</h4>
<p>База — <code>React.lazy</code> плюс <code>Suspense</code>: динамический импорт создаёт отдельный чанк, который грузится при первом рендере компонента. Естественные границы: маршруты (самое эффективное), тяжёлые модалки и редакторы, редко используемые библиотеки — графики, карты, WYSIWYG, генерация PDF. Мигание лечится <strong>префетчем</strong> и <strong>транзишеном</strong>.</p>

<h4>Как это работает</h4>
<p>Проблема наивного подхода в том, что загрузка стартует <strong>ровно тогда, когда компонент уже нужен</strong>: пользователь кликает и смотрит на спиннер, пока летит запрос за чанком.</p>
<p><strong>Префетч</strong> сдвигает старт раньше. По <code>onMouseEnter</code> и <code>onFocus</code> на ссылке — даёт 100–300 мс форы, чего обычно хватает. По видимости через <code>IntersectionObserver</code> — для блоков ниже сгиба. На <code>requestIdleCallback</code> после гидратации — для вероятного следующего шага. В Next это делает <code>&lt;Link&gt;</code> сам.</p>
<p><strong>Транзишен</strong> убирает мигание. Обёрнутый в <code>startTransition</code> переход заставляет React оставить старый экран до готовности нового вместо мгновенного показа фолбэка. На быстрой сети скелетон вообще не мелькнёт.</p>
<p><strong>Протухшие чанки.</strong> После деплоя старые хешированные файлы исчезают с CDN, и открытая у пользователя вкладка при ленивой загрузке получает 404 — белый экран. Лечится ретраем: перехватить ошибку импорта и перезагрузить страницу, либо держать предыдущую сборку на CDN некоторое время.</p>
<p>И мера предосторожности: делить надо по замеру. Три чанка по 5 КБ хуже одного на 15 КБ — накладные расходы на дополнительные запросы и на код загрузчика съедают выигрыш.</p>

<h4>Почему так</h4>
<p>Смысл разделения — не уменьшить общий вес, а <strong>сдвинуть его во времени</strong>: до интерактивности доезжает только то, что нужно на первом экране. Метрика, на которую это влияет, — TTI и INP на первом взаимодействии, а не общий размер сборки.</p>
<p>Цена: больше запросов, сложнее отладка (ошибка загрузки чанка выглядит как случайный сбой), и риск, что критический путь удлинится, если ленивый компонент оказался нужен сразу. Поэтому первое, что делят, — маршруты: там граница совпадает с намерением пользователя.</p>

<h4>Подводные камни</h4>
<ul>
<li>Ленивая загрузка компонента, который виден на первом экране, — вместо ускорения получаешь лишний запрос в критическом пути.</li>
<li><code>lazy()</code> внутри рендера родителя: промис пересоздаётся, компонент грузится заново на каждом рендере — объявлять только на уровне модуля.</li>
<li>Нет обработки упавшего импорта — белый экран после каждого деплоя.</li>
<li>Фолбэк другой высоты — CLS на каждом переходе.</li>
<li>Разделение без анализатора бандла: делят не то, а тяжёлая зависимость остаётся в общем чанке.</li>
<li>Дублирование общей библиотеки в нескольких чанках вместо выделения общего.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как понять, что делить?</strong> Анализатором бандла: ищутся крупные зависимости, попавшие в начальный чанк, — обычно это дата-библиотеки, графики и иконочные наборы, импортированные целиком. <strong>Как избежать спиннера совсем?</strong> Префетч на hover плюс транзишен: при быстрой сети переход выглядит мгновенным.</p>`,
    code: `const Editor = lazy(() => import('./Editor'));

// префетч по наведению - грузим до клика
function EditLink() {
  const prefetch = () => { void import('./Editor'); };
  return <a onMouseEnter={prefetch} onFocus={prefetch} onClick={open}>Редактировать</a>;
}

// переход без мигания фолбэком
startTransition(() => setRoute('/editor'));

// ретрай упавшего чанка после деплоя
const Editor = lazy(() =>
  import('./Editor').catch(() => {
    window.location.reload();
    return new Promise(() => {});
  })
);`,
    tip: 'Проблема протухших чанков после деплоя - реальная продовая боль, которую почти никто не упоминает. Назови её и решение с ретраем. И переформулируй цель: разделение не уменьшает общий вес, оно сдвигает его во времени - метрика тут TTI, а не размер сборки.' },

  { id: 'rx64',
    q: 'Что можно и что нельзя передавать между Server и Client компонентами? Как устроена граница?',
    a: `<h4>Коротко</h4>
<p>Граница задаётся директивой <code>'use client'</code> в начале файла и распространяется <strong>транзитивно вниз по импортам</strong>: всё, что импортирует клиентский модуль, тоже становится клиентским. Но она <strong>не распространяется через <code>children</code></strong> — серверный компонент, переданный пропсом, остаётся серверным. Пропсы через границу обязаны быть сериализуемыми.</p>

<h4>Как это работает</h4>
<p>Директива помечает точку входа в клиентский граф. Бандлер идёт по импортам от неё и всё найденное кладёт в клиентский бандл. Отсюда классическая ошибка: импортировать серверный компонент внутрь клиентского — он превратится в клиентский вместе со всеми своими зависимостями, включая ORM или SDK, которые в браузере не работают и весят сотни килобайт.</p>
<p><strong>Правильный паттерн — композиция через children.</strong> Клиентская обёртка (провайдер темы, аккордеон, табы, модалка) получает уже отрендеренное серверное содержимое пропсом. Серверный компонент рендерится на сервере, в клиентский бандл едет только обёртка.</p>
<p><strong>Что сериализуется:</strong> примитивы, массивы, простые объекты, <code>Date</code>, <code>Map</code>, <code>Set</code>, TypedArray, промисы, JSX-элементы и ссылки на Server Actions. <strong>Что нет:</strong> обычные функции, классы и их инстансы, <code>Symbol</code>, объекты с методами и прототипами, замыкания. Ошибка возникает в рантайме на рендере, а не на сборке.</p>
<p><strong>Безопасность.</strong> RSC-payload лежит в исходном коде страницы — его видно через «просмотр кода» без всяких инструментов. Значит проп <code>user={userFromDb}</code> утечёт целиком: внутренние флаги, хеш пароля, служебные поля. Передавать надо явно выбранные поля, а не объект «на всякий случай».</p>

<h4>Почему так</h4>
<p>Модель существует ради одной цели: держать в браузере только тот код, который там действительно нужен. Транзитивность границы — прямое следствие того, как работает бандлер: он не умеет частично выдёргивать модуль.</p>
<p>Цена: непривычная дисциплина импортов и неочевидные ошибки. Директиву легко поставить слишком высоко — на корневой layout — и обнулить всю выгоду, получив обычный SPA с лишними шагами. Плюс граница не видна в JSX: нужно помнить, какой файл клиентский.</p>

<h4>Подводные камни</h4>
<ul>
<li>Импорт серверного компонента в клиентский вместо передачи через <code>children</code>.</li>
<li><code>'use client'</code> на корневом layout или провайдере — весь сайт уезжает в клиентский граф.</li>
<li>Передача колбэка серверному компоненту — ошибка сериализации в рантайме.</li>
<li>Передача целого объекта из БД — утечка данных в HTML.</li>
<li>Директива не в первой строке файла (после импортов или комментария-лицензии) — не работает.</li>
<li>Ожидание, что <code>'use client'</code> означает «только на клиенте»: такой компонент всё равно рендерится на сервере при SSR, и <code>window</code> там нет.</li>
<li>Библиотека без директивы, использующая контекст, — падает при серверном рендере; оборачивается в собственный клиентский модуль.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Как передать функцию на клиент?</strong> Только как Server Action — она сериализуется как ссылка, а не как код. <strong>Значит ли <code>'use client'</code>, что компонент не рендерится на сервере?</strong> Нет: он проходит SSR для первого HTML, просто ещё и попадает в бандл и гидратируется.</p>`,
    code: `// ПЛОХО: импорт делает серверный компонент клиентским
'use client';
import ServerChart from './ServerChart';       // ServerChart уедет на клиент
export function Panel() { return <ServerChart />; }

// ХОРОШО: children остаются серверными
'use client';
export function Panel({ children }: { children: React.ReactNode }) {
  const [open, setOpen] = useState(false);
  return <div>{open && children}</div>;
}
// page.tsx (server)
<Panel><ServerChart /></Panel>                 // ServerChart рендерится на сервере

// ПЛОХО: весь объект из БД уедет в HTML
<ClientProfile user={userFromDb} />
// ХОРОШО
<ClientProfile name={user.name} avatar={user.avatarUrl} />`,
    tip: 'Скажи, что RSC-payload виден в исходном коде страницы, поэтому передача лишних полей объекта - это не только вес, но и утечка данных. И развей частое заблуждение: use client не значит «только на клиенте» - такой компонент всё равно проходит SSR.' },

  { id: 'rx65',
    q: 'Почему рендер в React должен быть чистым и что такое tearing?',
    a: `<h4>Коротко</h4>
<p>Конкурентный рендеринг даёт React право <strong>прервать, выбросить и перезапустить</strong> работу над деревом и отрендерить его несколько раз до коммита. Это корректно только если рендер — чистая функция. <strong>Tearing</strong> — прямое следствие нарушения: части одного кадра отрисованы с разными версиями внешних данных.</p>

<h4>Как это работает</h4>
<p>Планировщик рендерит дерево кусками, отдавая управление браузеру примерно каждые 5 мс. Между кусками может произойти что угодно: сработать таймер, прийти событие, обновиться внешний стор. Если компонент читает изменяемое значение <strong>напрямую в рендере</strong>, первая половина дерева прочитает старое, вторая — новое. Оба значения попадут в один коммит и в один кадр — пользователь увидит, например, цену 100 в списке и 120 в шапке одновременно. До конкурентного режима это было невозможно: синхронный рендер атомарен.</p>
<p>Что нарушает чистоту: мутация пропсов и внешних объектов, запись в <code>ref</code> во время рендера, чтение и запись DOM, вызов чужого <code>setState</code> в теле, изменение переменных модульной области, чтение <code>Date.now()</code>, <code>Math.random()</code>, <code>window.innerWidth</code> без стабилизации. StrictMode вызывает рендер дважды именно чтобы это всплыло.</p>
<p><strong>Лечение tearing — <code>useSyncExternalStore</code>.</strong> Хук принимает <code>subscribe</code>, <code>getSnapshot</code> и <code>getServerSnapshot</code>. React вызывает <code>getSnapshot</code> синхронно перед коммитом и сравнивает с тем, что было использовано при рендере; при расхождении он <strong>выбрасывает работу и перерендеривает синхронно</strong> с одним согласованным значением. Именно поэтому на этот хук переехали Redux, Zustand и Jotai.</p>
<p>Важное требование: <code>getSnapshot</code> обязан возвращать <strong>кешированное</strong> значение. Новый объект на каждый вызов даёт бесконечный цикл рендеров — React видит вечное расхождение.</p>

<h4>Почему так</h4>
<p>Чистота рендера — это цена, которую React берёт за прерываемость. Взамен даёт отзывчивость ввода при тяжёлых обновлениях, транзишены и Suspense. Без гарантии чистоты ни одно из этих свойств не работало бы предсказуемо.</p>
<p>Цена для разработчика: часть привычных приёмов из времён React 16 стала некорректной, хотя внешне продолжает работать. Баг проявляется редко и невоспроизводимо — только при удачном совпадении прерывания и внешнего изменения, — поэтому найти его постфактум почти невозможно. Дешевле соблюдать правило.</p>

<h4>Подводные камни</h4>
<ul>
<li>Чтение <code>window.innerWidth</code>, <code>localStorage</code>, глобального стора напрямую в рендере.</li>
<li><code>getSnapshot</code>, создающий новый объект, — бесконечный цикл вместо tearing.</li>
<li>Забыть <code>getServerSnapshot</code> — падение при SSR.</li>
<li>Запись в <code>ref</code> во время рендера «для оптимизации» — нарушение, из-за которого ещё и компилятор пропустит компонент.</li>
<li>Считать tearing теоретической проблемой: он воспроизводится на реальных приложениях с внешним стором и транзишенами.</li>
<li>Инициализаторы состояния с побочными эффектами: в StrictMode выполнятся дважды.</li>
</ul>

<h4>Что спросят следом</h4>
<p><strong>Почему до React 18 tearing не было?</strong> Рендер был синхронным и непрерываемым: всё дерево читало одно значение. <strong>Нужен ли useSyncExternalStore, если используешь Zustand?</strong> Нет, он уже внутри — писать его руками нужно для собственных подписок на браузерные API и внешние источники.</p>`,
    code: `// нарушение чистоты: мутация внешнего состояния в рендере
let renderCount = 0;
function Bad() {
  renderCount++;                      // побочный эффект в рендере
  return <div>{renderCount}</div>;
}

// tearing: чтение изменяемого внешнего источника напрямую
function Bad2() {
  return <div>{window.innerWidth}</div>;   // может отличаться между кусками дерева
}

// правильно: подписка через useSyncExternalStore
const width = useSyncExternalStore(
  (cb) => { window.addEventListener('resize', cb); return () => window.removeEventListener('resize', cb); },
  () => window.innerWidth,
  () => 1024                          // снимок для SSR
);`,
    tip: 'Определи tearing одной фразой: части одного кадра отрисованы с разными версиями внешних данных. Это точное определение, и его редко дают корректно. Добавь требование к getSnapshot возвращать кешированное значение - новый объект на каждый вызов даёт бесконечный цикл рендеров.' },
];
